window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20221222-6","meetingId":"r04-cm12","date":"2022年12月22日","dateIso":"2022-12-22","committee":"区民委員会","time":"午前１０時００分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)第１０７号議案、品川区印鑑条例の一部を改正する条例","agenda":"はじめに、(1)第１０７号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"改正の条例の第１８条ただし書で、別に規則で定める方法と定めているのですけれども、それで規則のほうで定めてマイナンバーカードを使うという形の定め方になっていますが、そのマイナンバーカードがどうしても必要なのでしょうか。それをお伺いしたいと思います。登録証を提示しないけれども、どのような事項を照合して相違ないことを確認することになっているのか、その点を教えていただきたいと思います。","respondent":"吉野戸籍住民課長","answer":"実際には、今回のオンライン申請なのですけれども、いわゆる印鑑登録証に代わってマイナンバーカードを使用することによりまして、そこで証明用のいわゆる暗証番号的なものを入力していただいて申請していただくのですけれども、そこではやはり申請書と同じように、名前と。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"確認","question":"そうすると、要するに名前と住所、ご本人ですよということを照合して、相違ないことを確認している。それだけのことだと理解したので、よろしいわけですね。分かりました。続けていいですか。それで、マイナンバーカード以外の方法では、その個人の照合は不可能なのかということと、それからマイナンバーカード以外の方法ということを考えなかったのかということもお伺いしておきたいのですけれども。","respondent":"吉野戸籍住民課長","answer":"ですので、いずれ、例えばウェブ会議とかが、今、大分盛んになってきておりますので、そういったところでの例えば顔認証であったりとか、そういったところの技術発展といいますか、そういったことは今後品川でもできるかもしれませんが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"意見","question":"私は、オンライン申請を認めることで区民の利便性が高まるということではよろしいのですが、やはりマイナンバーカードには多々の問題点、従来から指摘されているとおりで、その利用、普及を促進していくことにつながるという意味で反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-003"}]},{"id":"topic-02","title":"会議の運営上、予定表の順番を入れ替えまして、(3)第１０１号議案、令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"会議の運営上、予定表の順番を入れ替えまして、(3)第１０１号議案、令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"組むべきして組まれた予算だと思います。この商店街装飾灯維持支援金については、消費者物価指数が３０％上昇しているから３０％、従来の維持管理経費に３０％を掛けて支援金額を出したのだというような根拠が示されているのですけれども、この燃料費高騰対策支援金についてはそこら辺の根拠がどうなっているのか、算定の根拠をお伺いしたいと思います。そこら辺のことをお伺いしたい。以上３点です。","respondent":"遠藤商業・ものづくり課長","answer":"新型コロナウイルス感染症対応地方創生臨時交付金を充当、一般財源を使っていないというお話なのですけれども、財源をどこから持ってくるかというのは、私どもの課といいますか、ほかの所管で考える部分、歳入の部分になるので。","voiceIndex":25,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"算定根拠なのですけれども、おおむね妥当性があると言われましたが、大体この商店街に対して３０％を掛けて出したというようなものと同様に、この売上だったらこのぐらいの負担が増加しているだろうというようなことで、おおむね妥当だろうというような話なのでしょうか。そこら辺のことをお伺いしたいと思います。そういう点をちょっともう一度はっきりとお伺いしたいのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"各事業者、業種によってもいろいろなところが個別に支援策というのを出されているところでありますので、その辺を見ながら、今後も必要であれば私どものほうは支援策を今も考えておりますし、今後も検討し続けるというふうに考えているところです。","voiceIndex":27,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひ検討していっていただきたいと思います。やはり非常に厳しい経営を強いられているというのは事実で、それも運輸・水産に限らないということは事実だと思いますので、支援する業種は本当に拡大していただきたいと思います。しかも、区独自の財源というのも使う覚悟で、直接支援を私は考えていっていただきたいと非常に思っております。そのことを要望いたしまして、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"両方ともまさに時宜にかなった施策で歓迎するところなのですけれども、知らなかったという商店街、また中小企業の方たちが出ないようにしていただきたいと思うのですが、まずその辺については徹底的に広報していただきたいと思うのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"運送事業者等につきましては、この辺はこういうご要望をいただいたところもありますので、その団体を通じてだとか、もちろん一般的な広報とかホームページとか、こちらもしっかりやらせていただきまして、できる限り漏れのないようにといいますか。","voiceIndex":30,"id":"exchange-007"},{"speaker":"藤原委員","kind":"確認","question":"漏れがないようにしてくださいね。せっかくいい施策だから。それと、具体的にちょっと確認なのですけれども、まず品川区運送事業者等燃料費高騰対策支援金のほうなのですけれども、補正予算額のところの内訳で、想定件数が１,１００件となっているではないですか。これは具体的にどういうところから１,１００件と出したのか教えていただけますか。これで大大丈夫なのですか。","respondent":"遠藤商業・ものづくり課長","answer":"ですので実際には計算した結果、今回の金額で十分足りるというところで考えております。","voiceIndex":32,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"運送のほうなのですけれども、そこを具体的に伺いたいのです。運輸局に聞いて１,１００件というのは、１,１００件も品川区に事業者があるのですか。そこを具体的に教えていただきたいのです。例えば会社が１,１００件あるのですとか、そうではなくて、タクシーが何台あってとか、そういうので計算してこうなるのですよと。だから、２億２,２５０万円かかるのですと具体的に１,１００件が分からないので。","respondent":"遠藤商業・ものづくり課長","answer":"例えば、関東運輸局に確認したところ、これは届出が必要、許認可が必要になりますので、それで数字が分かったところで、例えばタクシー事業者ですと３３２件、貸切りバス事業者が７件、トラック運送事業者が１５０件、軽貨物運送事業者が５７８件、屋形船が１４件。","voiceIndex":34,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"そこの１つの例だけを伺いますが、タクシーが三百何十件というのは、三百何十会社があるということですか。タクシー会社が品川区内に３７０会社あるのですか。","respondent":"遠藤商業・ものづくり課長","answer":"個人事業主の方もいらっしゃるので、会社かと言うとちょっとまた微妙なところがあるのですけれども、それだけの少なくともうちのほうの助成の対象者がその件数という形になってあります。","voiceIndex":36,"id":"exchange-010"},{"speaker":"藤原委員","kind":"確認","question":"じゃあ最後に１個だけ確認です。運送業が一番数が多かったけれども、運送業も、いわゆる個人でやっている運送業も入れてということで、そういうものを全部含めて１,１００件になるということでよいのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ご指摘のように、そのような形で考えています。","voiceIndex":38,"id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そちらを見ると、産業の事業所数の数値が、平成１８年なのですが、１０年以上経ってもそれほど大幅に増加するとは思えないので一応これを見ると、運送業がそれほどないというか、６００件とか７００件とか、そのぐらいの数字が出てきていて、これは逆に言ったら事業所数なので、個人事業主も入っているのかなと思っていたのですけれども、こことの乖離はどう理解すればよろしいですか。","respondent":"遠藤商業・ものづくり課長","answer":"ご指摘いただいているところの資料につきましては、個人事業主が入っていないと聞いておりますので、ですので今回の予算ではさらに乗ったような形になっております。","voiceIndex":41,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"オンライン申請を原則にするということが書いてありますけれども、そうすると、会社なり個人事業主なりが申請してきたときに、売上がどの規模かというのは、どういった形で、あなたの売上が３,０００万円以下ですねとか、あるいは１億５,０００万円以上ですねというのはどういうところで判別するようになるのでしょうか。そのやり方です。","respondent":"遠藤商業・ものづくり課長","answer":"申請の段階で事業税の証明書と、それから確定申告を出されていると思いますので、そちらで確認するような形で考えております。","voiceIndex":43,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"その確定申告はいつまでの、年度はどこが対象になるのですか。","respondent":"遠藤商業・ものづくり課長","answer":"決算期はそれぞれ結構ばらばらかと思うのですけれども、一応決算期が２０１９年１月から今年、２０２０年１２月までの間、コロナ前も一応考えてということで、その中のどこかの決算期のものを出していただければです。","voiceIndex":45,"id":"exchange-014"},{"speaker":"本多委員","kind":"質問・要望","question":"すみません、区民委員会の所管ではないのですが、以前、補正予算で銭湯の浴場について、区の補正予算としては銭湯の浴場に１か所当たり１０万円掛ける１２か月で１２０万円という積算だったのです。今回この補正予算で、１０万円から４０万円の区分で支援金ということなのですけれども、１回で幾らという、１２か月とかいう単位ではなくて１回という、その辺の考え方を教えていただきたいのですが。","respondent":"遠藤商業・ものづくり課長","answer":"その中でどうしてもちょっとまとめなくてはいけない部分がありますので、今回は取りあえず１０万・２０万・４０万という、他区の状況なども参考にしながらこういう設定にさせていただいたところです。","voiceIndex":47,"id":"exchange-015"},{"speaker":"本多委員","kind":"質問","question":"もう一つなのですけれども、運輸・交通分野でそれぞれ質疑で分かりましたけれども、例えば貸切バス事業者が入られていますけれども、民間の路線バスとかは対象外ではないですか。その辺の運輸・交通分野の全てとか、水産業分野の全てとかではなく、何かその網羅できていない部分の線引きは、どうしても行政ですからどこかで線引きするのは理解できますが、どういう考え方で線引きをされたのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"今回の貸切バスは大丈夫だけれども、いわゆる路線バスみたいなものは対象でないというところですが、路線バスを運営しているところは比較的に大手のところで、私どもの支援の対象ではないというところが多いと考えているところがあります。","voiceIndex":49,"id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"分かりました。それぞれおくの委員からもお話が出ましたが、先ほどの答弁で他の自治体を参考にしていろいろ考えていただいているようですので、他の自治体も各分野、業種、幅広く支援が進んでいるところもありますので、さらに支援を、燃料に限らず電気、水道、全ての高騰に対する支援を幅広く全庁的に進めていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"},{"speaker":"小芝副委員長","kind":"質問","question":"私のほうから、商店街装飾灯維持支援金のところで若干お聞きしたいと思います。対象の商店街、８２商店街ということなので、こちらのほうは規模は問わずという、例えば商店会、または商店街振興組合という規模がたくさんあると思います。これはもう規模は問わずという認識でよろしかったでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"全ての商店街を対象とさせていただいています。","voiceIndex":52,"id":"exchange-018"},{"speaker":"小芝副委員長","kind":"質問・要望","question":"ただ、もう少し待っていればなというところでもあるのですけれども、やはり一度撤去してしまったまちにある小さな規模の商店街にも、ぜひ、これはあくまでも既に電灯を保有している商店街が対象ということなのですけれども、既にこの電灯をなくしてしまった、撤去してしまった商店街にも何かしらの支援を検討していただきたいと思うのですけれども、その辺のお考えについて教えていただけますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"しかし、昨年度に撤去してしまったところにつきましては、申し訳ないのですけれども、今回はちょっと対象外という形になるところあります。","voiceIndex":54,"id":"exchange-019"}]},{"id":"topic-03","title":"第１１５号議案、指定管理者の指定","agenda":"第１１５号議案、指定管理者の指定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"指定管理者の指定、議案そのものではないのですが、この荏原平塚総合区民会館、スクエア荏原ですね。それで、やはりその他の施設のように料金を引き下げていただければありがたいという声もありまして、これを指定管理者の努力で引き下げられないものなのかという、区側もそういう努力を促すというか、区側からもそういうふうにしていただけないものなのか、その辺をお伺いしたいと思います。","respondent":"篠田文化観光課長","answer":"確かに地域センター、区民集会所と比べると、高く捉えられる方もたくさんいらっしゃるのですけれども、施設としても非常にその他の集会所とはまた一段グレードの高い施設ということもありますので、ご要望として承らせていただきまして、今後、場合によっては利用料金等。","voiceIndex":71,"id":"exchange-020"},{"speaker":"おくの委員","kind":"質問・要望","question":"要望として申し述べておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-021"},{"speaker":"藤原委員","kind":"提案","question":"この詳しい報告書なのですけれども、６番の選定理由で、１０年間の実績がありますと、とても安定しているのだと、経験に裏づけられているのだと、すごく評価が高いではないですか。しかし、７ページの(６)の選考基準に基づく採点表は、提案内容の評価は満点が４８０点で３４０点です。総合点数が満点５００点で３５２点ではないですか。このぐらいの点数で、これだけ評価する選定理由になるのでしょうか。","respondent":"篠田文化観光課長","answer":"私どももこの審査にあたりましては、最低でも６０％の得点は取らないと、指定管理者として指定するのは難しいだろうと思っていたのですけれども、最終的には７割のご評価をいただいたです。","voiceIndex":74,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"そうですか。１者ですか。初めに指定管理というような制度を導入したときには、民間にいろいろプロポーザルして、切磋琢磨していいものを、だから指定管理は５年ごとにとかね。１者。この事業は、民間の方が魅力がなくて申し込んでこないかもしれない。しかし、１者しか申込みがないというのは、やはり私個人としていかがなものかという思いがあるのですけれども、最後に担当としてはどう思いますか。","respondent":"篠田文化観光課長","answer":"その辞退された経緯につきましては、追跡調査等をしているわけではないので正確な理由は私どもも把握しているところではないのですけれども、募集にあたってお示ししている資料の中では、例えば過去５年間の指定管理料について参考情報としてご提示しているのですけれども。","voiceIndex":76,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"だってこれだけの資料を見ると、最初の答弁ではもう１者しかなかったのですというふうになってしまうじゃないですか。この資料で審議するわけですから。だからその辺も、今度代わるのが令和１０年ですから、そのときには募集をかけて何者応募が来て、そこから何者に絞られて何者になったのですという形で、ちゃんと分かりやすくその辺は報告していただきたいと思いますが、いかがでしょうか。","respondent":"篠田文化観光課長","answer":"私どもも当初、どういう形でご説明させていただこうかと考えたときに、実は正式に応募があったのは最終的には１者だけになってしまったということもあるものですから、初めに５者というのも意向を示されたという状況だったものですから。","voiceIndex":78,"id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"今日、何でそういう質問をするかというと、実は今回常任委員会で、５つのうちたしか３つ指定管理者に関する議案が出てきているかと思います。その辺りがやはりちゃんと出てくると、我々もさらにしっかり審議できるのかなと思いますので、次回、必ずしもこのスクエア荏原に限らずほかの指定管理の議案が出てくる際には、できるだけその募集要項とかまでお出しいただければ思いますので、いかがでしょうか。","respondent":"篠田文化観光課長","answer":"私どもも今回ご説明するにあたって、資料はどういったものでご説明をしようかと思ってちょっと考えたのですけれども、今回こういう形にさせていただいたのは、実は募集要項ですとか、あとは指定管理要求基準書といったものに基づいて募集をかけたのですけれども。","voiceIndex":80,"id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"２点あって、今のお話で、その募集要項というのは今はもうインターネット上に公開されているのでしょうか。もしそうであれば、我々もそこにアクセスできるのかなというのが１点。これはもう行政側というよりもやはり区議会ですね。","respondent":"篠田文化観光課長","answer":"こちらにつきましては、例えば、委員会でのご審議に関しては最小限の資料を紙でご用意させていただいて、別途そういったタブレット配信ができるかどうかというのは、議会運営の関係もありますので、事務局のほうとも相談しながら、そういった手法が可能であれば。","voiceIndex":82,"id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"我々は政務活動費をもらっているわけですから、データでもらったものを必要な人が政務活動費を使って印刷すればいいのに、なぜこの品川区議会はまだそれができていないのかということを意見として申し上げて、私の質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問","question":"１点だけちょっとお伺いしたいのですけれども、７ページの委員の意見の一番最後、稼働率の向上についてもっと努力をしてほしいというようなことがあります。","respondent":"篠田文化観光課長","answer":"実は、私も以前スクエア荏原の館長をさせていただいたことがございまして、その頃からやはり何とか借りていただけるようにということで、例えば、大した話ではないのですが、リピーターを増やしていきたいということで。","voiceIndex":85,"id":"exchange-028"}]},{"id":"topic-04","title":"令和元年請願第２１号、選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","agenda":"令和元年請願第２１号、選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"最高裁は夫婦同姓を２度支持したということが、大変重要なことだと思います。それで質問は、ここ２０年あまり、旧姓の通称使用というのが拡充をされてきておりますけれども、品川区内を見て、この旧姓の通称使用というものが、私は品川区内を見たときに何の問題もないと思っているのですけれども、その辺の感触をちょっと教えていただきたいと思います。","respondent":"吉野戸籍住民課長","answer":"先ほどの説明の中で、４月のときの７６１名から、今回は９３７名ということで若干増えていらっしゃいますので、そういった意味でいきますと、こういったところで使用していきたいという方が増えてきているのかなという感触でおります。","voiceIndex":103,"id":"exchange-029"},{"speaker":"本多委員","kind":"意見","question":"その拡充はもう本当にすごくそういう手応えがあると思うので、私もそう感じるのですけれども、本当に何も問題ないのではないかなと思って、ちょっと聞かせていただきました。それで意見をちょっと述べますと、夫婦別姓に対する課題ですね。それと、またその制度が導入された場合、改めて姓の選び直しに混乱を来たす等々課題があるなということを述べて、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-030"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうでないと、これは来年４月にはもう選挙になってしまいますから、今日継続ということになると、廃案になってしまいますので、この請願はせっかくの請願ですから、やはり採決して採択ということで、ぜひとも採決していただきたいと私は思っております。ですから、私の父親だけ奥野という姓で、ほかの両親も、つまり私の祖父母ですね。ですから、そうしませんかと皆さんにお訴えしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"私たちは区議会議員なので、国に要望、意見書を上げるときも、区民からどういうふうな意見が出てきているのかというところが大事かと思います。少なくとも態度は表明するべきかなと、採決で最終的に反対の方が多いということはあり得ると思いますけれども、では品川区議会としてこの本件についてどう考えているのかというところには、結論を出したほうがいいのではないかいうふうに意見を申し述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-032"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今弁護士の方から弁護士の立場でお話があったみたいなのですが、私は小児科医なので、子どもの立場から話をしたいのですけれども、これは子どもの立場だったら、子どもの考えとかはどこかに反映されているのでしょうか。例えば子どもというのは、父親と母親が別姓になったときに選ばせられるのでしょうか。その子どもの悲しみとかはないのですか。子どもの立場というのはどこにあるのですか。","respondent":"吉野戸籍住民課長","answer":"お子さんに関しましては、それで決まった氏を変更することができるかというようなこともＱ＆Ａには載っているのですけれども、こちらのほうでは通常未成年のお子さんが両親のいずれか一方の氏に、例えば離婚のときに自分の氏を両親のいずれか一方の氏に変更するためには。","voiceIndex":108,"id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"質問","question":"子どもの権利条約はどうなっているのですかね。私の質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"今の点、出ましたので伺いたいのですけれども、両親が離婚する際に子どもの意見は反映されるような仕組みになっているか伺います。両親が離婚する際に、氏を子どもがどうするかについて、子どもが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"離婚をする際に、子どもが自分の氏をどうするのか決められるような仕組みになっているのか伺います。","respondent":"吉野戸籍住民課長","answer":"こちらのほうは、お子さんが成年に達したときに、特別な事情がなくても家庭裁判所の許可を得ることはできるというふうに書かれておりますので、未成年ですと、その辺はご両親の判断によるのかと思います。","voiceIndex":112,"id":"exchange-036"},{"speaker":"松本委員","kind":"質問","question":"そういう意味で言うと今の現状も、離婚についても子どもの意見ははたして出せるのか。子どもから、お子さんの相談があって、自分の氏を変えたいと。なので、子どもの意見ということをこの選択的夫婦別姓、別氏の議論の中で考えるにあたっては、では離婚のときはどうするのかということも考えなくてはいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-037"},{"speaker":"松本委員","kind":"意見","question":"何が別なのかはさっぱりよく分からないとは思います。そちらについても、子どもの意見ということを言うのであれば、きっちりとその離婚制度、例えば共同親権もそうですけれども、そちらの議論もしっかりとしていかなければならないというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"ちょっと質問なのですけれども、今回の資料に令和３年に実施した「家族の法制に関する世論調査」の結果ということが出ていて、これは設問の内容がそれ以前の内閣府の調査と変わったということで、令和元年にまたこの請願の審査をされているときにも少し議論になったと思いますけれども、その説明の中身が、聞き方が変わったことによって出てきたこの調査への影響というのは。","respondent":"吉野戸籍住民課長","answer":"平成２９年度のときは、法律を改めても構わない、いわゆる夫婦は同じ名字を名のるべきで、法律を改める必要はないとか、そういった内容だったのですけれども、令和３年度はちょっと一歩踏み込みまして、夫婦同姓維持というような、維持をすべきという形になっておりまして。","voiceIndex":116,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"戸籍住民課の立場でなかなか答えにくいかもしれませんけれども、その設問が変わったことが、それまでの世論調査の結果に何かしらの大きな影響を与えるものだったかどうかというところで、私は結果に対してそこまで何か大きな変更が起こるような、変化が起こるようなものでもなかったのかなとは個人的には思っているのですけれども、そこら辺に対する見解みたいなものはどうでしょうか。","respondent":"吉野戸籍住民課長","answer":"行政側としましては、やはり国の動向と、あと他自治体の動向をやはり注視させていただきたいと考えています。","voiceIndex":118,"id":"exchange-040"},{"speaker":"小芝副委員長","kind":"質問","question":"４つの項目が多岐にわたって質問形式でありまして、全体のアンケートの結果として、この夫婦同姓の制度の維持と、夫婦同姓の制度を維持しつつ通称使用の法制度を設ける。その結果、この約７割以上の方が夫婦同姓の制度を維持していきましょうという結果になっていると思うのですね。もちろん賛成の意見もありますけれども、議論は続けていくべきであるかなと思いますので、意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"意見","question":"世の中というのはいろいろ流れていくもので、時代によっていろいろ考え方が変わっていくというのは、それはよく分かる。明治時代と昭和も違うし、昭和と令和も違うし。ほとんどの人がちゃんとそれはそうだと受け入れられるような形でだんだん世の中というのは変わっていくべきものだから、少量の声が大きい人の意見がそのまま通ってしまうような社会というのは、非常に私は危険だと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-042"},{"speaker":"塚本委員","kind":"意見","question":"最初にちょっと意見を述べさせてもらいますけれども、公明党としては、この選択的夫婦別姓制度については導入するということで、たびたびいろいろなところで表明している立場です。それは結果としていろいろな分断を生んだりするということは、決して価値的なものではないと思います。まだ結論を出すには早急だというふうに判断して、継続でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-043"},{"speaker":"おくの委員","kind":"質問・要望","question":"この請願、選択的夫婦別姓制度の導入を求めるのではなくて、やはり国会審議を求めている。たくさんの賛否、いろいろな意見がある中で、国会で審議してくださいという、審議を求めている請願なのですから、私は採決をとって採択ということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-044"},{"speaker":"藤原委員","kind":"意見","question":"これ、意見書をということなのですけれども、これは物すごく大事なことだと思うのですね。私はまだ審議していかなくてはいけないと思っていますし、もし出すということであるならば、やはり全会一致で出すべきことだと私は思います。なので、継続。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-045"},{"speaker":"松本委員","kind":"質問・要望","question":"先ほど意見は申し上げましたが、もう一度申し上げると、もう既に法制審議会が要望を出したのが平成８年ですので、時代の流れもある。やり方は国会のほうでしっかりと審議していただければと思うのですが、審議自体がほとんど進んでいないという事態に対して区民の意見も踏まえると、やはりそこは進めていただきたいと考えていますので、本日結論を出す、そして採択というふうに申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2946#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":33319,"voices":139}},{"id":"r04-20221222-7","meetingId":"r04-cm12","date":"2022年12月22日","dateIso":"2022-12-22","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０１号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１０１号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田委員","kind":"質問","question":"それで、この米印のところで、「東京都実施の集中的検査実施事業所の対象となるものを除く」というようにあるのですけれども、そうしたらこの東京都実施の対象事業所はどれぐらいあるのか伺いたいということと、この検査キットの予算額のところの回数が、障害者のほうは３,５００回分、介護のほうが１万５,０００回分ということで、この回数が大分大きく違うのですが。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"ホームページにも実施されている施設は公表されております。それ以外のところは、全て区のほうでも検査キットを配布していくということになっております。現場のほうが困らないように対応していきたいと考えています。こちらの検査キットの対象施設については、区内の全ての事業所が対象になりますので、この支援金の対象外となるところ、具体的には訪問系の事業所などが、支援金の対象となっておりませんが、検査キットのほうでは対象ということで。","voiceIndex":11,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、物価高騰対策支援金ですけれども、やはり電気・ガス料金にという周知をしていくということですが、何というのですか、電気、ガスに本当に使われたのかというようなところまで、事業所のほうから出させるというような仕組みではなく、電気、ガスに使ってくださいという形のものなのか、その辺だけ確認させていただきたいということと、障害者の福祉タクシーのほうも新たに質問したいのですけれども。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"今回この補助単価を算出するに当たりまして、先ほど障害者支援課長からご説明ありましたが、例えば高齢者の場合は、入所・入居系と通所系別に、令和３年の４月から８月分の電気。今回、タクシーの利用券の追加発行となりますと、年度内での執行というものが困難であることから、相当分ということで、区内共通商品券で対応させていただいたものです。","voiceIndex":14,"id":"exchange-002"},{"speaker":"石田委員","kind":"意見","question":"分かりました。区内共通商品券は、そうすると一部のタクシー会社では使えないけれども、そのタクシーにかかってしまった分を生活のほうで、このような区内共通商品券で補っていただけたらということなのですね。分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-003"},{"speaker":"いながき委員","kind":"確認","question":"今の福祉タクシー券に関して追加で質問なのですけれども、ごめんなさい、私がどのような方が対象者となっているか、ちょっと分からないので、そこの確認をしたいということと、福祉タクシー等助成券とあって、福祉タクシーというと、私の感覚だと車椅子の方がご利用になるのかなと思ってしまうのですけれども、例えば視覚障害者の方なども移動のためにタクシーを使われていると思いますが。","respondent":"松山障害者支援課長","answer":"こちら、いわゆる身体障害者手帳をお持ちの方のうち、下肢ですね。下肢と体幹機能障害３級以上の方、視覚障害２級以上の方、内部障害１級の方、愛の手帳２度以上の方ということで、障害があるために外出困難な方ということを対象にしております。","voiceIndex":19,"id":"exchange-004"},{"speaker":"いながき委員","kind":"確認","question":"確認なのですけれども、対象の方たち全員が、配られている方たちには申請なしに、自動的に配られるのですか。団体に属している方だけとか、何かそのような決まりではなくて、これまで対象だった方たちには個別に、新規の方は別としてですけれども、今までの方に対しては自動的に配られるということでいいのでしょうか。","respondent":"松山障害者支援課長","answer":"追加交付の対象者、タクシー券についてのご質問です。今のところ、令和５年１月１日付で福祉タクシー利用券の助成を受けている方、もしくは自動車燃料費助成を受けている方全員に対しまして、追加で区内共通商品券を周知文とともに送付する予定です。","voiceIndex":21,"id":"exchange-005"},{"speaker":"いながき委員","kind":"確認","question":"確認なのですけれども、そうしたら、今まで配られている視覚障害などの方たちには、自動的に申請なしで配られるということでいいでしょうか。","respondent":"松山障害者支援課長","answer":"申請なしに、全員の方を対象に交付する予定です。","voiceIndex":23,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"意見","question":"必要なのですけれども、幾つか項目の中に雇用の維持等もあったのですが、従事される方々への支援という意味で、今回の補正のときの国の方向性では、雇用に関係するものには出せないものだったのかということが１つです。もう一つは、区として従事されている方々への支援という観点で、この交付金を使おうという選択があり、しかし、いろいろな事情でできなかったのかというところをお尋ねします。","respondent":"松山障害者支援課長","answer":"従事者に対しましては、処遇改善加算等も今年度アップされたということもありますので、また社会情勢を鑑みまして、今後各事業所の従事者への支援というものを検討していきたいと考えております。","voiceIndex":26,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"今までにも、従事される方の処遇改善という形でもやっていただいていたということは大変ありがたいことなのですが、今回こういった交付金があるということで、かなり、何というのですか、使い道も広いし、そのようなことが、もちろん物価高騰に対する事業者への支援は絶対必要なのでやっていただくとして、その一方で。","respondent":"菅野高齢者福祉課長","answer":"区全体としても、いろいろな部分で今回補正予算を組ませていただいていると思いますが、その中で、区全体の枠の中で見させていただきましたので、従事者に対するという支援については、今回については俎上には上がらなかったということが事実ですが、今後。","voiceIndex":28,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"最後ですけれども、障害者支援課長も、高齢者福祉課長も、今後も支援を考えていくというように言っていただけたので、ぜひ今年度、間に合えば何かの施策をし、そして来年度の予算の中で計上していっていただければよろしいかと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"},{"speaker":"あくつ副委員長","kind":"提案","question":"障害福祉サービス事業所物価高騰対策支援金のほうで、先ほど石田委員の質問で確認したいことは幾つかお尋ねしていただいたのだけれども、念のための確認で、先ほど高齢者福祉課長のほうから、今回の予算額の算出根拠が示されたのですが、基本的に入所、通所系、そこについては１人当たりの単価は一緒ということなのですが、障害者のほうでは訪問・相談系サービスが５,０４０円ということで。","respondent":"松山障害者支援課長、若生健康課長","answer":"そういった声は特別区の課長会の中でも話題になっておりまして、なかなか品川区だけで進められることではございませんので、今後とも検討していくべき課題だと認識しております。毎月特別区の課長会のほうで集まった際に情報共有しているのですけれども、やはり今回、第４回定例会のほうで、その燃料高騰に対する補助を検討している、もしくは上程したというような情報が区のほうにも入ってきているような状況です。","voiceIndex":32,"id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"タクシー券のデジタル化ということは、ぜひ進めていただきたいなと思います。公衆浴場については、やはり私の地域でも年々減ってきて、昔から行っていたところがなくなってきているところもあって、やはり一定程度、これは必要な方たちもいらっしゃるので、このようなことは折に触れて、最後お声があったということでしたけれども、しっかり聞いていただいて、前向きに進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"先ほど介護のほうの事業所支援のところで、物価高騰の支援金の対象に訪問系は入っていないということだったのですけれども、これはなぜ入っていないのかなという、そこだけお答えをいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区としてはそういった判断をして作業を進めていたところ、ここに来て、東京都のほうでは、訪問系につきましての１台当たりの支援金というところで、ガソリン代に相当する補助金を直接補助という形で。","voiceIndex":37,"id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひ積極的に区として進めて、支援していただきたいなと思いますし、先ほど高橋しんじ委員からもありましたけれども、従事されている皆さんというものも、本当にこのコロナで、東京都で感染者がまた２万人を超えた状況ですので、本当に大変な中で業務に当たられています。ぜひ当たられている方への支援というものも、再度していただけたらなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-013"},{"speaker":"いながき委員","kind":"質問","question":"公衆浴場のところで聞きそびれてしまったのでお尋ねをしたいのですが、歳出の１２か月というものが、今年の令和４年の４月から、来年の令和５年の３月までの１年間で、遡っての支援金ということでよろしいのでしょうか。","respondent":"若生健康課長","answer":"支給対象月が、令和４年、今年度の４月に遡って、そこから１２か月、来年の３月分までを一括で支給するというような形で考えてあります。","voiceIndex":41,"id":"exchange-014"}]},{"id":"topic-02","title":"令和４年請願第１５号、補聴器購入費助成制度を求める請願","agenda":"令和４年請願第１５号、補聴器購入費助成制度を求める請願","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"それで、まずは正しい知識の普及啓発というようにおっしゃっているので、具体的に正しい知識とは、この請願の中にもあるのですけれども、耳の聞こえが悪くなってきたということが、なかなか自分でも周りでも気づきづらいので、区としてもチェックリスト、チェックシートをつくり出したということも伺ったのですが、そのようなことから始まり、それで受診をして、では補聴器が必要になったといったら。","respondent":"川原高齢者地域支援課長","answer":"はご自身で耳の聞こえについて異常というか、何か気になるところはないかというところを知っていただくこと、そして知った上で、ご自身のかかりつけ医を受診していただくというところをまず進めているところです。","voiceIndex":57,"id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。個人任せにせずに。ですから、それが認知症予防にもつながっていくということを区もお認めになられているので、そういった流れをつくっていっていただきたいなと思うのですけれども、そこはいかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"現在、品川区医師会、あとは荏原医師会の先生と、その辺りはお話をしています。各医師会のほうに補聴器の相談医の先生がいらっしゃいますので、相談医の先生と情報提供の仕方、また、そのリストの在り方等については、現在意見聴取を行っているところです。","voiceIndex":59,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"ですから、港区などはまさにそのような例だと思うのですけれども、この補助制度を使うことで、正しい知識も普及啓発されていく、フォローアップもされていくというようになると思うので、そのような枠組みにしていただきたいなと。そうすると、もうすぐに進められるのではないかなと思うのですけれども、そこはいかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"購入するありきではなく、購入の前段階で、購入に当たってどういったところを気をつけなければいけないか、購入後どういったところを自分で行わなければいけないか、フィッティングの方法も含めて、そういったところも事前に知識として提供できるような形で考えてあります。","voiceIndex":61,"id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"私たちとしては、早急にこの補聴器購入費助成制度、実施していただきたいと思っているのですけれども、そうすると、この正しい知識の普及啓発というものは、大体いつぐらいまで、何というのですか、どの辺で実施していこう、そのためにはこれが今必要で、このような準備が必要だというようなものがあると思うのですが、実施の目標というものはあるのか、それと、そのように検討を重ねていく中で。","respondent":"川原高齢者地域支援課長","answer":"実施までに向けてのご質問です。区といたしましては、助成の実施に向けて、現在検討を進めているところです。","voiceIndex":63,"id":"exchange-018"},{"speaker":"石田委員","kind":"質問","question":"分かりました。調整されているというところではいいのですけれども、本当に実施されるのかなということがすごく不安で、実施に向けて、今様々やられているということですので、そこは否定しないのですが、ぜひ来年度から、新年度からというようにこの請願書にもありますけれども、そこに向けて、来年度実施できるかどうかということも今の段階ではもう全く分からないということですか。教えてください。","respondent":"川原高齢者地域支援課長","answer":"実施に向けての、来年度できるかというところのご質問です。来年度の実施に向けて、現在取り組んでいるところです。","voiceIndex":65,"id":"exchange-019"},{"speaker":"いながき委員","kind":"質問","question":"すみません。今医師会の調整が必要というお話だったのですけれども、具体的にどのような調整が必要で、どこが難航しているかなどということは分かるのですか。","respondent":"川原高齢者地域支援課長","answer":"現在の時点で、何か大きな壁というか、変更というところでは、今起きてはいないのですけれども、実際に助成をする前にいろいろな聴力の検査ですとか、細かい事務のところの話合いをしています。大きな壁というところは、現時点ではまだございません。","voiceIndex":68,"id":"exchange-020"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"確認ですけれども、本年第２回定例会の一般質問で、私どもの会派から、先ほどのご答弁のとおりなのですが、このような質問をしてこのようなご答弁がありました。前向きなご答弁をいただいたというところは確認させていただきました。先ほど質疑の中で、来年度の実施に向けて検討をされているということが聞こえたのですけれども、そのとおりでよろしいのかどうか、それだけ確認させてください。","respondent":"川原高齢者地域支援課長","answer":"副委員長のご指摘のとおり、実施に向けて、今取り組んでいるところです。","voiceIndex":71,"id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問","question":"結論を出す、不採択でお願いします。というのも、今の明確なご答弁があったように、本会議一般質問等への答弁、方向性が出ている、そして今回の請願項目に一致するものが、既にもう今年示されていて、取り上げるまでもないものとして好意的に私は捉えたので、そのような意味で取り上げずということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"結論出す、不採択でお願いします。今の渡辺委員からの、自民党の意見と同じで、私どもからの要望に答弁のとおり、今その段階まで来たということで、来年度からの実施を目指しているという答弁をいただきましたので、その上で取り上げる必要はないということで、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。来年度実施に向けてということでありましたので、本当によかったなと思います。ぜひ本当に、来年度でも早いうちに実施していただきたいなと思いますし、それを議会としても後押ししていきたいと思いますので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-024"},{"speaker":"木村委員","kind":"意見","question":"結論を出すで、不採択でお願いします。いろいろと高額な費用もかかるようですけれども、本当にそれが、区民の皆さんが、実際に難聴なのか、そのような意味では聞こえづらくなっているのかどうか、そのような検査というものをしっかりやってもらうべきで、まだ時期尚早と思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。ご説明、答弁もいろいろいただきまして、来年度から実施ということで検討を進めていると。ただ、２つだけ。そういったところの、何というのですか、制度を導入するに関しては、そごのないように十分な準備をお願いして、少し早くということと準備をしっかりということは矛盾しますけれども、両方を確立させるような形で進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-026"},{"speaker":"せお委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。様々、今ご答弁などありましたが、購入費助成というものがしっかりと効果を発揮するように、そこは丁寧に今進められていると思いますけれども、丁寧に準備をしていただいて、早期に実現するようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-027"}]},{"id":"topic-03","title":"令和４年陳情第６０号、高齢者住宅の増設を求める陳情","agenda":"令和４年陳情第６０号、高齢者住宅の増設を求める陳情","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"高齢者住宅の増設を求める陳情ということで、私たちも高齢者住宅の増設は求めてきていたところですので、ぜひ進めていただきたいと思うのですが、区には建設型が３棟、借り上げ型が７棟ということで、全部で２２３戸ということでした。そのようなものは全くなくて、増設は必要ないという立場なのか、そこを伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"現在増設の予定は、先ほど申し上げましたとおりございませんが、公的な住宅に関しましては、やはり財源の確保、土地の問題等、様々な問題がありますので、こちら引き続き研究が必要となってくるのですが、直近で住宅に困っている困窮者の方に対しては。","voiceIndex":88,"id":"exchange-028"},{"speaker":"石田委員","kind":"質問","question":"先日、１１月にも、今年最初で最後の募集があったと思うのですけれども、この間の経年的な高齢者住宅への募集、要は申請と入居可能戸数が、昨年、一昨年、入居可能な戸数が何戸生まれていて、そこに何人が申請をして、それで何人が入れて、何人が未解決なのかということが分かる形で教えていただけないでしょうか。","respondent":"川原高齢者地域支援課長","answer":"入居可能な戸数というところは、実際には時差がございまして、今お住まいの方が退居されてから、次に新しい方がお住まいになるには、一部補修や軽微な工事が必要となってきますので、そこを一概に、現在何戸というようにはちょっと申し上げられないので割愛をしますが。","voiceIndex":90,"id":"exchange-029"},{"speaker":"石田委員","kind":"質問","question":"そうしたら、今年の１１月に申し込んだ方は何人いらっしゃるのかということをまずお尋ねしておきたいということと、去年申し込んで今年度入られている方が１８名、それでプラス４名で、入れていない方が３８名ということですよね。そうしたら、そのもう１個前も分かれば伺いたいのですけれども、おととし申し込んで去年入り始めた、また入れなかったという、経年的な数を伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"すみません。ちょっとおととしの状況については、今手持ちの資料がすぐに出ないのですが、今年度の申込みの状況という形でよろしければ、今年度の状況、令和４年度申請ですね。令和５年度入居希望の方の申請の状況をご説明します。今回申請がありました方は、６５名でした。","voiceIndex":92,"id":"exchange-030"},{"speaker":"石田委員","kind":"提案","question":"ですから、４０名近くの方が毎回未解決というか、要は立ち退きを受けていようが、劣悪な環境に住んでいようが、高齢者住宅には入れないという方が４０名前後、毎回大体おられるかなと思うのです。それで、入居するところまでのめどというものがつくような形のことを区として提案していただいたりはするということなのですか。","respondent":"川原高齢者地域支援課長","answer":"一人一人ご相談に丁寧に対応しているような状況です。","voiceIndex":94,"id":"exchange-031"},{"speaker":"石田委員","kind":"質問","question":"大きくあるようであれば、やはり高齢者住宅がいいというようになっていくと思うのですけれども、民間のほうに高齢者住宅としてあっ旋した方との家賃の違いというものはどれぐらいあるのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"お一人お一人の細かい家賃の状況までは、ちょっとこちらでは分かりかねるのですけれども、希望の家賃額というものをその方のご意見、希望欄のところに書いてありますので、それに見合ったものを不動産会社を通じて紹介をいただいているところですので。","voiceIndex":96,"id":"exchange-032"},{"speaker":"石田委員","kind":"質問・要望","question":"ですから、高齢者住宅の増設、今のところ考えていない、検討はしていないということですけれども、ぜひ検討していただきたいなと思いますし、あと陳情項目の年１回の募集、私もこれは本当に、毎年毎年この時期にタイミングよく、立ち退きや劣悪な環境に住んでいるという状況が生まれれば、それこそ高齢者住宅に申し込めるのですけれども、そのようなタイミングではない方も多々いらっしゃいますので。","respondent":"川原高齢者地域支援課長","answer":"募集の回数についてのご質問です。募集の回数は年１回というところで、今後も予定をしています。","voiceIndex":98,"id":"exchange-033"},{"speaker":"石田委員","kind":"質問・要望","question":"実態調査等に高齢の方が対応するのが、年２回あると大変だということなのですけれども、何というのですか、立ち退きであれば住まいを失うということになるので、そこは高齢者の方も、実態調査等々を受けながら、やはり住まいの確保を進めたいと思うと思うのです。この年に１回ということの理由が、ごめんなさい、聞こえづらかったので、もう１回ご説明だけお願いします。","respondent":"川原高齢者地域支援課長","answer":"ご意見として年に２回ということは承らせていただいて、検討したいと思います。","voiceIndex":100,"id":"exchange-034"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、毎年４０名前後の方が未解決のままに終わっていくわけですから、ほかのサービスにつなげていくということもありますけれども、高齢者住宅があれば、そこがやはり一番安心ですし、暮らしを確保、安心を確保できるということにつながりますので、区がそこに責任を持つということは当然のことだろうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-035"},{"speaker":"いながき委員","kind":"質問・要望","question":"ですから、本当に優先するべき方であるならば、新規という形でお一人やお二人であれば対応はできるのではないかなと思ったのが１つと、高齢者住宅というものは手すりがあったり、人感センサーがあったり、緊急通報があったり、あと管理人室があって、見守りもプラスされているというように伺ったのです。","respondent":"川原高齢者地域支援課長","answer":"２点目、借り上げの高齢者住宅の増設というところに関しては、国や都の動向、あとほかの自治体の情報も入れまして、検討してまいりたいと思います。現時点で増設ということは、今の時点ではございません。","voiceIndex":104,"id":"exchange-036"},{"speaker":"あくつ副委員長","kind":"質問","question":"様々ご説明ありがとうあります。高齢者住宅のニーズというものは我々も伺っているところなのですが、先ほどのご説明の中で、基本的には今増設は考えていないということ、既存の高齢者住宅を活用するということと併用して、民間の賃貸住宅のあっ旋事業等を拡充しているというようなことでした。","respondent":"川原高齢者地域支援課長","answer":"昨年度までは、お申込みができる方は、立ち退きですとか、劣悪な住宅に住んでいるですとか、保証人がいないなどで賃貸を今度契約更新をしたいけれども拒否されてしまっている、そして高額家賃で契約が困難という方のみを受付していたところなのですが。","voiceIndex":107,"id":"exchange-037"},{"speaker":"あくつ副委員長","kind":"質問","question":"先般の一般質問、これちょっと所管質問になってしまうかもしれないのですけれども、その辺り、ＮＰＯ法人等の活用のようなことについてもお考えいただけるようなご答弁もたしかあったと思います。その辺り簡単に、お考えがあれば再度教えてください。","respondent":"川原高齢者地域支援課長","answer":"残念ながら区内には団体がないのですけれども、ほかの自治体がどのような形で進めているかという調査をして、研究をしています。","voiceIndex":109,"id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問","question":"自民党、結論を出すで、扱いは不採択でお願いします。それぞれ課題の指摘、すぐには増設等難しい課題も含めて、また、その間もあっ旋の事業、あるいは受入れの拡充の説明もありましたので、その点から踏まえて、不採択という結論でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-039"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。先ほどの質疑のやり取りのとおりですが、区のお考えも一定程度理解ができ、経費の話も最初出ましたけれども、そのようなところで民間の活用というところによりいっそう力を入れていただきたいという意味を含めての不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-040"},{"speaker":"石田委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。やはり住宅に困窮する高齢者の方への住まいの確保を区が保障するというところでは、民間のところのあっ旋もありますけれども、それと併せて高齢者住宅をさらに増やしていくということが、さらに安心に必ずつながっていきますので、そこは増設していただきたいし、申請回数も増やしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-041"},{"speaker":"木村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。そしていずれ、それでもどうしても足りない場合には致し方ないと思いますけれども、何分にもそのお金というものは、区民の財産でもあるということを考えますと、むやみやたらに、むやみという言葉は失礼な言い方ですが、慎重に使うべきではないかというようなことです。それで不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-042"},{"speaker":"いながき委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。やはり住宅は、心身の健康面からとても重要な部分だと思います。ただ、増設をしないことには、募集回数を増やしてもご希望に沿えないのかなとは思いますが、高齢者住宅のあっ旋事業、それもお伝えをしつつ、でもやはり高齢者住宅、見守り等のきちんとしているものを求めていらっしゃると思うので、ぜひご検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すでお願いします。取扱いは不採択でお願いします。いろいろご説明いただいて、課題も指摘していただいて、その一方で、現状でできることを様々取り組んでいるということも説明いただきました。高齢者住宅の増設ということも含めて、これは要望なのですけれども、高齢者施策という全体の大きなものの中で研究していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、新設に関しては、区全体で議論していっていただきたいなと考えています。先ほどもお話がありましたあっ旋など、そういった今ある事業を申請して、かなわなかった方には丁寧にご説明を引き続きお願いしたいと思っています。先ほどあくつ副委員長からもお話がありましたけれども、私としましても、民間の活用をぜひ広げていっていただきたいなと、そこは要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-045"}]},{"id":"topic-04","title":"令和４年陳情第６４号、八潮に暮らす高齢者が健康づくりと生きがいづくりに利用できる入浴設備のあるシルバーセンターの整備を求める陳情","agenda":"令和４年陳情第６４号、八潮に暮らす高齢者が健康づくりと生きがいづくりに利用できる入浴設備のあるシルバーセンターの整備を求める陳情","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"それで八潮の高齢化率、３５％ぐらいですか、今はもう少し上がっているのですか。ですから、そのようなところからも、シルバーセンター、ゆうゆうプラザも含めてですけれども、新設してもいいぐらいの地域、配置バランスとおっしゃっていたのですが、八潮地区としては必要ではないかと思うのですけれども、区の立場を改めて伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"現時点では、シルバセンターもしくはゆうゆうプラザの新設は、行う予定はございません。","voiceIndex":127,"id":"exchange-046"},{"speaker":"石田委員","kind":"質問・要望","question":"この八潮、八潮地区として見ていく必要があると思うのです。ですから、どうしたらできるかというところでぜひ考えていただきたいし、八潮南特養ホームの増改築に合わせて、ぜひ検討をしていただけないかなと私も思います。そういったところで、今の八潮南特養ホームの増改築の部分の進捗というのですか、設計など、どのような段階なのかということを伺いたいのですが。","respondent":"寺嶋福祉計画課長","answer":"現在、基本計画を進めている中、設計等も前提に置きながらの計画ということになるのですけれども、この間ご説明してきたとおり、まず区内での特養ホームの増築というのですか、増床、これが一番の目的でありまして、上大崎特養ホーム、それから民間のグランアークみづほ以降。","voiceIndex":129,"id":"exchange-047"},{"speaker":"石田委員","kind":"質問・要望","question":"南品川のシルバーセンターや東品川のシルバーセンターの入浴施設を利用されている方に、私もお話を聞いてみたのですけれども、やはり１人ではないことが安心だというのです。ぜひ、どうやったらつくれるかということを検討していただきたいのです。そういった視点からもぜひ見ていただいて、どうやったらつくれるだろうかという検討を部署のほうでしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"今、八潮のまちづくりの検討会のお話も委員からあったと思うのですが、私どもも適宜八潮のまちづくり懇談会等の意見などは話を聞かせていただいておりますので、引き続きその部分は研究をしてまいりたいと思いますけれども、現時点では、八潮南特養ホーム等。","voiceIndex":131,"id":"exchange-048"},{"speaker":"いながき委員","kind":"質問","question":"シルバーセンターをつくるに当たっての基準というものは、どのような基準に基づいてこれはつくられているのでしょうか。地図を見た感じで、八潮地区すごく広いのですけれども、何となく地図を見た限りでは、ほかのところと比べて２か所ぐらいあってもいいのではないかなと思える面積なのですが、どういった基準でシルバーセンターなどをつくるのかなということをお尋ねしたいのですが。","respondent":"川原高齢者地域支援課長","answer":"明確な基準というものは、ちょっとこちらでは申し上げるものはございません。今は、先ほど申し上げた老朽化したシルバーセンターの改築というところの計画を進めてありますので、既存の施設の老朽化に対してどのように改築を行っていくかというところは現段階で検討しています。","voiceIndex":134,"id":"exchange-049"},{"speaker":"いながき委員","kind":"質問","question":"大体３,０００人から６,０００人規模のところにというようなお話だったかと思うのですが、不勉強ですみません、八潮地区というものはどれぐらいの方がいらっしゃるのかお伺いしたいと思います。","respondent":"川原高齢者地域支援課長","answer":"八潮地区の人口は、４月１日現在で約４,３００人です。ただ、八潮地区にいらっしゃる方は、ゆうゆうプラザでは東品川ゆうゆうプラザのほうもご利用をいただいているところです。は南大井ですとか、南品川等のご案内をしています。","voiceIndex":136,"id":"exchange-050"},{"speaker":"渡辺委員","kind":"質問","question":"結論を出す。態度は不採択でお願いします。質疑、答弁等を伺った中、課題は課題で存在する、そしてまた、八潮地域だけではなく、区全体のバランス等も必要な部分もあるのだなということが分かりました。そのようなことで、願意に沿い難いということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-051"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。地元に確認したら、６９棟の建物がある中で、全ての住居に基本的には浴室は設置をされている。という中で、そのような入浴施設を八潮内で求めるお声は、あることはあるということは地元から聞きました。私どもとしては、その地域の声、総合的に聞いていただいて、ご判断いただきたいと思いますので、今回のこの陳情の願意には沿い難いということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-052"},{"speaker":"石田委員","kind":"質問・要望","question":"やはり、先ほどいながき委員からもありましたけれども、３,０００人から６,０００人ということを見てもあっていい地域だし、あるべきだと思いますし、高齢者の方が安心してというところでは、そこを確保していくということは、入浴設備というものは必要だろうなと私たちもずっと訴えてきましたので、ぜひどうやったらつくれるかという方向で考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-053"},{"speaker":"いながき委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。今、高齢者の方のお風呂場での事故というものがすごく気になります。ここにもあるように、大勢の目があるほうが安心して入れるということはあると思うのです。改修計画、ちょうど八潮にあるというのであれば、ぜひ区民の希望に沿う方向で考えていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、先ほども別の委員からありましたけれども、八潮の懇談会、そちらで八潮の在り方を検討されていくということ、話し合っていくので、ここは地域活動課の所管なのですけれども、こちらの委員会の所管の福祉や保健・医療施設、そのようなものが八潮の中でどのように整備していく施設が必要なのかということを、少し課は違うかもしれませんが、連携していいまちづくりを進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"区全体の需要のバランスだったりとか、あとはほかの委員からもお話がありましたけれども、八潮のまちづくりの担当の部署ができて、そこで懇談会や、あとワークショップなども行われているというお話も聞いていますので、そちらでシルバーセンターも含んだお話、議論をぜひ地域の方々で定期的に行って、そちらを参考に、まず、地域活動課とも連携して、聞いていっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3646#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":37614,"voices":155}},{"id":"r04-20221222-8","meetingId":"r04-cm12","date":"2022年12月22日","dateIso":"2022-12-22","committee":"建設委員会","time":"午前１０時００分～午後 ３時１７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、(2)第１１１号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"会議の運営上、予定表の順番を入れ替えまして、(2)第１１１号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、廃棄物処理の手数料が値上げされるということですけれども、説明の中では、現行手数料と手数料原価の乖離があるということで値上げをするということですが、その乖離が生まれている理由を伺いたいと思います。それと、その中で、収集運搬部門が４円で、処理処分部門が２円ということですが、ここの考え方というのですか、ここのところも伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"これと現行の単価との乖離分、これについて値上げをしているものです。それから、処理手数料の考え方ですけれども、資料のとおり、収集運搬部門、それから、実際に処理する部門ということで分けて、それぞれで金額を算出して、手数料を出しているというものです。","voiceIndex":9,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"部門別のところでもそれぞれ出しているという、そこと関係してくると思うのですけれども、それぞれの部門で４円と２円が上がっている理由というところを伺いたいのと、あと、清掃主管部長会で改定の検討がされたということですが、その中ではどういった意見というか、検討、話合いが行われたのか、そこも伺います。","respondent":"品川品川区清掃事務所長","answer":"乖離が生まれているということですけれども、これは原則、４年に１回程度、単価の改正をしております。前回はコロナの関係等もありまして、大分前になるのですが、平成２９年１０月に改定をしております。","voiceIndex":11,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"４年に１回改定をしているということで、その間の改定の際には、上がってきたのか、下がってきたのか、変わらないのか、そこも伺いたいと思います。なぜここで上げるのか、伺います。","respondent":"品川品川区清掃事務所長","answer":"上がった下がったですが、基本的には、現行の４０円から４６円に上がっているという動きがあります。それから、ここ４年間の平均値を取って算出しているものですが、ここ４年につきましては、基本的には毎年増加しているという傾向が強いかと思います。","voiceIndex":13,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"業者に負担させるのもなかなか厳しいということですが、そうであれば、区でその分補助をするということをやっていくべきではないかと思いますが、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"先ほど少し説明したとおり、(1)のところ、それから粗大ごみ等のところは該当するかと思うのですが、これは基本的には臨時ごみという形で、常時負担するものではないというところでは、区民負担については大きくは表れないのかということが感じられます。","voiceIndex":15,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"加えて、中小企業の事業者は、ごみ処理券を貼って出すことになりますので、４５リットル券でいきますと、１０枚セットで今回４９０円の値上げになるということですので、そうすると、今まで３,４２０円だったところの約８分の１ぐらいの値上げということで、１割を超える値上げが行われるということですから、それは大きな負担になると思います。","respondent":"品川品川区清掃事務所長","answer":"各企業の負担ですが、こちらも先ほどの答弁と同様になってしまいますが、基本的には廃棄物処理法の中の自己的負担という中で原則行われているものと解釈して、この手数料改定は進めてあります。","voiceIndex":17,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民や中小企業の実態はつかんでいるのかというところを聞いたので、そこも伺いたいと思います。それで、受益者負担ということですけれども、つまり、区で負担をするということは検討さえもしていないということなのか、そこを確認させていただきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"こちらは、先ほど少し説明をしていますが、いろいろな業者の処理費用、こういうもののコストも全部調査をしまして、処理単価を出しているという状況です。ですので、大部分のところについては状況は把握していると考えています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"大体は把握しているということですが、今のは処理業者の話ですかね。中小企業の今のコロナや物価高の下での状況、その上でごみ処理券が値上げになるということですから、そういった状況を分かって値上げをしようとしているのか。それはやめるべきだと思うのですけれども、そこのところを伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"いろいろな状況を見ているかというようなご質問の中で、先ほどからご説明しているとおり、ここ２年間、コロナの関係等、やはり事業所に負担がかかるのではないかという議論の中で見送りという判断もしています。","voiceIndex":22,"id":"exchange-007"},{"speaker":"のだて委員","kind":"提案","question":"把握していると。その上でさらに値上げを提案しようということですので、なおさら悪いという感じがするのですけれども、やはりコロナ、物価高の下で、来年１０月からということですが、そのときにコロナが終わっているとも限りませんし、物価高も続いているかもしれませんので、そうした下で値上げをしていくのはやめるべきだと。これは強く要望しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問","question":"家庭ごみの状況をお聞きしたいと思います。もう一つが、臨時に排出するということですので、先ほど例題で引っ越し等とありましたけれども、いわゆる生活保護の方とか低所得者の方とか、こうした方々への対応、いわゆる費用の支払いの部分はどうなっているのかをお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"臨時ごみの関係ですけれども、１日に出るか出ないかという、大体それぐらいの状況かと思います。それから、生活保護関係、そういう状況の方については、それぞれの生活状況等も把握して、金額は別途また算出をしてやっているという状況です。","voiceIndex":26,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、今、そうした算出を別途してくださっているということですので、数字が出れば、この６円がどれぐらいの算出になるのかというところを一つお聞かせいただきたいのと、事業系の話が先ほど出ておりましたけれども、やはり一方で、このコロナ禍、清掃、回収してくださる方々、コロナの関係で大変リスクが高いお仕事でもありました。低所得者の方々の対応のところだけお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"低所得者の対応については、これも状況に応じて無料でやるとか、そのような対応等も取ってきているところですので、その方の生活状況等におきまして、いろいろと考えてやっているというものです。","voiceIndex":28,"id":"exchange-010"},{"speaker":"横山委員","kind":"確認","question":"区のウェブサイトにも、例えば、差額ですとか、払戻しですとか、そういった細かい部分が載っているかと思うのですけれども、皆さん、家庭ごみもそうですし、事業系の方も、これから大きなそういった整理ですとか、排出等を検討されている、計画されているようなところがあるかもしれませんので、迅速に必要な方にしっかり伝わるような形で広報、ご案内をお願いしたいと思っているのですけれども。","respondent":"品川品川区清掃事務所長","answer":"広報で周知するところにつきましては、この辺もスケジュール感はしっかりと考えておりまして、今回、条例改正を進める形で、もし議決をいただければ、４月から１０月まで、これは、１０月からとしているのが、周知期間ということで、４月から１０月まで周知期間を取って。","voiceIndex":31,"id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"シールのところ、皆さん、混乱等がないように、色の変更みたいなところも、前回行っていただいているかと思うのですけれども、それぞれの区で違いが出た場合に、皆さん勘違いされてしまったりですとか、そういった混乱がないように進めていただきたいと思いますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"芹澤委員","kind":"確認","question":"今回、値上げということではありますが、区民の負担感はなるべく少なくされながら、事業者の負担も検討して、税による補填も検討して、特に２年間、先延ばししてからこれが今出ているわけですから、基本的には賛成いたしますが、確認で、４０円から４６円になっていくと。","respondent":"品川品川区清掃事務所長","answer":"ですので、例えば現行２００円のもの、これについて値上げをせざるを得なければ、やはり３００円という形でやっていかざるを得ないかと、現在のところは考えております。","voiceIndex":37,"id":"exchange-013"},{"speaker":"芹澤委員","kind":"確認","question":"今おっしゃるとおり、１００円単位の券ですからそうだと思うのですけれども、確認で、一律に全部１００円単位で上げていくということではなくて、例えば、３００円のものは３００円、４００円のものは４００円のものもあれば、残念ながら１００円単位で上げていかなければならない品目も出てくるだろうということでよろしいのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"まさにそのとおりで、これは多分品目別に値上げの上下がどうしても多少出てしまうということはあり得るかと考えております。","voiceIndex":39,"id":"exchange-014"},{"speaker":"芹澤委員","kind":"質問・要望","question":"最後、要望で、全体的な値上げに関しては反対しておりませんが、区民の負担感がなるべく少ない方向で、うまくバランスを取っていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"}]},{"id":"topic-02","title":"第１１６号議案、指定管理者の指定","agenda":"第１１６号議案、指定管理者の指定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、区民住宅の指定管理者の指定ということで、公募型プロポーザル方式でやったということですが、結局、応募されたのは１社のみだったということで、そうすると、プロポにした意味が半減、ほとんどなくなってしまうのではないかという感じがするのですけれども、１社しか応募してこなかったことについて区はどのように捉えているのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"民間企業ですので、仕様を見て、採算性とか、仕様に適切に対応できるか等々のご判断の下、残念ながら２社は辞退になったものと考えております。今後、１社でも多くのご提案があるように、適切に対応していきたいと考えております。","voiceIndex":53,"id":"exchange-016"},{"speaker":"のだて委員","kind":"提案","question":"だからこそ、この１社しか、既に今やられている事業者ですので、そういった中で実際の状況も分かるし、やりやすいのかというところで提案していただいていると思うのですけれども、そうした中でやはり公募をしてもなかなか応募がないという状況ですので、東急コミュニティーが受託をするメリットというのですか。なかなか利益が出ないと思うのです。そういうメリットがあるのかどうか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"ですので、近隣の同業務を行っている方に駆けつけていただく、あるいは、全国展開、５２万の民間のマンション等を含めまして、こういった住宅の管理をしておりますので、全国から応援を呼び寄せられるという、これは直営ではとてもできないような手厚い体制だと考えています。","voiceIndex":57,"id":"exchange-017"},{"speaker":"のだて委員","kind":"提案","question":"そういったところで点数を公表していただきたいということで伺ったのですが、その点、いかがでしょうか。そうすることで、事業者の提案というのが分かるわけです。そうしたところで、やはり資料を充実させていくということが必要だと思いますので、そういった対応をしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"今後、提案内容等をどのような形でご説明することが一番最適なのかについても、考えていきたいと考えています。","voiceIndex":59,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ公表していただいて、その下で判断できるようにしていただきたい。これは強く要望しておきたいと思います。大きく分けても１０項目ありますけれども、その点を伺いたいと思います。今回、この調査の中で、労務関係についての調査というのはしているのでしょうか。官製ワーキングプアを生み出してはいけないと思うのですけれども、そういった点の検討、調査というのはどうされているのか、伺います。","respondent":"竹田住宅課長","answer":"特に、特筆して挙げられるのは、まず、建物に対する維持管理計画です。こちらについては、先ほどご説明しましたが、緊急時の対応が非常に期待できること、それから、新たな提案として、長期修繕計画の作成というのも提案されております。","voiceIndex":61,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"この事業者の人件費が４７.３％ということで、標準的ということですが、管理をしていく中で、経費がかかるというのは管理人の業務がメインなのかと思うのですが、その中で、そうすると、人件費が一番大きいかと思うのですが、それが半分を下回っているというのは標準的なのかどうか、そこの考え方を伺いたいと思います。そうすると、特に滞納などでは、入居者の生活状況が分かってしまうと思うのです。","respondent":"竹田住宅課長","answer":"個人情報の点ですが、こちらの企業は個人情報保護について非常に重点を置いておりまして、例えば、プライバシーマークという民間の認証制度、一般財団法人が提示しているプライバシーマークというものですが、これを１４年間認証していたり、あるいは。","voiceIndex":63,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどあった「健康相談ダイヤル」、こういった視点というのは、むしろ区が持つべきなのかと。管理ということで、ハード面に目が行くのも分かるのですが、やはりそうした区民の生活をどう支えていくかという区としての視点が必要だと思いますので、そうした区民を支えていくという視点についてどのように考えているのか、伺います。","respondent":"竹田住宅課長","answer":"区の窓口につなげてはどうかということですが、今現在、例えば、３か月滞納が続いたような方につきましては、指定管理者に任せ切りにするのではなく、区のほうにお越しいただいて、区の担当職員が丁寧に聞き取りをしまして。","voiceIndex":65,"id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"３か月滞納した方については区のほうでも聞き取るということですが、できればそれを早め早めに対応していくということが重要だと思います。そうしたことは、区が職員としてもともと対応すれば、すぐ分かるわけですし、今おっしゃられた対応というのも、どうやって払っていくかということだと思うのですが、その裏の背景には、コロナで仕事がなくなったとか、そういった問題があるわけです。","respondent":"竹田住宅課長","answer":"委員がおっしゃるとおり、今、コロナということで、一時的に収入が減少したという方も多数おられると思いますので、滞納に至った経緯等を丁寧にお聞きして、どういった返済方法があるのかというのを、お話を伺いながら、一緒に考えていくという姿勢で臨んでいるところです。","voiceIndex":67,"id":"exchange-022"},{"speaker":"横山委員","kind":"提案","question":"指定管理者業務仕様書の９ページですけれども、その他の業務の(3)関係機関・団体との連絡調整業務の２番目のところ、「近隣との相互理解・協力は不可欠なことから、入居者には、町会への加入を積極的に働きかけること」とあるのですけれども、それはどのような働きかけをされているというご提案があったのかを、まず確認させてください。","respondent":"竹田住宅課長","answer":"ご通報いただいた場合の対応につきましては、こちらも細かく、３０分経過したときはどうするのか、２時間経過したときはどうするのか、それから、３日後、１週間後等、時期を区切って対応方法が細かくマニュアル化されておりますので、そういったものに基づきまして。","voiceIndex":72,"id":"exchange-023"},{"speaker":"横山委員","kind":"提案","question":"ソフト面からのサポートをするということで、大変重要な取組かと思いまして、また、別のページのところ、７ページですか、「住民に対して実施したアンケート結果のフィードバックや、各自治体の事例について社内で蓄積されている情報を区へ提供してもらい、うまく活用してほしい」などの委員の意見等もあるのですけれども、こちら、関連しているかどうかは私のほうでは分からないのですが、すみません、あと。","respondent":"竹田住宅課長","answer":"選定委員会が行われて、その後にこの件についての事業者との接触というのはしておりませんので、今後、指定管理者に決まりましたら、ご提案いただいた内容をどのような形で実施することが一番効果的なのか、有効なのかというのをしっかり詰めまして。","voiceIndex":74,"id":"exchange-024"},{"speaker":"横山委員","kind":"確認","question":"ありがとうございました。すみません、私が聞き漏らしてしまったのかもしれないですけれども、健康相談ダイヤルのところに戻るのですが、看護師以外の資格の部分、もう一度、すみません、確認させてください。","respondent":"竹田住宅課長","answer":"すみません。漏れておりました。私が聞いているのは、看護師等と聞いておりまして、それ以外の方がどういう資格を持っているのかというのは確認できていないです。","voiceIndex":78,"id":"exchange-025"},{"speaker":"こんの委員","kind":"提案","question":"今回のこの東急コミュニティーは、指定管理の実績としては、そうすると３回目になるのでしょうか。それから、先ほどの７ページですかね。そうすると、新規としてご提案があったアンケートの実施、それから、「健康相談ダイヤル」というご提案、こうしたことで指定管理のいわゆる契約金額、こうしたものも前回より少し上がっていくのか、その辺の具合も教えてください。","respondent":"竹田住宅課長","answer":"アンケート、あるいは「健康相談ダイヤル」は別に費用を要するものなのかというところですが、提案書には無料で行いますということで明記されているところです。","voiceIndex":81,"id":"exchange-026"},{"speaker":"こんの委員","kind":"質問・要望","question":"参考までにこのことをお聞きしたのは、いわゆる３回目になりますので、お互い緊張感のある関係でこれからもお仕事をお願いし、受けていただく、こうしたことをお願いしたいという思いでお聞きいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした理由から、株式会社に委託するのではなく、区直営でやるべきですので、反対です。それと、ぜひ情報をいろいろ公表していっていただきたいということは、意見として述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-028"}]},{"id":"topic-03","title":"令和４年請願第１７号、航空需要が回復したとしても、羽田新飛行ルートは必要無くなりました、よって国に対し運用停止を求める請願","agenda":"令和４年請願第１７号、航空需要が回復したとしても、羽田新飛行ルートは必要無くなりました、よって国に対し運用停止を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、その上でも、国の言う増便が可能だということで、海上ルートに戻してほしいということで今請願がされておりますけれども、こうした中でまた同じ、続けて２度目の請願が出されてきた下で、区はどのように受け止めているのか、伺いたいと思います。そうした下で、やはり区としての判断が求められているということだと思うのです。その点について、区の認識を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今回の後方乱気流の件も含めて、やはり町会を含め、地域の方々、区民の方には丁寧にその内容を国のほうからしっかり説明していただけるように、こちらについても併せて国のほうには申し入れているところです。","voiceIndex":98,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"この下で、結局、この固定化回避の案が出てきたとしても、やはり品川区の上を飛ぶことになってしまうということだと思いますけれども、そこの認識をまず伺いたいのと、区長はそういう認識だということですので、区がその下で固定化回避を見守っていくという姿勢は、区長の姿勢とずれるところがあるのではないかという気がするのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今現在、国で実施していただいている検討状況についてのお話ですが、国のほうは、現状の羽田新ルートを将来にわたり固定化せず、現状から可能な限り環境影響の軽減につながるルートの見直しがないかというところで、これは区のほうでも国に求めてきた内容ですが。","voiceIndex":100,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"結果をすぐ示してほしいということですけれども、その結果が出ていないということですが、区長の認識としても、品川区の上を結局飛ぶことになるということですよね。その下で、やはりその結果を待っているだけでいいのかと思うのですが、いかがでしょうか。やはり区として、羽田新飛行ルート、運用停止を求めることが必要だと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区としては、やはり少しでも環境軽減につながる見直しが行われるように、具体的な提示を早急に求めていただきたいというのが区の姿勢でございまして、それとともに、やはり区長のほうが、今回の一般質問でも答弁させていただきましたが。","voiceIndex":102,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこの区の認識を伺いたいと思います。先ほど来、区としても、視界が悪いときは、検討しているルートは実施できないということですので、そうすると、今の新ルート、品川区の上を縦断というのですか、下りてくる新ルートは、この検討案が出されたとしても実施されることになってしまうと思いますが、その点も伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"飛ぶことになることに対しての区の認識ですが、現行ルートがそのまま見直しも行われず将来にわたって、これも繰り返しになりますが、そのまま継続し運用されていくことがないように、先ほど委員のほうから、これが結果固定化されているのだというお話もございましたが。","voiceIndex":104,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、結果を早く出してもらうという繰り返しの答弁ですけれども、やはり実際問題、品川区の上を飛ぶことになるということで、将来にわたってと言いますけれども、将来、そうしたら、区の姿勢としては、１０年後、少し変わればそれでいいのでしょうかと思うのです。私は、区民の被害をなくしていくためには、やはりこの羽田新ルートの運用を停止することこそ必要だと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"視界が悪い場合には従来の運用が行われるというところのお話がございましたが、これも繰り返しになりますが、資料には、デメリットとして視界が悪い場合の点が記載されてありますが、それに対して対応していくのか、ほかの方法があるのか。","voiceIndex":106,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"アンケートを実施して、実態を把握して求めていくということですが、ぜひ実態はつぶさに、いろいろと住民の身体的あるいは精神的な被害ですとか影響というのをつかんでいただきたいと思いますけれども、それに併せてぜひ賛否も取っていただきたいと思いますが、いかがでしょうか。実際に滑走路の１機当たりの占有時間というのはどのくらいになるのか、そこも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"２分間隔を切るという、請願の内容にも示されているところですが、これは今回、お手元にご用意させていただきました資料の頭紙、この点についても国のほうに、３番のところになりますが、先ほどもご紹介させていただきましたが。","voiceIndex":108,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"その下で、滑走路、着陸してくる間隔、ここに変更はないということでしょうか。従来どおりの、後方乱気流管制方式を使用した上での滑走路上の短縮というのは今はないということなのか、伺いたいと思います。資料の中の、Ｃ滑走路については離着陸機共に存在して、到着機の間隔が２分を切る場合もあるということがどういう意味なのか分からなかったので、もう少し詳しく教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"後方乱気流の方式を採用して、上空で間隔が詰められて、そのまま詰めた間隔で着陸すれば、これは、増便につながるのではないかというのは、説明を伺ったときに、この形のものが公表されたときに、それは区としてもそう考えまして、国のほうに確認をさせていただいたところです。","voiceIndex":110,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ品川区としても、国の言う増便というのができるということで、運用停止を国に求めていただきたいということは強く要望しておきたいと思います。これを先延ばしにしていくわけにはいかないと思いますし、来年４月には改選にもなりますので、ここでやはり請願者の方々が出された思いを議会としても受け止めて、採決をしていくべきだと。皆さんにこれは呼びかけたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-036"},{"speaker":"芹澤委員","kind":"質問・要望","question":"もう一方で、新しい技術があって、新方式になって、スピードが若干上がっていくというような話もありましたので、これは、直接増便には関わらないということですが、これからも新たな技術が出てくるだろうと思っていますので、これは国に任せ切りにせずに、区としても新技術をしっかりと見つめていただいて、要望できるところはしっかりと要望を引き続きやっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-037"},{"speaker":"こんの委員","kind":"意見","question":"本請願については、継続でお願いしたいと思います。理由は、増便できるできないというお話、質疑もありましたけれども、事実に対して認識が誤っているのか、異なっているのか、そういった点が１点。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"なので、結論を出していただきたいということと、区民に騒音や落下物などの被害を与えている羽田新ルート、すぐにでも運用を停止すべきだと私は思います。先ほどそうしたうるさいということとか、いろいろ思いはあるということですので、やはりそれを区民の声として受け止めて、議会としても運用停止を求めていくべきだと思いますので、また、国の言う増便も海上ルートで可能だと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-039"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す、そして、採択いたします。この請願に書かれております内容に、前回審議された結果を各町会長・自治会長様にご報告に回り、そして再度信託を得たとあります。我が会派といたしましては、これを重く受け止めなければならないと考えております。固定化回避検討会が開かれ約２年半たちますが、結果が出てこないのが現状です。このことも踏まえて、この請願に対しては採択いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-040"},{"speaker":"横山委員","kind":"確認","question":"本日の議論では、区民アンケートにて、区が区民の皆さんの様々なご意見ですとか実態を直接お聞きしていく予定だということ、また、内容の一部は、事実と相違している部分があるとの確認をいたしました。引き続き区民の皆さんの心に寄り添って丁寧に説明、確認していく必要があると考えておりますので、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、武蔵小山駅前の小山三丁目の再開発について、様々説明を求めるですとか、いろいろ書かれた陳情となっています。５番目、６番目あたりに書いてある発言の件ですけれども、貧乏人には買えないだろうとか、あと、三菱地所の社員の方が、私たちはまちがどうなってもいいという発言をしたということですけれども、こうした発言について、区の感想を伺いたいと思います。","respondent":"多並都市開発課長","answer":"この陳情にありました発言のところですけれども、これにつきましては、やはりまず、その前後のいろいろな、何というのですかね、話の流れが分からない中で、区で明確にこうだと答えるのはなかなか難しいところであるのですけれども、ただ一言でお話しするところであれば。","voiceIndex":128,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"この破綻のところは、破綻しないようにということですが、いろいろ変化があって、物価高騰などもありますので、いろいろ工事費にも跳ね返ってくると思うのですけれども、そうしたときにこうした様々な状況の変化が、どうマンションなどの販売価格に影響してくるのか、そこのところを伺いたいと思います。","respondent":"多並都市開発課長","answer":"は……。","voiceIndex":130,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、今、準備組合がいろいろ進めているわけですけれども、準備組合の後、本組合設立になっていくわけですが、準備組合で今、資産評価や補償の話をしているというところで、ここで補償の約束をしたときに、本組合にそれが１００％引き継がれるのか、その担保というのですかね、そこのところも伺いたいと思います。","respondent":"多並都市開発課長","answer":"補償の件ですけれども、これも冒頭説明させていただきましたが、今後、法律に基づく組合が設立した後に、その組合の総会で決議された補償基準に従って算定していくことになりますので、約束したから出すというのではなく、きちんと基準に基づいて出さなければいけない。","voiceIndex":134,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"今の答弁の中で、先にご説明いただいた感じですけれども、この陳情の中に、再開発に合意すれば補償を２０％増額するということで、そういううわさが立っているということですので、本当にこうしたことがあるとすれば、合意させるためにこの補償を出すということで、取引みたいになっているということですので、それは問題ではないかと思うのですが。","respondent":"多並都市開発課長","answer":"区としてはそういう話は直接、今回のこの陳情の前には受けておりませんが、これについては、こういうことがないように、しっかり権利者の皆さんにご説明するようにということで、これは必ず準備組合に伝えていきたいと思っているところです。","voiceIndex":136,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"不適切なことがないようにということなので、それはぜひそうしていただきたいと思います。こうした状況を生み出しているこの再開発というのは、中止にすべきだと思いますけれども、いかがでしょうか。それと、本組合設立のスケジュールは、今回、説明会の中で行われているということですが、その内容について区が知っていれば、お答えいただければと思います。","respondent":"多並都市開発課長","answer":"ここの事業を進めるに当たって、皆さんが集まって、このまちにどういう課題があるかと、それを改善するためにみんなで考えた計画を実現していくということですので、やはりそれを皆さんで考えながら一歩一歩進めていくことが重要であり、それを。","voiceIndex":138,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"３分の２の同意で強制的に再開発できてしまう、つまりは住民の追い出しをしていくというこの仕組み自体、私は問題だと思うのですけれども、区の考えを伺います。","respondent":"多並都市開発課長","answer":"区としましては、やはりその法令で決まっていますから、それを遵守して進めていく事業は、適正にやっていかなければいけないと思っているところです。","voiceIndex":142,"id":"exchange-047"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。毎回お伝えはしておりますが、地元の方が中心となって再開発をするべきであって、それをどちらか、止めるもなく進めるもなく、地域の声を支援していくというのが行政の立場だと思っていますので、誤解とかがあれば、そこは情報提供はしっかりしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":145,"id":"exchange-048"},{"speaker":"こんの委員","kind":"確認","question":"本陳情については、本日結論を出すということでお願いします。先ほどの質疑を聞いておりましたけれども、法的にきちんと定められた手続で進められているということを確認しました。一方で、関係者の方々の様々なご意見があるというところは、引き続き、区も現在サポートしてくださっておりますし、ご意見も伺ってくださっているということもありますので、よって、この陳情については不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、趣旨採択を要望します。住民の生活を壊す再開発をやめてほしいという思い、また、この生活の不安から様々説明してほしいという趣旨は分かりますので、趣旨採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-050"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。先ほどもお話があったように、法的にきちんと、しっかりと進められており、また再開発に関しましても、地元住民が主体となって集まって、いろいろな意見があって、それでつくられるものだと考えておりますので、この陳情に関しては不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"１点目の植栽の件ですけれども、実際にこの白いネットがかけられているということで、その状況を区がつかんでいたらご説明いただきたいのと、あと、ご説明の中で、建設後も風環境を調査しているということですけれども、建設前と後で風速がどれだけ強くなったのか、そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"この白いネットですけれども、資料の２ページ目の写真の奥のほうを見ていただいて、手前が先ほどご説明した２メートルの歩道状空地ですが、その奥に白いネットをかぶっている樹木がある、これのことかと思います。","voiceIndex":158,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"この白いネットは樹木の保護のためということなので、そうすると、今回、落ち葉がいろいろ飛んできて、それを防ぐためのものではないということか、その確認をさせていただきたいのと、あと、やはり保護しなければいけないということでいくと、樹木の生育には、風の問題なのですかね、よくない状況なのかなと思うのですが、樹木の保護をした理由を伺いたいと思います。","respondent":"多並都市開発課長","answer":"落ち葉を防ぐものではないと先ほどご説明させていただきましたが、守るためのものですので、防ぐものではないということです。","voiceIndex":160,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"ましてやベビーカーや車椅子では通れないということになっていますので、これを、もともとあったものではなくて、先ほど沿道植栽で植えたということですので、なぜこれを植えてしまったのかと思うのですけれども、請願にも書いてありますが、人を大事にする視点が欠落しているのではないかと、歩行者の視点というのが欠けていたのではないかと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"風のデータですけれども、これにつきましても、先ほどの説明の繰り返しになってしまうのですが、評価の仕方が、何メートルから何メートルに増えたのではなくて、１年間のデータを全部集約して、その中で、一定の確率であった風が。","voiceIndex":162,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"喫煙所のところです。そのところで今、いろいろ配慮義務なども管理者にはあるということで、やられているということですけれども、実際、この排気口などが通路に面しているということで、臭いもするということで苦情があるということですので、それはぜひ改善していっていただきたいと私も思いますけれども、改めて区のお考えを伺いたいと思います。","respondent":"多並都市開発課長、若生健康課長","answer":"喫煙所の件の最初のご質問ですけれども、これにつきましては、先ほどもご説明した小山三丁目第一地区、これから再開発事業を進めていくことになりますけれども、それを進める際に、デッキでつながることになります。繰り返しになりますけれども、区といたしましては、管理権原者が新たに空気清浄機の設置を検討しているという回答をいただいておりますので、実際、置いてみてどうだったかというところを、きちんと状況を見守りながら、その後。","voiceIndex":166,"id":"exchange-055"},{"speaker":"のだて委員","kind":"確認","question":"最後に１点だけ。この空気清浄機を設置すると、２００種あるとされるいろいろな有害物質というのは取り除くことができるのか、超微粒子化学物質と書いてありますけれども、それを取り除けるのかどうかというところを確認させてください。","respondent":"若生健康課長","answer":"実際にどういう製品でどういう機能のものが置かれて、それがどういう有害物質、いわゆるＰＭ２.５とかというような微粒子等の除去ができるかどうかというところについては、まだその内容について詳しく、現在、設置されているかどうかは所管としてまだ未確認な状況ですので。","voiceIndex":169,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"臭い成分は９９％ということですが、ＰＭ２.５という話もありましたが、やはり有害物質がないようにということで、住民の方に望まない受動喫煙がないようにしていっていただきたいと思いますし、様々再開発が行われたことでいろいろな住環境の悪化が起こっているということで、再開発を進めてきた区としての責任というのですか、そういったところはどのように考えているのか、最後に伺います。","respondent":"多並都市開発課長","answer":"再開発につきましては、造って終わりではなくて、やはり造った後も地域の方と一緒に進めていくものですので、今もやはり新たに再開発は進めていくところでありますので、今も、造った方とこれからやられる方も一緒に情報連絡会という形でお話合いをしながら。","voiceIndex":172,"id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。ご要望の内容として書かれているところが、区道でもなく区の敷地でもないというところが大きくあります。加えて、今回要望いただいているところも、前向きに先方も検討いただいているというところでありますので、それは注視していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-058"},{"speaker":"こんの委員","kind":"意見","question":"本請願につきましては、本日結論を出すでお願いしたいと思います。したがいまして、この請願については不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":176,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。どの項目も住民への悪影響が出ているものですので、ぜひ改善していただきたいと思いますし、今やっているということですけれども、議会としてもそれは後押ししていくということで、採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-060"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。風については風工学研究所で調査を行っているということと、確かに歩道については、私もあそこを通ったことがあるのですが、狭いなとは感じております。喫煙所に対しても空気清浄機が設置されるということで、それについても今後について注視していきたいと考えていますので、これに対しては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-061"}]},{"id":"topic-04","title":"議案審査を再度議題に供します。 それでは、(4)第１０１号議案、令和４年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"議案審査を再度議題に供します。 それでは、(4)第１０１号議案、令和４年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これは分かればでいいのですが、１１月の金額と前年比の割合が分かれば、伺いたいと思います。それと、区が電気料金の契約をしているところはどこになるのかということ、今回予算として１,８８０万円にした根拠を伺いたいと思います。","respondent":"森道路課長","answer":"〔同日後刻に「東京電力エナジーパートナー」と答弁訂正あり〕 それから、根拠ですけれども、補正予算につきましては、まず、現在の電気料金につきましては、使用量相当に対応する、電力使用量によって賦課されるものと、それから。","voiceIndex":188,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"単純に前年比の割合で見たときに、そのままその水準でいくと、もう少しかかるのかなと思ったので伺ったのですが、それは過不足ないようにしていただきたいと思います。今、契約しているのが、東京電力パワーグリッドということで、これだけ上がってきているというところでは、もしもう少し安いところがあれば、契約変更をしていくということもあるのか、そこのところを伺いたいと思います。","respondent":"森道路課長","answer":"東京電力以外で安いところというお話でございました。道路課といたしましても、電気料金を少しでも安くするために、そういった検討委員会をやったこともあるのですが、ただ、その中で、結論としては、今のままが一番適当だろうという形で結論づけて、今に至っているところです。","voiceIndex":190,"id":"exchange-063"},{"speaker":"こんの委員","kind":"確認","question":"１点だけ確認です。街路灯設置数が１万９,２１２基ということで、これは普通の道路に設置してある街路灯のほか、防犯灯というのもありますか。これも含まれているのかだけ確認させてください。","respondent":"森道路課長","answer":"委員がおっしゃるとおり、１万９,０００基のうち、いわゆる区道に設置してある街路灯と、私道防犯灯、そういったものも全て含んで１万９,０００基という形になっております。","voiceIndex":195,"id":"exchange-064"}]},{"id":"topic-05","title":"第１１０号議案、品川区立公園条例の一部を改正する条例","agenda":"第１１０号議案、品川区立公園条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、ボルダリング場をしながわ中央公園に作るということで、こうしたスポーツを子どもたちが身近に感じられ、できるということは、いいと思うのですけれども、今回この条例改正は、有料化をする条例になっております。子どもからもお金を取るということで、小学生以下が１００円、中学生以上が２００円ということですけれども、なぜ子どもからもお金を取るのか、そこを伺いたいと思います。","respondent":"高梨公園課長","answer":"今回、小学生以下で１００円という料金設定をさせていただきました。今回のボルダリング場の有料エリアにつきましては、施設を区切っての専用の利用という形になってあります。ほかの公園施設でも同様です。","voiceIndex":208,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"専用の利用だからということですが、そうすると、この専用の利用というのは何なのかなというふうに思うのですね。ほかの遊具も当然、滑り台があれば滑り台しかできないですし、本当の専用という考え方、そこを伺いたいと思います。","respondent":"高梨公園課長","answer":"過度な負担とならないように、他区の事例等も考慮して、２時間１００円という料金設定をさせていただいたところです。","voiceIndex":210,"id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"以前、地域で聞いた話ですけれども、そうめんを食べる会をやろうと思ったのだけれども、子どもたちがそうめん代、１００円も持ってこられないという状況もあったりして、そうした子どもたちがいる中で、この１００円、２００円を取っていくというのは、やはりやめるべきだと思いますけれども、いかがでしょうか。","respondent":"高梨公園課長","answer":"ただし、やはり初めてやる方等に対して、お金を払わないとできないのかといったところは、なかなか、そこも一定配慮すべきだという考えの下から、無料エリアを設置して、初めてやるお子さんに対して気軽に遊んでいただける、体験していただけるといったところについても。","voiceIndex":212,"id":"exchange-067"},{"speaker":"のだて委員","kind":"意見","question":"いろいろ議論があったということですけれども、やはり一定無料エリアを設けたというのは、確かに配慮したのかなと思うのですが、やはりそれでも有料化していくということは、家庭の経済力などにも影響してきますし、子どもに等しくスポーツをやれる機会を与えていくためにも、やはり有料化すべきではないということは言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-068"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ボルダリングを今回つけるということで、今、様々お話いただきましたけれども、壁を登るスポーツですから、安全性に配慮しなければならないということで、プールと同じ考えだと思っていて、プールも監視員の方がいて、そこは一定程度ほかの方を排除してというか、占有させてやっていくということで、そこにお金を払って入るということに関して異議を唱える方というのは。","respondent":"高梨公園課長","answer":"今後の公園の方向性といたしましては、有料施設をどんどんつくっていくというよりは、やはりその時代時代のニーズをしっかりと捉えて、小さいお子様も気軽に体験できるような規模でも構わないと思いますので、そういったものを積極的に。","voiceIndex":216,"id":"exchange-069"},{"speaker":"芹澤委員","kind":"意見","question":"ボルダリングに限らず、今、お話しいただいたとおりですが、子どもたちもその時代時代に合わせて、いろいろな遊びであったり遊具を経験したいのだろうと思っていますので、様々な可能性を検討していただいて、その時々のすばらしい公園をつくっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":218,"id":"exchange-070"},{"speaker":"こんの委員","kind":"質問","question":"区内団体、それから区外団体が使われるときの、いわゆる団体の方が使用するときの何かルールというのはあるのでしょうか。というのは、いわゆる団体でお教室を開くというような、有料でお教室を開くという団体も使うのかどうなのかといったところとか、あるいは、予約の取り方とか、そこら辺のスキームというか、これを運用するに当たって具体的なものが見えているようでしたら、その辺、お知らせください。","respondent":"高梨公園課長","answer":"予約の取り方等々ですが、基本的には今現在、しながわ中央公園の多目的広場、グラウンドですね、あそこと同じような運用を考えているところですが、それを軸といたしまして、これから詳細は詰めていこうという段階です。","voiceIndex":220,"id":"exchange-071"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひお願いしたいなというところです。安全面、初めて使う方も、やってみたい、だけど安全に使うというところは、どなたかやはり専門的に見ていただく方がそこにいらっしゃると、大変助かるなというところと、お教室があると、安全に利用していただくことを学べるかなというところですので、ぜひその点はお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-072"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目ですけれども、すみません、先ほどご説明があったのですけれども、少し聞き漏らしてしまいまして、管理する方がいるスペースはこの平面図のどのあたりなのか、もう一度教えていただきたいというところと、２点目が、幼児用の無料エリア、高さ１.５メートルと１.８メートルがそれぞれあるのですけれども、幼児感というのは大体どのくらいの年齢を想定されているのかというところを、教えてください。","respondent":"高梨公園課長","answer":"３点目、万が一のけがの対応といったところですが、基本的に通常の利用でのけがであったり、そういったところの責任は利用者個人でといったところですが、当然、緊急の場合があると思いますので、運用時間中は管理事務所に必ず人間がいる体制を取ってありますので。","voiceIndex":224,"id":"exchange-073"},{"speaker":"松永委員","kind":"質問","question":"それぞれご説明、ありがとうございました。私からは何点かあるのですが、１つは、管理者についてですが、この人たちというのはどういう方たちなのか。もう一つが、先ほど有料施設に関しては定員が１２名ということだったのですが、無料施設については何人でもオーケーなのか、それについても伺います。無料エリアについては、雨が降った場合は使えるのかどうか。","respondent":"高梨公園課長","answer":"図で言う右側の部分に出入口を作る予定ですけれども、利用受付をした人がその出入口から入って、黄色の有料エリアのボルダリングウォールを使えるという仕組みを考えてあります。","voiceIndex":227,"id":"exchange-074"},{"speaker":"西村副委員長","kind":"意見","question":"１点だけ、すみません。２１時まで利用できるということで、大分時間も子どもにとっては遅いかなと思っていまして、見逃していたら申し訳ないですが、保護者同伴などのルールを何時以降とか設けるのか、それだけお聞かせください。","respondent":"高梨公園課長","answer":"そこまで八潮北公園ほど遠くもないですし、日常使いができるような設備ですので、ただ、小さいお子様がやはり高いウォールに登ってというようなことがありますので、一定有料エリアの高いウォールについては、考えなければいけないのかなですが、現在、そこら辺の安全面を。","voiceIndex":230,"id":"exchange-075"},{"speaker":"のだて委員","kind":"意見","question":"親の経済力に関係なく子どもたちがスポーツに接する機会を設けるべきであり、小中学生からもお金を取る有料化ですので、反対。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":235,"id":"exchange-076"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"１点だけです。この公園の今、ご説明いただいたことは理解いたしました。関連で、これ、樹木は街路樹もありますので、その点についてはどういうふうにされるのか。こうしたことは街路樹でもあるかなと想像するのですけれども、その点はいかがでしょうか。","respondent":"森道路課長","answer":"陳情等がございましたら、その都度対応していますので、これからもなるべくそういった事故がないように、しっかりと管理をしていきたいと考えています。","voiceIndex":243,"id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"再発防止に努めていくということなので、ぜひそれはお願いしたいと思います。それで、今回、樹木の枝というのはどのくらいの大きさだったのかというところと、それがなぜ分かったのかというふうに思うのですが、被害者の方から問合せなどがあったのかどうか、そこを伺いたいと思います。","respondent":"高梨公園課長","answer":"枝ですけれども、こちらはソメイヨシノ、桜の枝、約３メートルの大きさの枝でございました。","voiceIndex":246,"id":"exchange-078"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この間、継続になっている請願・陳情があると思います。今期まだやっていないものもあると思うので、今期が終わる前にその審議をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":65762,"voices":255}},{"id":"r04-20221222-9","meetingId":"r04-cm12","date":"2022年12月22日","dateIso":"2022-12-22","committee":"文教委員会","time":"午前１０時００分～午後 ０時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"教育委員会のところだけでいいのですか。所管質問。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"１２月２０日の渡辺裕一議員の部活動の地域移行についての質問なのですが、来年度から段階的に試行が始まり、２０２５年度末以降の目標が示されているこの地域移行なのですけれども、準備状況等についての質問への答弁がありましたが、改めて、現時点で区教育委員会が考えている検討内容とスケジュールを教えてください。文教委員会での報告はいつ予定しているのかも伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"１２月２０日のこんの議員の質問の防災対策の中で、児童・生徒の登下校中の発災時のことについて、安否確認の対策についてご答弁があったかと思うのですけれども、そこの部分でたしかタブレットで帰宅を知らせる訓練をした学校もあるなどというお話があったのですが、登下校中に本当に災害が起きたときの対策がどうなっているのかというところがいまいち分からなかったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"}]},{"id":"topic-02","title":"第１１７号議案、指定管理者の指定","agenda":"第１１７号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"裏面の選定の経緯の（１）なのですが、３事業者とありますけれども、Ａ、Ｂ、Ｃ、それぞれ何事業者だったのか、そこら辺の応募の件数をもう少し教えていただきたいというのが１つです。それと、選定基準の中に持続的な配置という言葉がありますけれども、勤めている方の平均勤続年数、そこら辺は何年ぐらいになっているのか、教えてください。","respondent":"吉田品川図書館長","answer":"３番目の平均勤続年数ですけれども、おおむね１０年以上は勤めているという話を伺っているところです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこで働くということで、私たちとしては、図書館に指定管理を導入するというのはやるべきではないという考えなのですけれども、ただ、私たちだけが言っているわけではなくて、総務省も図書館については指定管理者制度を肯定的に捉えていない通知などを出していると思いますが、その総務省の通知はどのような内容なのか、そしてそれについて、あえて指定管理をしているわけですけれども。","respondent":"吉田品川図書館長","answer":"公募の件数が少なかったですけれども、この施設を指定管理にするに当たりまして、こういう施設ですよというご案内だとか、最初に応募に関する説明をするのですが、その際には６者参りました。","voiceIndex":16,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"平均勤続年数については、ぜひ、こういう指定のときもそうですけれども、モニタリングなどでも、それはきちんと出してもらうように求めていただきたいなと思います。安定して司書を確保するというのであれば、区が直接そういった方をしっかりとした待遇で雇うということが必要だと思いますし、それは指定管理に委ねるという理由にはならないと私は思いますので、意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"施設等の説明などをしてから、申込みは４者にとどまったということだったのですけれども、１点気になるのが、指定管理料が適正なのかという部分で、人件費のところなどがなかなか厳しかったり、事業者的に運営がどうなのかなという部分を危惧しているのですけれども、そこのところを伺いたいということと、あと。","respondent":"吉田品川図書館長","answer":"その辺、いきなり６０％まで上げるというのも一つの手かもしれませんけれども、まずは５０％のところから始めて、今まで設定がなかったところにつきましては、新たに今回から設定を付け加えたところです。","voiceIndex":20,"id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"申込みが４者あった中で、３者だったのですよね。ごめんなさい、聞きたいことは、決定されなかった事業者は、どこに課題があったのかというところを確認したいと思いました。","respondent":"吉田品川図書館長","answer":"申込みがあったのは、実際は３者になります。最初に６者が現地見学などに来られた中で、申し込まれなかったのは２者です。ただし、残りの４者のうち、２者が共同企業体として、ＴＲＣ・リディアグループという形で申し込まれたので、これは１者と換算いたします。","voiceIndex":22,"id":"exchange-008"},{"speaker":"安藤委員","kind":"意見","question":"反対です。現場で働く指定管理者の事業者の皆さんは頑張っていらっしゃると思いますけれども、そもそも図書館業務は指定管理で行うべきではなく、区が直営で担う専門性や経験を蓄積できる職場環境に責任を持つべきだと思います。それが図書館文化の育成と区民サービスの向上にもつながると思います。したがいまして、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"１２月２１日ののだて稔史議員の子育て支援の質問なのですが、株式会社立認可保育園の人件費率が３割台と低いことについて改善が必要ではないかと質問したのですが、人件費率の引上げだけでなく、総合的に支援が必要という答弁だったのですけれども、人件費率は職員の給与改善につながり、ひいては保育の質確保に重要な指標だと思うのですが、改善が必要という認識はないのかということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-010"}]},{"id":"topic-03","title":"第１０１号議案、令和４年度品川区一般会計補正予算（歳出等 文教委員会所管分）","agenda":"第１０１号議案、令和４年度品川区一般会計補正予算（歳出等 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"商品券なのですけれども、なぜ未就学児までのみを対象にするのか、伺いたいと思います。全ての子育て世帯を対象にすべきではないかと思いますが、いかがでしょうか。学校のほうですけれども、２番目に地下通路撤去とありますが、この状況をもう少し教えていただきたいのと、あと、「等」と書いてあるのですけれども、何かほかにあったのか。そこら辺について伺いたいと思います。","respondent":"染谷子ども家庭支援センター長、飛田子育て応援課長、森学校施設担当課長、勝亦学務課長","answer":"ゼロ歳児が対象かどうかという部分につきましては、別の保健センターで実施している事業との兼ね合いを含めて、今回。大体１つのところ、６０から７０名ぐらいが平均になるのかなと思いますけれども、子ども食堂の周知がされてきたと私は認識しております。第四日野小学校につきましては、基礎で掘った土が、想定よりも含水率が高いことが分かりましたので、それについての変更です。学校の光熱水費ですけれども、一括しての支払いを行っているところです。","voiceIndex":54,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれありがとうあります。ここが聞きたかったというところですので、お答えください。やはり学生がかなりしんどいということで、今こそそういう奨学金を検討すべき時期ではないかと思うのですけれども、この間も繰り返し求めてはきたのですが、まだ高校生の給付型奨学金が始まったばかりなので伺ってしまったのですが、始まったのは２０１８年度からなので、もう４年半以上たっているのです。","respondent":"飛田子育て応援課長、染谷子ども家庭支援センター長","answer":"１,９２０世帯が多いか少ないかというところなのですけれども、私は妥当な数かなと考えています。今回、こちらの実施が可能となった場合につきましては、今まで行っていた１歳・２歳の対象の方も含めて、改めて広報。現在、高校生については給付型〔同日後刻に「返還免除型」と答弁訂正あり〕の奨学金をやっているところですが、大学生につきましては、今現在。","voiceIndex":59,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"大変な状況が広がっておりますので、ぜひ大学生の給付型奨学金の検討を先にしていただきたいと思います。区立学校の電気なのですが、再生可能エネルギー電気は、原油の由来ではないので、高騰が抑えられているということはあるのでしょうか。現状として、区立学校の電気なのですが、どれだけ再生可能エネルギーの電気で賄われているものなのか、伺いたいと思います。","respondent":"染谷子ども家庭支援センター長、飛田子育て応援課長、勝亦学務課長","answer":"こちらの事業につきまして、実際に事業を開始した際には、こちらのほうで対象者を抽出させていただきまして、個別に直接通知を差し上げているところです。先ほど奨学金のところですが、大学生のところで給付と言ってしまったのですけれども、貸付も含めて、給付だけではなく、奨学金全般ということで。こちらにつきましては清掃工場のごみの焼却の熱からの発電をしている状況でございまして。","voiceIndex":63,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ区立学校の再生可能エネルギー由来の電気の使用などは広げていっていただきたいと思います。最後、私立保育園の物価高騰の対応の補正予算についてお伺いします。認証保育園も結構しんどいと思うのですけれども、こちらについては対象になるのか。どちらがやるのか。考え方として、在園児数に応じて給付ということなのですけれども、これは理由はなぜなのか、伺いたいと思います。","respondent":"中元保育支援課長、飛田子育て応援課長","answer":"今回、どういう積算根拠かというところは、こちらのほう、検討しまして、施設によって規模が違うので、在園児数に応じて算出するのがよいのではないかと。言い間違いですので、訂正いたします。大学生については、現在、大学生の受験の支援というのはやっておりますので、また今後も声を聞いていきたいと考えております。","voiceIndex":67,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"対象年齢の理由、私も何でかなと思っていて、子育て世帯、大きな子どもたちがいると、やはりその分食べますし、必要だなと思っていたのですけれども、先ほどの説明では、今回、ゼロ歳を除く就学前児童が対象になった理由が、そのほかの年代は子ども未来部以外の支援があるということだったのですが、分かる範囲で、どういった支援があるのかということと、あと、今回の商品券事業をお知らせする際に。","respondent":"飛田子育て応援課長、染谷子ども家庭支援センター長、中元保育支援課長、森学校施設担当課長","answer":"大体各子ども食堂、月に１回から２回渡しているということで、２月・３月にかけて、３回に分けて配布予定と考えております。子育てサポート商品券につきまして、今回の対象以外の部分についてどういった支援があるのかというご質問につきましては、先ほど私。なかなか歩行が困難だったり、出かけることができないということで、施設のほうで配布ということがあるかと思いますが、保育園、幼稚園の場合。今後もこういうことは起こるかもしれませんけれども、できるだけないように、調査は丁寧に行っていくつもりです。","voiceIndex":71,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"１箱１,８００円とか。先ほど子ども未来部以外の支援のところで、物価高騰等のお話があったのですけれども、それは分かっているのですが、子育て世帯に対しての支援サポートという考え方だったら、やはり年齢を区切るべきではないなということで、でも、前回よりは拡充されているので、ぜひ次からはもうちょっと広げていただいて、子育て世帯も年齢を広げていただきたいということを強く求めたいと思います。","respondent":"中元保育支援課長、染谷子ども家庭支援センター長、飛田子育て応援課長","answer":"４月当初と、また、秋口にも文書が東京都から出まして、各私立保育園、申告制で、手挙げ方式できちんと検査キットが園に送られるという形で。子育てサポート商品券事業の対象年齢ですけれども、今回、就学前を対象とさせていただいた部分につきましては、繰り返しになりまして恐縮ですが。今回の購入については、しながわ子ども食堂ネットワーク事務局、また、フードパントリーを現在行ってくれております子ども食堂にも声をかけまして。","voiceIndex":76,"id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"例えばこれは区内事業者限定にするのかどうかとか、あと、例えばいわゆる訳あり品、Ｂ級品と言われる、中身に関して品質は問題ないけれども、パッケージであるとかに問題があって流通させるのが難しい商品を扱っている業者にするであるとか、そこの選定方法についてと、もう一つが、１世帯当たり６００円掛ける３回という部分なのですけれども。","respondent":"飛田子育て応援課長、中元保育支援課長","answer":"６００円の想定は、そもそも子ども食堂で、今、フードパントリーでの一回分のお弁当代を想定すると、６００円相当かなというところとか、あと、今、ストックがあるものとか、それにプラスアルファということで。私立幼稚園の給食提供園と給食非提供園の線引きですが、こちら、正確な資料が手元にないのですが、数値でいいますと、給食ありのほうが３,０８０人、給食なしが１７０人という規模ですので。","voiceIndex":81,"id":"exchange-017"},{"speaker":"くにば委員","kind":"意見","question":"子ども食堂のほうですけれども、購入業者に関しては一般競争入札というご答弁だったと思うのですが、１世帯当たり６００円という部分、もちろん可能な限り安く購入できる業者で、あとは、もちろん栄養バランスであるとか、子ども食堂ネットワーク事務局と相談の上だと思うのですけれども、予算をできる限り多くの品目、多くの食材を安く購入して、活用していただければと思います。これは意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"地下通路撤去に関して、あそこは公園と学校の間の区道ですかね、区道をどんなふうにまたいでいて、地下何メートルぐらいなのか、参考までに教えてください。お話の中だと、区道の下を通っているような印象があるので、その部分が１つと、併せて、毎年、区道は空洞調査をやっていますよね。","respondent":"森学校施設担当課長","answer":"地下通路の部分、区道の下にもございました。調べた結果ですけれども、道路面から約２.４メートルのところにトンネルの上端が来ているような状態です。空洞調査でどうだったかというところなのですけれども、詳しくは聞いていないのですが、特に引っかかっていなかったようです。","voiceIndex":86,"id":"exchange-019"},{"speaker":"渡部委員","kind":"質問","question":"２つ伺います。最初は、物価高騰に対応した云々のところで、先ほどもいろいろ質問があって、私立保育園１万１,０００円でというところの中で、私立幼稚園の５,５００円とか２,５００円、それもいいです、分かるのですけれども、その算定根拠といったらおかしいのですが、保育園が１万１,０００円で、何で幼稚園は５,５００円だったのですかというところだけ、分かりやすく聞きたいです。","respondent":"中元保育支援課長、染谷子ども家庭支援センター長","answer":"初めに、物価高騰のこちらの算出根拠ですけれども、昨年度の光熱費や食材費等、幾ら払っていたという実績を各施設からいただきまして。子育てサポート商品券事業につきまして、１月１日基準日として事業を実施することによるタイトなスケジュールというお話につきましては、委員からお話しいただきましたとおり。","voiceIndex":89,"id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"保育園が１万１,０００円で、私立幼稚園は何で５,５００円なのかだけ、聞きたいです。それ以外はいいです。分かりました。商品券のほうは、例えば私のところに５歳児と２歳児がいるとしたら、２歳児のときに済んでいるわけですよね。それは感想です。混乱のないようにお願いします。１万１,０００円と５,５００円の違いを。","respondent":"中元保育支援課長","answer":"認可保育園ですと、大体９０人規模だったりするところが多いです。私立幼稚園ですと、そこまでの人数は今いらっしゃらないと思うのです。その辺のところで、どうしても基本的な光熱水費とか食材費の調査をかけたときに、既に差が出てしまっている。","voiceIndex":92,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"すみません、子育てサポート商品券のところなのですけれども、区内共通商品券について、個店とかでも使えるのかというところを伺いたくて、使えるお店とかの周知がどうなっているのかということを聞きたいです。","respondent":"染谷子ども家庭支援センター長","answer":"区内共通商品券を利用できる店舗につきましては、現在、品川区内に個店も含めて約２,０００店舗ございまして、品川区商店街連合会のホームページに利用できるお店が載っているかと思いますので。","voiceIndex":96,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成ですが、子育て世帯、学生等の苦境に照らして、対象や内容はまだまだ不十分で、区の独自財源も活用したさらなる支援策が必要だと思います。この実施を求めつつ、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"賛成します。先ほども言った保育園での抗原検査については、東京都の実施ということも分かるのですけれども、やはりそういうところも含めて拡充していただきたいというのと、子育て世帯の年齢についても拡充を求めての賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-024"}]},{"id":"topic-04","title":"令和４年陳情第５８号、八潮団地内にオアシスルームの整備を求める陳情","agenda":"令和４年陳情第５８号、八潮団地内にオアシスルームの整備を求める陳情","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"今も説明いただいたとおり、たしか決算特別委員会でも、これは進んでいる話なので、地域の方から請願が云々とか陳情が云々ということなく、順調に進めてくださいというところで終わりだと思うので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"私も田中委員と同じです。ぜひ議会としてもさらに加速させる意味でも、逆に言うと、これ、不採択にはできないなと思います。それで質問は、今、既に検討を進めているということですが、最新の検討状況をお伺いさせていただきたいと思います。","respondent":"中元保育支援課長","answer":"既に令和４年度段階で、八潮の中で、こちらにもお話がある、それぞれの候補地がございましたので、それぞれ検討していますが、具体的な状況につきましては、今後、皆様にしかるべきときにしかるべきタイミングで、こちらの場でご報告させていただきたいと思います。","voiceIndex":115,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"大体いつ頃の開設を目指していらっしゃるのか、目標について伺いたいと思います。","respondent":"中元保育支援課長","answer":"その辺のところ、スケジュール感につきましても併せましてしかるべきときにご報告させていただきたいです。","voiceIndex":117,"id":"exchange-027"},{"speaker":"若林委員","kind":"質問","question":"すみません、オアシスルームから少し話を広げて、八潮地域について、多世代交流的なところ、そういう地域の声もあるように伺っております。そこら辺も視野に、また他課との連携というところもあると思いますけれども、八潮の皆さんに喜んでいただける、そういった視点で、オアシス、また、その先もというところでご検討いただければ幸いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-028"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらの八潮団地のオアシスルームに関して、私からも何度か議会のほうで要望させていただいていた部分で、特に商業施設パトリア品川の２階であるとか、具体的に私もちょうど申し上げて、なかなか民間の施設では難しいというご答弁を当時いただきました。今、現行で既に検討が着実に進んでいるというところで、それをしっかりと進めていただければなと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-029"},{"speaker":"田中委員","kind":"確認","question":"ごめんなさい、先ほどからご答弁で、しかるべきときにご報告ということだったのですけれども、そんなに遠くないということでいいのですよね。何年も、１０年も先とか、そんなことはなくて、なるべく早いということを確認したいと思って、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-030"},{"speaker":"安藤委員","kind":"意見","question":"結論を出すで、採択なのですけれども、言うまでもないのですが、保護者の願いであり、在宅子育て支援の充実につながる内容ですし、これ、不採択にする理由がないので、不採択というのは私は理解できないです。採択をして、議会としてしっかりと意思表示をするということは、それはそれで必要ではないかと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-031"},{"speaker":"くにば委員","kind":"質問・要望","question":"本日結論を出すで、不採択です。もうこの内容は、丸々、私がそもそも思っていた内容なのですけれども、しっかりと計画が進んでいるということで、そちらを進めていただきたいということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"児童センターなのですけれども、これで何施設中何か所目の建て替えになるのか、あと、何か所くらい残っているのか。建て替えの順番ですとか時期についての考え方があれば、教えてください。それと、区立保育園も、今回、何園中何か所目ぐらいの建て替えで、あと何園ぐらい残っているのでしょうか。伺います。","respondent":"廣田子ども育成課長、初貝保育教育運営担当課長","answer":"その後、今現在、一本橋児童センターの工事が進んでおりまして、今回の案件につきましては中原児童センターをやるのですが、同じ種地を使いまして東五反田を今後続けて行うという予定がありますので、２５館中、完了が２件。仮施設であったり、あとは、先ほどもご説明ありましたけれども、合築の施設等もありますので、明確に順番というところは、一括してというところはなかなか難しいのですけれども、計画を立てていきたいと考えております。","voiceIndex":139,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"三ツ木保育園なのですけれども、既に去年、民営化していまして、大井保育園も民営化対象園で、約２年３か月後の令和７年、２０２５年４月に民営化するという予定にされています。今回、大井保育園を改築対象に選定したことについて、老朽化以外の理由について伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"大井保育園の改築の理由ですけれども、老朽化以外ですが、先ほども少しご説明させていただいたように、仮の施設を建てられる場所であったり、あと、こちらは複合ではないですけれども、そういったところの施設の状況を鑑みまして。","voiceIndex":142,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"過去の民営化対象園の改築について質疑がありまして、当時の所管の課長などは、施設の水準が高いほうがよりよい委託事業者を確保しやすいという答弁を繰り返しております。民営化を進めるための改築という考えもあるのではないでしょうか。もう一度伺いたいと思います。大井保育園の事業者の募集時期と選定はいつ頃になるのか、伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"改築の理由に関しましては、先ほどもご説明させていただいたとおり、あくまでその保育園が老朽化しているかといったところをまず一義的に考えさせていただいて、改築を進めているところです。","voiceIndex":144,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"先ほど説明があったように、大体保育園の老朽化度合い、築年数は変わらないですよね。募集時期なのですが、前々年度ということでしたけれども、となりますと、既にある程度、いつからになるのか、具体的に、こういう建て替えの新しい施設の契約関係なども出ていますけれども、施設の設計等に当たっては、事業者あるいは民間などと打合せなどもしているのでしょうか。伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"事業者の選定に関してです。大井保育園は令和７年４月に民営化を予定していますので、令和５年度ですね、来年度、プロポーザル方式によって事業者を選定する予定です。","voiceIndex":146,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"民営化することが決まっている園なのですよね。区としてはですよ。そういう建て替え計画などももう設計が出ているのですけれども、そういった設計を策定するに当たって、民間事業者等といろいろ打合せなどはしているのでしょうかと伺ったので、お答えください。保育士の配置基準や給食にかける費用など、民営化園というのは変わるのでしょうか。何でこんなことが起こるのか、ご説明いただきたいと思います。","respondent":"初貝保育教育運営担当課長、立木保育課長","answer":"保護者の皆様からも、民営化後も含めて、きちんとご意見をいただきながら進めているというところで、対応しています。先ほどの設計のところなのですけれども、今、担当課長から話がありましたのは、設計業者との打合せの話でございまして、実際に民営化の運営を委託する事業者は、来年度のプロポーザルで決定しますので。","voiceIndex":148,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。私が伺ったのは、区立民営と言いますけれども、民営化と言うのですけれども、業務委託なのです。何で保護者からそういうお声が出るのかなと思って、民営化によって保育士の配置基準が変わるのでしょうか。給食の献立が変わる、これは事実なのでしょうか。ですから、そういうことが起こっているという声を区はつかんでいないのでしょうか。伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-038"},{"speaker":"若林委員","kind":"意見","question":"質疑を続けていただいて結構なのですが、今回の議案は保育所条例の一部を改正する条例ということで、移転先とか工事とかというところの条例改正です。何やら質疑の内容が民営化について深掘りしている質疑になっておりますので、委員長に進行のご配慮をいただければ。効率的な委員会の運営についてご配慮いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":152,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは条例に関わる審議をしているわけですよね。今回、大井保育園は民営化の対象なのですから、それに関わる質疑をしているわけであって、ぜひ先ほどの質問について答弁をいただきたいと思います。","respondent":"立木保育課長","answer":"保護者からお声が上がっているものは、私どもも、委託元ですので、そこは把握した上で、事業者としっかりやれるよう、話をさせていただいているです。基準その他は、一切、区立保育園と変えているところはございません。","voiceIndex":154,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"そこの保育園の地下にはリニア中央新幹線と第二戸越幹線の２つが通るということで、どういう対策がされているのか。仮施設では、そういったバンドなどができるような、音響施設とかが整っているのかとか、ちょっと具体的なところになってしまうのですけれども、どうですかということを伺いたいです。","respondent":"立木保育課長、廣田子ども育成課長","answer":"リニアの工事に関しましては、今のところ、私どもに特にご案内等もございません。工事に関しては、施工会社、それから工事所管のほうもしっかり対応してやっているということで認識しています。中原児童センターでやっているバンドであるとか、そういう機能の部分については、仮設でも可能な限りつくってもらうのですけれども、今、バンドについては、コロナ禍で、個人では入って練習させているのですけれども。","voiceIndex":157,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"保護者、利用者への周知の部分は分かりました。保育園のところです。本当に課題が多いところで、防音対策とか、そういったこともされているのかなというところを伺えればと思います。今、バンドでもみんなで練習というのができない状況で、個別で練習している子とかもいるので、そういった子たちが練習できる環境がなるべく整ったらいいなということを要望したいと思います。","respondent":"立木保育課長","answer":"工事に関しましては、安全に配慮した上で、しっかり長く使えるような形で、施工会社とともに施工しております。防音対策等につきましても、必要な性能等は確保できていると認識しています。","voiceIndex":160,"id":"exchange-042"},{"speaker":"若林委員","kind":"確認","question":"大井保育園について、若干確認させてください。改築に当たって、工事概要をお聞きしたいと思います。いわゆる周りの環境がどうなっているのかの確認をします。立会道路、立会川というのですか、があったり、あと、民家も隣接しているというところもあると思います。","respondent":"初貝保育教育運営担当課長","answer":"大井保育園の工事に関してのお問合せと認識しております。本園舎に関しましては計画の説明会も実施しておりますし、大井保育園に関しては工事説明会が今後予定されておりますので、そちらのほうで丁寧に住民の方の意見を聞き取って、真摯に対応していきたいと考えております。","voiceIndex":163,"id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"反対です。施設の老朽化による改修や建て替えはもちろん必要なことですが、今回の改築は、保育の公的責任を後退させ、中止すべきである民営化を進めるためのものです。改築して施設を新しくして、民間委託を進め、将来は民設民営、完全に売り渡すという流れの中での改築ということであり、認められません。反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":37106,"voices":186}},{"id":"r04-20221222-5","meetingId":"r04-cm12","date":"2022年12月22日","dateIso":"2022-12-22","committee":"総務委員会","time":"午前１０時００分～午後 ２時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 初めに、(6)第１１２号議案、大井保育園改築工事請負契約","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 初めに、(6)第１１２号議案、大井保育園改築工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この大井保育園が老朽化に伴う改築というご説明でしたが、築何年なのか教えていただきたいと思います。それから、工期が令和６年１２月１３日ということなのですけれども、これはいつから始まるのか。仮園舎への移転というのはもう済んでいるのか、その点についても伺いたいと思います。","respondent":"東野経理課長","answer":"工事の工程ですが、令和５年４月から解体工事を始めまして、その後、基礎工事、建物の躯体工事等を行うということで聞いてあります。それから、ちょうど南側のところです、真ん中のところ、空いている部分は、園庭の予定です。","voiceIndex":10,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点についてお聞かせいただきたいのと、この大井保育園は、令和７年４月からは民営化の方針が出されていると思うのですけれども、そのこともあって改築されるということもあるのか、その点についても伺いたいと思います。それから、この保育園の建て替え計画というのは、基本的に古い順番からやっていくという考え方であるのか、その点についても伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"令和７年４月からの民営化との関係ですけれども、これは基本的に、先ほど説明させていただいた建て替えは建て替えとして適切にやりながら、民営化に関しては、それとはまた別に検討を進めていて、民営化を決定したです。","voiceIndex":12,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところでいえば、建て替えはこれからかなり計画していかなければならないと思うのですけれども、そこら辺は、今後どのように計画的に建て替えをしていくのかという考え方としては、どういう状況になっているのかも伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"建て替えの計画に関しましては、やはり施設の状況であったり、あとは、老朽度合いであったり、総合的に判断しながら計画を順次進めてまいりたいと考えております。","voiceIndex":14,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"保育園の工事のときは、私はいつも避難経路。２方向避難が確保されているのは当然だと思うのですけれども、これ、１つは、避難滑り台というのは、３階からずっと回る感じなのですか。滑り台になっているのかと思うのですけれども、最低２方向避難だと思うのですが、この避難滑り台が１つなのかということの確認と、それから、ほかは一般的な昇降口といいましょうか、出入口がもう１つというふうに考えるのか。","respondent":"東野経理課長","answer":"２階、３階のところをご覧いただきますと、ちょうど端に当たる部分に階段の経路があります。こちらで２か所の避難、２方向避難の経路を確保しているということになります。加えて、３階からの避難用の滑り台がありますので、計３か所の避難経路があるということになります。","voiceIndex":17,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"はい、分かりました。区立保育園ということであると、障害児も受け入れているかと思うのですけれども、その辺についてはどうなのでしょうか。そういう子は下の階のほうの遊戯室に行くとか、そういう配慮がされているのか。その辺について伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"もちろん避難訓練というのは、個々のお子様の特性に合わせて、そこも配慮しながら十分行ってまいりますので、滑り台を使用するかどうかも含めて、運営の中できちんと計画を立てて、いざとなったときに対応できるように運営をしていきたいと考えております。","voiceIndex":19,"id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"必ずしも全部ハードの部分で確保する必要はないというふうに私も理解しているのですけれども、この滑り台型の避難については、これは回っていく形だからいいのかなと。よくシューッといってしまうものは、上体が確保できない障害児とか障害者にとっては避難が難しいというふうに聞いたので確認させていただきました。その辺、運営上配慮されているということであれば結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"設備等は、エレベーターはもちろん、それから蓄電設備、太陽光発電、様々工夫をされていると思います。ただ、契約金額、約７億７,８００万円ということで、このような建物では費用がちょっと高いような気もするのですが、どこの部分に一番費用がかかっているのか、その点を教えてください。","respondent":"東野経理課長","answer":"こちらも聞いている範囲でお答えしたいと思います。委員がおっしゃるところでいきますと、建設資材の高騰という部分に当たるものと思われます。直近でいきますと、一本橋保育園・児童センター改築工事請負契約があったのですが、こちらは令和４年第１回定例会の議決です。","voiceIndex":22,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"最近のあれですから、物価も、確かに資材も高騰しているということは分かるのですが、年々、毎回審議すると、どんどん高騰しているような気がするので、積算は積算業者にお願いはしていると思うのですが、ちょっと気になる部分もあるのですが、いい施設を造っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"},{"speaker":"せらく委員","kind":"質問","question":"ご説明いただき、ありがとうあります。今回の大井保育園の建て替えに伴って、受け入れの児童の数などは増減があるのか、伺いたいです。図面に描いてある２階部分の幼児トイレの数なのですけれども、これは見た感じですと、３か所あると思いますが、今のところ、３・４・５歳児の人数が８１名となっていて、児童に対してのトイレの数は、基準があるのかどうか、そこを伺いたいです。","respondent":"初貝保育教育運営担当課長","answer":"定員のお話です。定員に関しましては、大井保育園は、今、１３１名ですけれども、変わらず同じ定員で予定しています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"せらく委員","kind":"質問","question":"受け入れの人数は同じ１３１名ということで、かしこまりました。この大井保育園は、０歳児の受け入れがないということで、１歳児からなのですけれども、今、育休を延長される方も大分増えておりまして、０歳児が定員割れという保育園もあると聞いています。幼児トイレの数なのですけれども、児童何人に対してトイレ何基という具体的な数字は出されていないのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"設置基準というところでは、ちょっと今、手元に資料がないのですが、ただ、例えば指導検査の中で、そういったところのチェックという項目はあるというようなところです。","voiceIndex":27,"id":"exchange-010"}]},{"id":"topic-02","title":"第１１３号議案、第二戸越幹線整備工事（北品川特殊人孔等整備）請負契約","agenda":"第１１３号議案、第二戸越幹線整備工事（北品川特殊人孔等整備）請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですけれども、これ、特殊人孔等となっているのですが、立坑ですよね。シールドマシンを入れる立坑のことだと思うのですけれども、それでいいのでしょうか。「特殊」が付く理由は何なのか、伺いたいと思います。","respondent":"栗原河川下水道課長","answer":"ご質問いただきました特殊人孔の「特殊」の意味ですけれども、人孔はマンホールを表しており、特殊というのは、マンホールの種類にも様々ございまして、既存のコンクリート製品を組み立てて設置する比較的深さの浅いマンホール、これを一般的な人孔、マンホールと呼んでおります。","voiceIndex":42,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"特殊人孔等整備ということで、ただ、立坑の工事がこれだけかかります、こういう整備をしますということで、まだこれからシールドマシンのほうは、次の議案のほうになるということですか。それとも、ここにシールド工事も、何ｍかは入っているということなのですか。「インバート工延長９６０ｍ」と書いてあるのですが、その辺を教えてください。","respondent":"栗原河川下水道課長","answer":"そこを仕上げる工事、これを二次覆工といいます。こちらの工事と、トンネルの中にインバートといいまして、人が通れるような平たい場所と、水が流れやすいように溝をコンクリートで造る工事が含まれているものです。","voiceIndex":48,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"人孔等を造るということで、恐らく深さも大分深く掘るのだと思うのですが、この辺は、地盤的に弱いような感じもするのです。もちろん事前に調べていらっしゃると思うのですけれども、その辺は、安全度というのですか、どういうふうにお考えなのでしょうか。教えてください。","respondent":"栗原河川下水道課長","answer":"工事の前にはボーリング調査を行いまして、当該地層を調査しておりますが、シールド掘削の地盤に関しましては、Ｎ値が５０以上の、非常に締まった地盤を掘削しているものです。そのため、比較的良好なところを、今、掘り進めている状況です。","voiceIndex":50,"id":"exchange-013"},{"speaker":"つる副委員長","kind":"確認","question":"念のための確認で、１０ページの番号２の辞退をされたほうの共同企業体ですが、ちょっと不勉強で分からなかったのですが、これ、大豊建設株式会社の代表取締役社長は、これは合っていますか。間違っているのでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-014"},{"speaker":"つる副委員長","kind":"確認","question":"合っているのか、間違いないですか。私も事前に資料を、こういう企業の役員とかを確認すればよかったのですが、大豊建設は、中央区にある大豊建設株式会社ですよね。これ、普通に考えたら、先ほどの審議にあった大井保育園のほうで、番号２の法月建設株式会社の代表取締役社長と同姓同名なのかと思ったのですが、これは分かりますでしょうか。","respondent":"東野経理課長","answer":"申し訳ございません。今、ネットで調べましたところ、記載が間違ってあります。大豊建設株式会社は、森下様が代表取締役ですので、資料を訂正させていただきたいと思います。","voiceIndex":56,"id":"exchange-015"},{"speaker":"つる副委員長","kind":"確認","question":"ほかは恐らく誤記はないかなと、株式会社淺川組も東京支店とあって、代表取締役が長谷川さんとお名前があったりしますが、今回これは辞退をされた側の共同企業体の記載であるかとは思うのですが、委員会前に私も気づいてお伝えできればよかったのですが、ちょっといろいろ今、審議の中で見せていただく中で、ふと思いましたので、一応また改めて、ほかのところにそういう記載の間違い等がないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-016"},{"speaker":"吉田委員","kind":"確認","question":"１１ページに工程表があります。それで、最終的には令和８年度のところで、ここに「※次年度以降発注予定」となっているのですけれども、工程表がここまでということは、工事の終了の見込みというか、予定は、この辺までというふうに思っていいのでしょうか。地域の方たちから見ると、この工事はいつまで続くのか、みたいなご意見を伺って、私がその場ではすぐお答えできなかったので、確認させてください。","respondent":"栗原河川下水道課長","answer":"今回、北品川特殊人孔等整備を行う子供の森公園隣接地での工事は、本工事をもって終了いたしますので、こちらの工事は令和６年度まで。全体は令和８年度までですけれども、今回の子供の森公園隣接地での下水道工事に関しましては、今のところは令和６年度末までを予定しています。","voiceIndex":59,"id":"exchange-017"},{"speaker":"吉田委員","kind":"意見","question":"はい、分かりました。お伝えするときには、工事ですので、あくまで予定ということで、また何かあると延びる可能性もあると思いますけれども、めどを聞かれたので。分かりました、ありがとうあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-018"},{"speaker":"大倉委員","kind":"質問","question":"本来であったら、こういう形がいいとか、一般であれば、相見積りをいろいろなところからとって業者を選ぶとかということもあると思いますし、区のほうでも、２者以上からとらなければいけないということも決まっていたかと思うのですが、その辺に関して教えてください。","respondent":"東野経理課長","answer":"ですが、実際には、札入れの際に１者が辞退したということになりますので、入札自体は成り立っている状況ではありますが、１者ということになりますと、やはり競争性というところでは少し疑問があるかなというふうに感じられるのは否めないと考えています。","voiceIndex":62,"id":"exchange-019"},{"speaker":"大倉委員","kind":"提案","question":"望ましくないというご答弁だったので。そういったやり方とか契約の方法とかというのは、何か、今後、すみません、私は、今、何か提案とかできるようなものは全然持ち合わせがないのですが、そういうことについて教えていただければと思います。","respondent":"東野経理課長","answer":"１者で入札が成り立つのかという部分につきましては、過去にも議論があったところです。品川区だけではなく、他区の状況によりますと、１者の入札は認めていないというような区もあるということを聞いてあります。","voiceIndex":64,"id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問","question":"ごめんなさい、私、こういうのはあまり好きではないのですけれども、さっきの、２のところの株式会社淺川組東京支店の代表取締役も、この長谷川智和さんというお名前も、株式会社長谷川工務店の代表取締役のお名前ではないでしょうか。恐らく。","respondent":"東野経理課長","answer":"大変申し訳ございません。今ご指摘があったように、こちらは誤記になっておりますので、訂正させていただきたいと思います。今後このようなことがないように、きちんとチェック体制をとりたいと思います。申し訳ございません。","voiceIndex":67,"id":"exchange-021"},{"speaker":"つる副委員長","kind":"意見","question":"３ページにはきちんと企業名と代表者名が間違いなく記載されていたりとか、あろうかと思います。ですので、ぜひ後学のために、しっかりとそこは改めて、これまでしっかりされて、たまたま今回ということかというふうには思いますけれども、引き続きぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建設委員会でも報告事項として、この特殊人孔等整備についてという報告があるということで、その資料を見ていたときに、これはりんかい線と交差するのですか。りんかい線と第二戸越幹線との間はどれくらい開いているのか、その位置関係だけ教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-023"}]},{"id":"topic-03","title":"第１１４議案、第二戸越幹線整備工事（下流部シールド）請負契約の変更","agenda":"第１１４議案、第二戸越幹線整備工事（下流部シールド）請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回、契約金額が約１０％増えるわけですが、インフレスライド条項は人件費と資材でしょうが、やはり掘削とか、その他補助地盤改良工、こちらのほうが相当費用がかかってきたのかなというふうに思うのです。今回どういうわけでこういうふうに大きく変更されたのか、何があったのか、教えてください。金額的にも、ここの割合が一番高額だとか、増えた理由ですとか、その辺も教えてください。","respondent":"栗原河川下水道課長","answer":"今回、金額が増えた大きな要因ですけれども、まず１つが、管きょ工のうち、掘削泥土受入施設の変更があります。","voiceIndex":88,"id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"先ほどのご説明で、環境アセスメントが必要な工事について、いろいろな、本来何か処理をしなければいけないものが出てきたら、何かそういう関係のアセスメントの結果がよく出ているのですけれども、そういう感じですか。先ほどのご説明でそういうふうに受け止めたのですけれども、それで間違いないか、確認させてください。","respondent":"栗原河川下水道課長","answer":"今回そういった基準を超えたものですから、別のところに搬出して、基準値超過泥土のほうがリサイクルに手間がかかりますので、その分の費用が発生したものです。","voiceIndex":90,"id":"exchange-025"},{"speaker":"吉田委員","kind":"意見","question":"大体私の理解で合っていたのだなと思ったのですけれども、１つだけ分からなかったのが、基準値を超えたというのは、何の基準値が何の基準を超えたのか、どういう物質が何の基準を超えたからというのを、もう１回説明していただけますか。","respondent":"栗原河川下水道課長","answer":"東京都の環境局、それから環境省の指定検査機関で検証していただいた結果、自然に存在する鉱物であり、そういったものが含まれていたということでございまして、数字が少し高いです。","voiceIndex":92,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"リニアのほうはならないで、これがなるというところが、なぜ違うのかということが分からないのです。しかも、これで約３億４,０００万円も新たな処理をするためにかかるということになる理由が、もうちょっと、ここは特殊なのかどうなのか、そこら辺のところを教えてください。","respondent":"栗原河川下水道課長","answer":"リニアのほうは、その土を現場のほうで何かしらの手を加えて、そういったところに出しているかもしれないのですけれども、その辺は我々は把握はしておりませんが、我々の工事では泥土として、産業廃棄物として出しているということで。","voiceIndex":95,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"添加剤を入れて泥土にして送り出すという仕組みになっていますよね。それで、その添加剤を入れても産業廃棄物にはならないというのが、産業廃棄物にならない添加剤を入れる、使うという、そういうリニアの説明なのです。そうではなくて、もともとの土壌が、先ほど言われた鉛とかヒ素とかセレンとかが含まれているということでそうなるのか、そこら辺のところを教えていただきたい。","respondent":"鈴木（真）委員長、栗原河川下水道課長","answer":"リニアは別の話になりますので、この総務委員会の所管の中での話をお答えいただけますか。セレンとかヒ素とか鉛とか、そういったものが含まれていようが、含まれてなかろうが、泥土として再資源化施設に送っています。今回は、その泥土の再資源化施設が変わったことで設計変更させていただいているということになります。","voiceIndex":97,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"空調設備の空調方式の個別空調方式というのは、全館一体型の空調ではなくて、それぞれのお部屋とか、そういうところを個別に空調する方式という理解でいいのでしょうか。間違っていたら教えてください。","respondent":"東野経理課長","answer":"こちらも聞いている範囲でお答えいたします。今、委員がおっしゃったように、個別空調、園児によって必要な部屋だったりとかという部分がありますので、個別にも空調できるようにしているということで聞いてあります。","voiceIndex":113,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい、一遍に聞けばよかったのですけれども、給湯のほうで、局所給湯方式というのも、それぞれのところで給湯されるというものなのか。例えばこういうものに対して局所の給湯になるのです、というものをご説明いただけると理解が進むと思うのですけれども、分かる範囲で教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-030"}]},{"id":"topic-04","title":"専決処分の報告について（報告第２０号）","agenda":"専決処分の報告について（報告第２０号）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第１０２号議案ですけれども、これまで情報公開で請求したときに手数料が３００円かかっていたのが、３００円がなくなるということは、これまでもずっと、共産党としても一貫して求め続けてきていますので、これは本当に大歓迎です。それで、これ（資料）を見ていくと、基本的には実費のコピー代が５０円以内で規則で定めるということでいいのでしょうか。","respondent":"大澤広報広聴課長","answer":"やはり東京都ですとか他区の状況を見ましても、白黒印刷が１０円、カラー印刷が５０円というのがほとんどの区の情勢ですので、その辺を含めて、今後決めていきたいと考えております。","voiceIndex":125,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その３００円がなくなるわけですから、実際のコピーにかかる紙代ですとか、トナー代ですとか、そういう形での実費ということで、考え方としてぜひそうしていただくように、これは要望をさせていただきたいと思います。審査請求されたときに開くという形になっていたのか。その審議会のあり方についても教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"審議会の開催ですけれども、定期的ではなくて、審査請求があったときに開催するという形になってあります。","voiceIndex":127,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、おおよそ年間何回ぐらい審議会が開催されてきたのかも伺いたいと思います。その経過と、審議会で議論した回数や、そこで出された意見がどういう意見だったのかも伺いたいと思います。","respondent":"大澤広報広聴課長","answer":"パブリックコメントに関しては、幾つかの区で実施したということは私どもも認識していますが、品川区の場合は、条例の改正に関しましては、区民の代表である議会でご審議をいただくということで、条例の改正に関するパブリックコメントはこれまでも実施していないということで。","voiceIndex":129,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、今回、個人情報保護法そのものが、かなり大きく変更されるという、個人情報をオープンデータ化していくだったりとか、そういうふうに大きく変更される法律になるわけですけれども、そういう法律そのものに対して、そこから区民の個人情報をどう保護していくかとか、そういうところでの意見というのはなくて、有料の手数料の問題ぐらいしか意見としては出されなかったのか。","respondent":"大澤広報広聴課長","answer":"審議会での意見は、もちろん料金のことだけではないのですが、委員からは、やはり個人情報を保護するために、区の考え方については審議会に必ず報告するようにという意見もございました。","voiceIndex":131,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこのところに対しては、区としての考えはどういう方向にしていくのか、その点についても伺いたいと思います。それから、第７５条で、個人情報ファイル簿の作成および公表をしなければならないということも書かれていたのですけれども、それは区としては、個人情報ファイル簿というのは、作成についてはどういった状況になるのか、その点についても伺いたいと思います。","respondent":"大澤広報広聴課長","answer":"何かのあれで受け取った場合も、それは区がどこかに提供してはいけないという規定ですので、区に関して、仮名加工情報を扱うことはほぼないというふうに認識しています。","voiceIndex":133,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も仕組みとしていまひとつ分からない部分があるのですけれども、オンライン結合の制限というので、オンライン結合に関して、これを制限する規定を置く条例を持つ自治体が９４％近くあると書いてあったのですけれども、このオンライン結合制限というのは、品川区は、これまでの条例ではどうだったのか、これからはどうなっていくのか、その点についても教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"が、具体的に５００人から１,０００人に変わっても、ファイル簿の種類が実際的に変わることはちょっと考えにくいので、ほぼ今のままのファイル簿になっていると思います。","voiceIndex":135,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"国の法に従ってオンライン結合していくということは、具体的にどういうふうになるのか、分かりやすく教えていただけたらと思います。","respondent":"大澤広報広聴課長","answer":"考え方としては、漏えい等がないように、これまでと同等に厳格な制限の下に結合していくという考え方でよろしいかと思います。","voiceIndex":137,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"それが今回、情報公開条例となるわけですよね。先ほど鈴木ひろ子委員からもありましたけれど、閲覧の手数料については、もうずっと反対をしておりましたし、今回、一般質問でもそれは取り上げましたので、このこと自体は大変賛成なのですけれども、個人情報保護法にくっついて、もう条例はつくらないということなのか、その考え方について改めて確認したいと思いますが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"個人情報保護自体が、個人情報保護法に則って運用されることになりますので、法の趣旨や目的に照らしまして、条例で定めることが必要な事項とか、条例で定めることが許容されている事項につきましては、第１０４号議案の法律施行条例の中に落とし込んでおります。","voiceIndex":139,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"それが全部施行条例になっているという認識は、生活者ネットワークとしては持っていないのですけれども、これに関して、全部この部分の条例をなくすということについてのお考えを伺ったのです。もし繰り返しになるようだったら、もうそれで、そういう考え方なのですねということなのですが、もうそういうことは一切決めていかないということなのでしょうか。","respondent":"大澤広報広聴課長","answer":"今回、条例の中で削除している個人情報の部分ですけれども、削除しているほとんどのものに関しましては、法のほうでほぼ同等の規定がありますので、法に則ってやっていくという考え方で進めてまいります。","voiceIndex":141,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"はい、分かりました。自治のことを考えれば、ほかにもいろいろありますし、品川区としては、やはり個人情報保護という視点で自治体としての条例は、生活者ネットワークとしては定めるべきだと思っています。繰り返しになりますが、この閲覧の手数料については賛成なのですけれども、やはりきちんとその辺の、個人情報保護に関する条例も定めるべきということを改めて主張させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-040"},{"speaker":"つる副委員長","kind":"質問","question":"第１０４号の法律施行条例のところなのですが、第８条の「審議会への意見聴取等」のところで、議案の記載が一番主であるかと思うのですが、委員会資料の２ページの5)の一番最後の記述のところで、「品川区個人情報保護審議会に意見を聴くことができることができる規定を設ける」と、こうあるのですが、どういう意味か教えてください。「聴くことができることができる」と。これについて教えてください。","respondent":"大澤広報広聴課長","answer":"多分、できる規定という言葉を使いたくて、こういう表記になってしまったのですが、ちょっと分かりづらくて申し訳ありません。特に深い意図はございません。","voiceIndex":145,"id":"exchange-041"},{"speaker":"つる副委員長","kind":"確認","question":"いわゆるよくある言葉でいう「できる規定」ですということの表現で、条例上の言葉は、当然すっきり「意見を聴くことができる」となっていて、委員会資料のほうでは「できることができる規定」に、ちょっと繰り返しのような感じになっている。今のご説明で確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、この個人情報保護法そのものに共産党は反対という態度ですけれども、その中で求めているのが、匿名加工情報というような形で、本当に膨大な自治体の情報を活用していくという、そういう狙いがあると思うのです。行わない理由と、２３区の状況も教えていただきたいのと、これを今後検討するとか、今後の見通しは、どう考えられているのか。どういう状況になったときに行うことを検討するのか。","respondent":"大澤広報広聴課長","answer":"考え方としては、まだ都も来年度からということで、どういうことになるのか、ちょっと私どもに見えていないところもありますし、現段階では、これを導入することによる区や区民へのメリットは、今のところ見えてはございませんので。","voiceIndex":148,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうに答弁をいただきましたので、そのことは確認をさせていただきたいと思いますし、義務づけられるような方向が出たときも、ぜひ反対の声を国に言っていただきたいと要望もさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-044"},{"speaker":"吉田委員","kind":"意見","question":"品川・生活者ネットワークとしては、反対をいたします。先ほど、鈴木ひろ子委員もおっしゃった評価すべき点は同じです。そういうことについて、きちんと条例で定めておくべきということなので、法に則ってやったとしても、それに則った自治としての条例はあってしかるべきだと思います。全体で言うと、第１０２号議案には反対せざるを得ないというふうに考えて、反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。これは、本当であれば第１０４号議案のほうが先にくると分かりやすいと思ったのですけれども、第１０４号議案が個人情報の保護に関する法律施行条例ということで、第１０４号議案のところでまた改めてこの条例の反対理由は述べたいと思いますけれども、これに基づいてこの審議会がつくられて、その審議会の報酬が規定されているというものですので、第１０３号議案に対しては反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-046"},{"speaker":"吉田委員","kind":"意見","question":"品川・生活者ネットワークとしては、この審議会がつくられてしまうというか、そういうことについて、そこの手続きの問題として、審議会に関わる人たちの報酬が決まることについては、賛成せざるを得ないというか、賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"反対です。そもそもプライバシーを守る権利は憲法が保障する基本的人権として守られなければならないわけですけれども、それを大きく変えてしまう法律ということですので、その法律の施行条例という形で全国一斉にそういうことで縛りをかけるという中身の条例を国が求めてつくるというものですので、条例に対しては反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-048"},{"speaker":"吉田委員","kind":"意見","question":"先ほど、第１０２号議案のときも申しましたけれども、基本的には、個人情報保護に関しても、法律の施行条例という形ではなく、品川区として、これについては国の法律の範囲内で自治としてやっていくというものを定めるべきというのが私たちの主張ですので、この法律施行条例という形には反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":174,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。これも個人情報の保護に関する法律施行条例に基づいてこの審議会が設置されるものですので、法律そのものを反対し、またそれの施行条例に反対していますので、この審議会条例にも反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-050"},{"speaker":"吉田委員","kind":"意見","question":"品川・生活者ネットワークとしても、個人情報保護の第１０２号議案と、それから施行条例としての第１０４号議案に反対をしておりますので、その下の個人情報保護審議会条例にも反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":183,"id":"exchange-051"}]},{"id":"topic-05","title":"第１０６号議案、職員の退職手当に関する条例の一部を改正する条例","agenda":"第１０６号議案、職員の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"品川区では、フルタイムの会計年度任用職員はいないということなのですけれども、２３区の中には、そういう働き方がある区もあるのでしょうか。フルタイムのほうが、退職金とかも出たりということで、フルタイムを希望すれば、そういう働き方があってもいいのかなと思うのですけれども、そういう希望をする方はいないのか、その辺のところを教えてください。","respondent":"崎村人事課長","answer":"なぜ区でフルタイムがいないのかというところですけれども、この令和２年４月の会計年度任用職員への移行の前が、従前の非常勤職員制度を踏襲した形で実施をしたところですけれども、その際もフルタイムの非常勤職員はおらず、それを踏襲して。","voiceIndex":192,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"職場によって、ほぼ会計年度任用職員の方でされているという職場があると思うのです。そういうところで、２区がやっているということであれば、フルタイムの会計年度任用職員というのがあって、希望すれば希望に応えるという働き方があってもいいのかなと思うのですけれども、そこのところの区の考え方はいかがでしょうか。","respondent":"崎村人事課長","answer":"この会計年度任用職員制度については、本人の希望によって、フルタイムかパートタイムかを選べるかというよりも、区として、その職の設置の必要性に応じて、会計年度任用職員を配置するかどうかということを決めるところになりますので、今の委員のお話ですと。","voiceIndex":194,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多様な働き方がいろいろなところでされていると思うのですけれども、そういうところで会計年度任用職員の方にかなり頼っている部分が、区の中でも３分の１ぐらいが会計年度任用職員という、体制的にもそういうことがあると思うのです。この労働条件としては、決していい労働条件とは言えないような状況があると思うのです。賃金の定期昇給はないですし、退職金もないわけですから。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-054"},{"speaker":"吉田委員","kind":"意見","question":"品川・生活者ネットワークも、会計年度任用職員があまり広がるということについては、いかがなものかと考えておりますが、今回の条例については、処遇としていい方向にいくと考えますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":202,"id":"exchange-055"}]},{"id":"topic-06","title":"令和４年１２月４日執行、品川区長・品川区議会議員補欠選挙結果","agenda":"令和４年１２月４日執行、品川区長・品川区議会議員補欠選挙結果","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"いつも品川・生活者ネットワークは、選挙のご報告の後、障害者の方たちからのご要望とか、そういうことをお伝えしてきたのですけれども、今回は、いいほうのご報告になるかなと思います。やはりそういう方たちの要望が１つずつ実現していくことが、投票率アップにもつながるかと思っています。本当によかったと思います。それで、１つ、私の苦手な分野の質問をしなければいけなくて、これもお問合せがあって。","respondent":"鈴木選挙管理委員会事務局長","answer":"それと、警察との関係ですが、選挙管理委員会は、公職選挙法による規制の内容についてはご説明をしたり、注意をしたりしますが、実際に何か案件があった場合の適法かどうかの判断や、その取締りは警察というふうに役割が分かれているものです。","voiceIndex":210,"id":"exchange-056"},{"speaker":"吉田委員","kind":"確認","question":"その確認と、それから、選挙期間中は、今回で言うと、１１月２７日が告示日なので、１２月４日が投票日だから、３日まではよいということで、３日のどういう、インターネット広告とかだと時間で止めたりもできるではないですか。その告示日というのは、今回で言えば、１１月２７日の午前０時で区切れるものなのでしょうか。まだないから、その辺は曖昧なのか。その辺を教えていただけますか。","respondent":"鈴木選挙管理委員会事務局長","answer":"これは現実的に、やはり１２時をもってぴったり全部解除して表示を消せるかどうかというところを考慮したのだと思われますが、規定上は、当日に関しては更新はできませんということでご注意いただくよう申し上げているところです。","voiceIndex":212,"id":"exchange-057"},{"speaker":"吉田委員","kind":"確認","question":"届け出たと、時間で判断はできなくなってしまうというか、あくまで届出をするまでは、選挙期間前、届出をしてから選挙期間としての規制を受けるという判断なのですか。決して得意な分野ではないのですけれども、これからはやらないと無理ではないのかみたいなこともあるので、そのためにはルールがきちんとしていないと混乱状態なので、すみません、確認させてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただし、実際に選挙運動を行っていいのは、立候補届出をした後ですので、具体的には、立候補予定者の方が届出に来まして、選挙長のほうで正式に受理した時間を届出書に記入しますので、その時間以降は、その候補者の選挙運動をしていい期間が始まるという考え方です。","voiceIndex":214,"id":"exchange-058"},{"speaker":"吉田委員","kind":"確認","question":"なるほど。では、運動するほうとしては、届出書受理の書類を見て。あくまでやはりその時間ということですか。インターネット広告とかで言えば。大枠で言えば、その判断でいいでしょうか。それがまず確認で、その時間というのは、例えば、始めるときについては、正式に受理された時間で判断しなさいということなのでしょうか。最後に、間違いのないように。","respondent":"鈴木選挙管理委員会事務局長","answer":"ですので、インターネットに関しましては、ほかのポスターをポスター掲示場に張ったり、街頭の演説などもそうなのですが、届出をした時間以降でないと選挙運動ができないということですので、インターネットで選挙運動をすぐ始めたい場合には。","voiceIndex":216,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"剥がすことをご存じないのかしらと思うぐらい、その候補者のポスターが張ったままということが毎回見られるのですけれども、そのポスターは、告示日に剥がさなくてはいけないということを指導していただく場面はどこかであるのでしょうか。ぜひ指導していただきたいと思っているのですが、その点、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"そのポスターに関しては、何度か機会があるごとに説明、注意をしておりますが、まず最初は、やはり立候補予定者説明会のときに、選挙運動の説明の中で、事前に張ったポスターに関しては告示日のうちにすぐ撤去をということでお願いをして、説明しております。","voiceIndex":218,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうポスターは、剥がし漏れという感じではないくらいの、かなり張られているなというものが毎回見られることがあるので、今でもそういう形で指導されているということなので、改めて強調していただいて。そういうことがずっと続くと不公平にもなっていきますし、ぜひこれからも強力に言っていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":220,"id":"exchange-061"},{"speaker":"湯澤委員","kind":"質問・要望","question":"再選挙について、全国でも本当に稀な、７例目となる首長選挙の再選挙が行われたと認識しております。例えば上位３名とか、決選投票とか、そういったような形でやっていけば、もちろん４人以上いなければ法定得票数は必ずとれるわけであって、そういったことは区としてはどのようにお考えになっていて、どういった行動を、もしとられていることがあれば教えていただきたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"品川区選挙管理委員会といたしましては、１つは、ご指摘のように、公職選挙法の規定に基づいて執行せざるを得ませんので、直接区のほうで何か対応できることはないのですが、特別区の選挙管理委員会の委員長会、局長会などでは、情報を共有したり、それから。","voiceIndex":221,"id":"exchange-062"},{"speaker":"湯澤委員","kind":"質問","question":"よろしくお願いしたいと思います。それが変わったというところで、長く住んでいる方は分かっているというようなことがあったのですけれども、やはり新しい方、あまり地域を分かっていらっしゃらない方は、その地図を見て、こう行けばいいのかなどというふうになると思うのですけれども、ちょっと記載が違ったところがあったので、どういったタイミングでやっているのか、お聞きしたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"入場整理券にも同じ地図を使ったりしているのですが、基本的には、その都度、更新はかけているのですが、区の施設については、当然、情報は把握しているのですが、民間の事業所に関しては、報告を必ずいただけるものではないので、今回、申し訳ありませんでしたが。","voiceIndex":223,"id":"exchange-063"},{"speaker":"湯澤委員","kind":"意見","question":"期間も短かったというところで、なかなか大変だったと思うのですけれども、ランドマーク的に記載をされている大きな施設などに関しては、今後も注意をしながら記載をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-064"},{"speaker":"大倉委員","kind":"質問","question":"投票率についてなのですが、今回、戦後７例目、東京都でも初めての再選挙ということで、各種メディア等でも報道されたり、私から見ても、品川区がということで注目されたのかなとは思っておりましたが、実際に蓋を開けてみると、前回が３５％ちょっとで、今回は３２％ちょっとということで、３ポイントぐらい下がっているというところで、選挙管理委員会として。","respondent":"鈴木選挙管理委員会事務局長","answer":"ですので、委員ご指摘のように、取りあえず再選挙があるかないかではなくて、重要な首長を選ぶ選挙ということで、２回目だからと言わずに、棄権しないで多くの方に行っていただきたいというのが選挙管理委員会としての考えで、そういう意味では、啓発のときにも。","voiceIndex":226,"id":"exchange-065"},{"speaker":"大倉委員","kind":"質問","question":"確かに過去を見ても、大体同じ傾向があるというのは認識しているところです。それは周知がうまくいって３２％、３０％を切らないところで止まったのか。それとも、ある程度、皆さんに意識を持ってもらって３２％で止まったのかとか、分析としてはかなり難しいなとも思っているので、その辺の、周知に向けて何か工夫があれば教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、それだけで投票率の低下幅が抑えられたかどうかというのは、ちょっと分析はできないということと、それから、先ほど申し上げた３０％を切るのではという懸念も、あくまで今までの傾向を見て、一番悪いとそれぐらいもあり得るということで。","voiceIndex":228,"id":"exchange-066"},{"speaker":"大倉委員","kind":"質問","question":"分析については分かりました。例えば、広報紙の流用などではなく、単純に選挙管理委員会として、現在、品川区長選挙が行われていますのでみたいなものはされているのかどうか。ほかの先ほどのお話でいうと、そういうことをされた候補者もいるということで伺っていて、そのときに効果があったような話もちらっと伺ったのですが、そういうものも併せて、そういったところについて教えていただければと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"現時点では、インターネットで誰でも世界中でどこでも見られるものよりは、区民の方向けのＳＮＳ、ＬＩＮＥであったり、Ｔｗｉｔｔｅｒであったりというほうが、確実に区民の方に届くという意味では適しているかというふうに考えているところです。","voiceIndex":230,"id":"exchange-067"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。私の認識だと、例えばＦａｃｅｂｏｏｋ等のＳＮＳの有料広告でも、ＹｏｕＴｕｂｅ等の有料広告でも、ある程度、地域を限定して発信ができるような認識を持っています。ここは確かに分からないところもあるのですが、地域をある程度、品川区内などというふうに絞れるようであれば、そういったことも含めて考えていただければなと思いました。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、区で独自にＦａｃｅｂｏｏｋやＹｏｕＴｕｂｅチャンネルを持っていて使っているということがありますので、その辺をどう組み合わせるかとか、どちらのほうが効果的かということは、ちょっと検討してみたいと思います。","voiceIndex":232,"id":"exchange-068"},{"speaker":"大倉委員","kind":"意見","question":"私も分からないところがあったので、いろいろ工夫して調べていただければ。人によっては、ＹｏｕＴｕｂｅで出てくると、有料広告は邪魔だからという意見もあるので、そういうこともいろいろご考慮いただいて、できるだけいろいろな方の目に触れるようにしていただければなと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":234,"id":"exchange-069"},{"speaker":"つる副委員長","kind":"確認","question":"先ほど、いわゆる政治活動用ポスターというか、どちらがいわゆるか分からないけれども、ポスターの質疑がありました。１つよく問合せがあるのが、告示前のたすきなのです。常に確認はいろいろなところでされていると思うのですけれども、まず、告示前の政治活動における名前が入ったたすきについて、いわゆる選挙告示後に使う同様のたすき、これについては法律上どうなっているのか、改めて教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、実際にこの間もそういうお問合せをいただいたときには、その当該の団体には、そういう指摘があって、違法と判断される恐れもあるので、できるだけほかの方法にするなり、注意をしてくださいという注意喚起までは選挙管理委員会でもできますので、そこまでは対応して。","voiceIndex":236,"id":"exchange-070"},{"speaker":"つる副委員長","kind":"確認","question":"これは非常に大事な質疑かなと思って伺っていたところであるのですけれども、やはりそうしたところは、区議会議員選挙と、過日行われた区長選挙、そういうところにあっては、品川区の選挙管理委員会として、区民の方からそういう問合せがあったときには、厳正な、迅速な対処、対応を引き続き、ここはお願いしたいと思いますし、グレーやオフホワイトのようなところについては、これは法律解釈の部分で。","respondent":"鈴木選挙管理委員会事務局長","answer":"基本的には、ご指摘のように、例えば立候補の表明をされたり、政党の公認をとられたりというものは、もう明らかですが、それ以外に、今までの実例で言いますと、例えば何か活動をしていた当日では分からなくても、その後、選挙に立候補するというような実績があった場合には。","voiceIndex":238,"id":"exchange-071"},{"speaker":"つる副委員長","kind":"意見","question":"特に私の部分では、たすきについて質疑させていただいたわけでありますけれども、よく地域の方からも、やり得ではないかと言われるのです。各級選挙で毎回。やはり先ほど、鈴木ひろ子委員に指摘していただきましたルールに基づいてやっていくということがすごく大事かと思いますので、引き続き、こういったことについての強化も、この区議会議員補欠選挙の報告事項に関連して、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":240,"id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2252#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":52164,"voices":249}},{"id":"r04-20221223-6","meetingId":"r04-cm12","date":"2022年12月23日","dateIso":"2022-12-23","committee":"区民委員会","time":"午前１０時００分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区立五反田産業文化施設指定管理者候補者の公募","agenda":"品川区立五反田産業文化施設指定管理者候補者の公募","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"この施設を造って、人を呼んでこられるかという客観的な根拠、何か調査をしたのかという私の質問に対して、こういうご答弁をいただいたのですけれども、検討委託という形でさせていただきましてと、いろいろな資料をもらったというようなご答弁をされているのですが、これはもしかしたら結局。","respondent":"遠藤商業・ものづくり課長","answer":"今のＳＨＩＰの運営の、指定管理を行っていただいています品川ビジネスクラブとマグネットスタジオなのですけれども、今回はホールの運営だけになりますので、実際にブライトコアホールをやっているのはマグネットスタジオになっていますので、ちょっと分からないのですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"１者しか来ないのでみたいな話を昨日はしてしまったのですけれども、公募をすれば何者か来ると思いますという今の答弁でしたけれども、「もし」の話を今ここでしてはいけないかもしれないけれども、もしどこも応募がなかったら、そういう場合はどうするというのは前もって考えて、何か対策を、公募なのだから、対策というと変なのですけれども、でも１者も来ないとなったときにはというのは。","respondent":"遠藤商業・ものづくり課長","answer":"現状では１者も来ないということはないだろうとは思っているのですけれども、１月から募集を始めて、あまりにも来なかったという場合には、再来年の６月オープンという形になりますので、時期的なもので、もう一度指定管理の条件を変えて応募してもらうとか。","voiceIndex":9,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、委託ではなくて指定管理にしているわけだから、最後は委託があるからというのは担保としてはいいと思うのですけれども、そうではなくて、指定管理にしたというのは今までの区政の歴史があるわけですから、それについてどういうふうにしていくのかと思って、改めて質問します。","respondent":"遠藤商業・ものづくり課長","answer":"どこで引っかかっているかというところがありますので、そこについては、現在お付き合いがある会社とかがありますので、その辺の話を聞いてという形になるかなと考えていますけれども、現状では応募があるというふうに考えておりますので、ちょっと申し訳ないですが。","voiceIndex":11,"id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"この施設のことについては、以前議案でしたか、審議されて、結構催事が多い感じ、ただ単に使いたいという人にフロアを貸すというだけではなくて、フロアを貸すというのはそうなのですけれども、いろんな商業的な催事が結構利用の用途としてあるかなというのが、そのときに議論があったと思うのですけれども、そういう意味での企画とか、イベント、催事を打っていくノウハウみたいなものも。","respondent":"遠藤商業・ものづくり課長","answer":"できるだけ稼働率を上げて、お客さんをいっぱい呼び込んでもらうというのが、私どもが一番重点に考えているところですので、そういう部分での審査をするような形になるかなとは思っております。","voiceIndex":14,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"特に営業というか、いろんなツールというのか、営業ということもあまりやったことがないからあれだけれども、人脈とかいろんなものをたくさん持っている、あるいは事業として過去にそういう経験がいっぱいある、そういう会社というのを、会社かどうか分からないですけれども、そういう指定管理先というのがこの施設を運営する上では力になってくるような気もするのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"そういうところはどういう形で運営される考えかみたいなお話には、できる範囲でお答えするときがありますので、そういうときに、にぎわいを重視しているのだみたいな話をしていて、そのときに会社に聴いていますので。","voiceIndex":16,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。多分今まで品川区がいろんな指定管理先として指定してきたところとはまた違った、新しいノウハウを持っているところが必要になってくるのではないかなというのが思いとしてありますので、ぜひ当初の目的に沿った形を最大限実現できるように、そういう施設管理先を選定していただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"ごめんなさい、さっきの質問で、検討委託した先も品川ビジネスクラブとマグネットスタジオの共同事業体というふうに考えてもいいのかとお伺いしたのですけれども、そうなのですか。","respondent":"遠藤商業・ものづくり課長","answer":"検討委託したところの事業者ということですね。","voiceIndex":20,"id":"exchange-007"}]},{"id":"topic-02","title":"品川区立総合区民会館の再開","agenda":"品川区立総合区民会館の再開","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１点だけ確認したのですけれども、８階の大ホールはいつから再開になるのでしょうか。","respondent":"篠田文化観光課長","answer":"現在、鋭意工事を進めておりまして、年が明けた来年の１０月１日から再開を予定しています。","voiceIndex":31,"id":"exchange-008"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"私からは、左側の新型コロナウイルス感染症や物価高騰に対する支援のところについて質問します。基金も積み増して、九百数十億円になっている。昨日も申しましたが、直接支援の業種を広げる、あるいは金額を増やす、こういうことが必要になってきて、そのためにやはり区独自の財源による直接支援を進める姿勢をいよいよ持つべきだというふうに改めて思ったのですが、この点はいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"直接支援とかのお話もありまして、ほかの支援策も様々用意させていただいているところですので、今後もいろいろな形で支援策はやっていくつもりではもちろんありますし、方法、手段とか、当然予算も限られておりますので、その中で企業にとって一番有効に。","voiceIndex":37,"id":"exchange-009"},{"speaker":"おくの委員","kind":"質問・要望","question":"国や都からの補助がある範囲だけではなくて、区独自の財源を使ってでも支援していかなければいけないという姿勢で、区独自の財源による直接支援は何とか拡大していかなければいけない、金額を増やす、業種を広げるという形で増やしていかなければいけないという姿勢を持つべきときだと私は思います。その点をしっかり考えてやっていっていただきたいという意見を述べまして、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"例えば、ほかの自治体とかを見ると、事業主、経営者がもう一回専門学校でも大学でもいいのですけれども、自分の能力を高めるときの支援というのがあったりするのですけれども、そういったところは品川区としてはどのようにお考えでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"経営者を対象とした支援ですけれども、経営者を対象としたセミナーというのを年に何回かやらせていただいているところがございまして、その中でお話を聞いた方から、次はこういうのをやってほしいということであれば。","voiceIndex":41,"id":"exchange-011"},{"speaker":"松本委員","kind":"意見","question":"それに加えて、今おっしゃっていただいたところになるのですけれども、１回のセミナーとかだと、どうしてもそれだけで終わってしまうというところもあって、継続的に学び直せるような形というのも、引き続きご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"産学官連携についてお伺いしますけれども、主な連携機関の2)なのですけれども、２つの大学ではないですか。だけれども、品川区内にはほかにも大学がありますよね。そこにはお話を持っていったのか、なぜほかの大学は入っていないのか教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"もちろんほかの大学もあろうかと思いますので、連携できる部分については、今回協定を結ばせていただいているところを中心に書かせていただいたのですけれども、それぞれのところで連携などができるかと考えていますので。","voiceIndex":45,"id":"exchange-013"},{"speaker":"藤原委員","kind":"提案","question":"その臓器を今こんにゃくで作って手術の勉強というのですか、大学医学部の手術の授業のときに、こんにゃくを使ったらと提案をしているところがあって、いずれこんにゃくが主体になりますよみたいな、正確に言うと、なりたいと思っていますというのをやっていて、大崎とかＳＨＩＰとかに行くと、よく３Ｄプリンターとかを紹介してくれるではないですか。あったような記憶があるのですよ。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、今おっしゃったとおり、かなり大きな病院がありますので、そういうことで連携することで、お互い相乗効果が出る場面もあろうかと思いますので、いろいろと検討させていただければと思っています。","voiceIndex":47,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"今初めて分かって、連携コーディネーターがいらっしゃるのですね。どこにいらっしゃる、課にいるとか、そういう方を別に雇用しているとか、まず、そのコーディネーターがどこにいるのかということ、だったら、繰り返しになるけれども、せっかく昭和大学医学部、看護学科も、昭和大学があるわけですから、どんどん持っていって、連携していくというのは大事だと私は思うのです。","respondent":"遠藤商業・ものづくり課長","answer":"間に区が入るということでうまくいくところもありますので、そういう部分では今、徐々に広げているところですので、今後もこの形で進めていければというふうに思っているところです。","voiceIndex":49,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"何回も申し訳ないのですけれども、ということは、コーディネーターの雇用関係は１年ごとですよね。その方はどういう経歴なのか、教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"その方は東京都の検査機関などで働いていらっしゃった方で、そのときにもう既に大学とのいろいろな連携などをされていたということで、知見がある方ということで、うちのほうで長年やっていただいているところです。","voiceIndex":51,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"初めに、経営変化対策資金２０２２、９４９件というのは今年度の数字ですか。それとも、今までずっとやってきたことの累積になりますか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは、２０２２年度の新しいメニューが増えてまいりますので、今年度という形になります。","voiceIndex":55,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、コロナ３年目ということで、９４９件という、借換専用資金なんかよりも大きな件数が出て、金額的にも大きいのですけれども、現状これまで、その前は２０２０でしたか、最初に経営変化対策資金ということでやられて、それ以来、いろいろ貸しつけで、中小企業も大分借り入れが大きくなっているというか、借り入れる限度みたいなもの、経営の上限のところに。","respondent":"遠藤商業・ものづくり課長","answer":"去年よりも一、二件増えたかなぐらいのレベルでしか増えていないところもありますので、効果は出ているのかなということで、また引き続き資金として区としてはもっている状態なのかなというふうに考えています。","voiceIndex":57,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。今年度は４月から借り入れ、この資金の事業が始まっていると思うので、この１年間、１１月までということですから、半年ちょっとですか、大体傾向としてはどうですか。毎月同じぐらいの形でずっと融資先があっ旋されているのか、少しなだらかに下がってきているのか、その辺はいかがですか。","respondent":"遠藤商業・ものづくり課長","answer":"昨年度とあまり変わりはないというのが正直なところです。","voiceIndex":59,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。今の状況を聞かせていただいて、来年度予算の編成というところになってくると思うのですけれども、やはり融資というのがこれだけ利用されている、必要とされているということがありますよね。そういう意味では、来年度以降についても、この事業についても中小企業を支える事業として検討というか、そういうことはしっかり考えていっていただきたいと思います。いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"融資については、そもそもかなりのメニューを用意してあって、それにプラスアルファして経営変化対策資金などをやってきたですので、来年度につきましても、何らかのメニューをご用意させていただいて、区内の資金繰りを支援できればと思っているところです。","voiceIndex":61,"id":"exchange-020"},{"speaker":"塚本委員","kind":"確認","question":"今ちょっとぱっと調べた中で、２０１９年に初めて、もうちょっと前からあったのか、そこはきちんと確認できていないのですけれども、いずれにしても、最初にこの事業で就職されてから数年が経っている方もいらっしゃるという中で、その方のその後の状況みたいなことはフォローされているのですか、今の活躍の状況とか。","respondent":"遠藤商業・ものづくり課長","answer":"今年９月にまたモンゴルで面接会みたいなものをやるのに、今日本でこんなふうに働いているのだという紹介をしてもらうような形で、その方も一緒にモンゴルに行っていただいたりというようなこともしております。","voiceIndex":63,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうなってきたときに、受け入れた中小企業側とすれば、もしそのまま戻られるということになると大きな穴があいてしまうみたいなところになると思いますけれども、そこのところで関係が切れてしまうのではなくて、その後も継続して、就職された方のコメントなんかでも、日本とモンゴルのかけ橋になりたいということもおっしゃっておられるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2948#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":18423,"voices":70}},{"id":"r04-20221223-7","meetingId":"r04-cm12","date":"2022年12月23日","dateIso":"2022-12-23","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区立出石つばさの家指定管理者候補者の公募","agenda":"品川区立出石つばさの家指定管理者候補者の公募","exchanges":[{"speaker":"石田委員","kind":"確認","question":"１点確認なのですけれども、この公募は、区外の法人等にも広くするという形でよろしいのか、お願いします。","respondent":"川崎障害者施策推進課長","answer":"広く公募を呼びかける予定です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながき委員","kind":"質問","question":"選定委員を設置とあるのですが、これはどういった方が委員になられるのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"委員の構成ですが、委員長は企画部長または総務部長等になります。委員としては有識者委員、学識経験者、弁護士等になりますが、２名以上となります。それから選定予備委員会の委員長。このような構成になっています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"いながき委員","kind":"質問","question":"企画部長は何となく分かるのですけれども、学識経験者と、ごめんなさい、誰でしたか。という方たちを、行政で選ぶという感じなのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"障害者の特性、知識に精通した方に入っていただくことで、専門性も高まると考えられます。何よりも、安定して施設を運営していくということが事業者の選定として重要と考えておりますので、有識者等に入っていただくということで公平性、客観性も保たれると考えております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"いながき委員","kind":"質問","question":"学識経験者とかの中には、グループホームを使っていらっしゃる方とか、当事者の方たちというのは入るのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"当事者の方は入らないのですけれども、実際に施設利用を希望される方に対して、こちらのグループホームは主に知的障害者の方がご利用になりますので、団体の方には適宜、情報の提供、共有はしています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"いながき委員","kind":"質問","question":"情報を提供ということで、この審議会に入るということではないという理解でいいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"質問","question":"所管をまたいでしまうかもしれないのですけれども、指定管理者制度について大幅な見直しが昨年あって、基本的に、公募を経ないで指定管理ができる期限が限られたという記憶があるのですけれども、障害者施設について、指定管理者を今回、もしかしたら後で障害児者総合支援施設のこともやりますけれども、そういう制度を活用して公募にかけるというのは初めてという認識でよろしいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"品川区の指定管理者制度活用に係る基本方針改定が令和３年３月３１日ですが、それが改定されてからは初めてということになります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"あくつ副委員長","kind":"確認","question":"確認ですけれども、そうすると、今回を含めて３期まで、最長で１５年間、今までは福祉というものの性質上、応募をしなくても、そのまま契約をしてきた指定管理者というものが、今回のことに関しては、途中で変更等があるかもしれませんけれども、最長で１５年間ということになるということで、その後も公募で、プロポーザルで選ばれれば、当然継続になるということでよろしいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","voiceIndex":19,"id":"exchange-007"}]},{"id":"topic-02","title":"介護保険事業計画改定に伴う日常生活圏域ニーズ調査","agenda":"介護保険事業計画改定に伴う日常生活圏域ニーズ調査","exchanges":[{"speaker":"石田委員","kind":"質問","question":"ニーズ調査ですけれども、令和５年２月下旬から発送とあるのですが、下旬というのはどのぐらいなのですか。なので、この下旬というのが最後になってくると、２週間ぐらいしかないということになってしまうので、それがいつなのかというのと、結果は計画の中に掲載するというご説明があったのですけれども、これは議会の中で報告等はなされないのでしょうかというのを伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今後のスケジュールのところで、アンケート調査票発送、回答が２月下旬から３月６日までというところで、確かに２月は２８日までしかないので、この辺りは、一般的なアンケート調査を送って回答するまでの二、三週間を見込んでというところで。","voiceIndex":26,"id":"exchange-008"},{"speaker":"いながき委員","kind":"質問","question":"実施目的なのですが、拝読はしたのですけれども、具体的にこれが何を目的として、これによって何が導き出されて、それがどういった政策につながっていくのかというものが、ごめんなさい、私には分かりかねたので、具体的なものを教えていただいてもよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"調査については推奨レベルではあるのですけれども、区としましては、もともとあるいろいろな対応、在宅介護支援センター等からの意見を常に把握しているというところはあるものの、ニーズ調査をすることによって、より幅広く区民の方のニーズを把握して。","voiceIndex":29,"id":"exchange-009"},{"speaker":"いながき委員","kind":"質問","question":"この調査に基づいて、より細やかな介護であるとか、そういった事業が充実していく方向という理解でいいのかなと思ったので、ありがとうあります。そうなると、ちなみに５,５００人という数字はどういった形で、数字の根拠とか、あと、こういったアンケートは大体どれぐらい返ってくるものなのでしょうか、お尋ねします。","respondent":"菅野高齢者福祉課長","answer":"７５歳以上はどうするのかということになるのですけれども、７５歳以上につきましては、高齢者地域支援課実施の介護予防把握事業というのがございまして、こちらは７５歳以上の介護認定を受けていない方を対象に実施している別のアンケートがありますので。","voiceIndex":31,"id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"調査概要のところの（２）アンケート項目案で、国より調査項目が示されているが、実施までに区の実情より意見集約すべき項目を加えた上で精査検討するとあるのですけれども、拝見させていただいて、物すごく品川ナイズされているという感じがして、品川区で独自に作ったものではないかと思うぐらい品川ナイズされているのですけれども、この結果は。","respondent":"菅野高齢者福祉課長","answer":"問９の耳の聞こえについてというところなのですが、問８が認知症に係る相談窓口の把握についてというところになっておりますので、認知症と耳の聞こえについての連動性といった部分についてとか、あとは補聴器の利用についてというところの実施について、今後。","voiceIndex":34,"id":"exchange-011"},{"speaker":"あくつ副委員長","kind":"確認","question":"一番最初にこういう書き分けの説明をしていただいた上で、すみません、質問させていただいたのですけれども、昨日の請願・陳情審査の中でも、耳の聞こえ方についてというところで、ここで質疑があったのですが、今、こういうニーズ調査をやられるということと、今までのご答弁の中では、周知・啓発を一段と進めた上で、補聴器の購入助成に進んでいくといったご答弁だったと思うのですけれども。","respondent":"川原高齢者地域支援課長","answer":"昨日の厚生委員会で、あくつ副委員長にもご質問をいただきましたが、改めてご説明申し上げますと、補聴器に関する正しい理解の普及啓発を、医療機関や業界団体と連携して進めていくことが、まずは第一に重要と考えておりまして、その上で。","voiceIndex":36,"id":"exchange-012"},{"speaker":"あくつ副委員長","kind":"確認","question":"昨日も確認させていただきましたけれども、第２回定例会でご答弁いただいたとおりということで、それが今現在のところの認識と、今それが一歩踏み出したということで、それが今回のアンケートに反映されているということで確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは返信用封筒に入れて投函ということなのですけれども、ネットで回答できるような仕組みは、今回は取らなかったのでしょうか。取らなかったのはなぜでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今回、ＩＣＴの設問を加えしていますが、６５歳以上７５歳未満というところで、７０歳以上につきましては、少しまだデジタル化が、デジタルデバイドと言うのは失礼なのですけれども、書いていただいて送り返していただくほうが確実に回収できるのではないかという視点から。","voiceIndex":40,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"６５歳以上の方は、かなりスマホやネットをやっている方もいらっしゃるので、そういうところから、国勢調査のネットのほうの比率は僕は分からないのですけれども、逆に言うと、そういったことを調べるチャンスだったのではないかと思っているので、今回は今言ってもしようがないのかもしれないので、ぜひ次回、こういう機会があったら、ＩＣＴのことを調べる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"},{"speaker":"せお委員","kind":"確認","question":"すみません、１点確認なのですけれども、対象者に障害者手帳を持っている方とかも入っているのか、そこだけ分かれば教えてください。","respondent":"菅野高齢者福祉課長","answer":"今回の対象につきましては、このニーズ調査において国が示しておりますのは、要介護認定を受けていない方ということになっておりますので、要介護認定を受けていない方で障害者手帳をお持ちの方がもしいらっしゃいましたら、その方は該当する可能性があると認識しております。","voiceIndex":44,"id":"exchange-016"},{"speaker":"せお委員","kind":"確認","question":"ランダムにという感じですね。これも確認になってしまうのですけれども、この調査では、いわゆる６５歳の壁というところ、私もそこはずっと気になっているので、そういったところは、この調査では分からないというか、そこの実態とかは、内容を見ていても分からないだろうなと思うのですけれども、そういったところはまた別として考えてよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今回、国全体の介護保険事業計画における改定を前提とした調査ということで、調査項目がかなり限定されているところもありますので、委員ご指摘のような部分については、この調査においては少し難しいのかなというところがありますが、例えば、区のほうで在宅サービス利用者へは。","voiceIndex":46,"id":"exchange-017"},{"speaker":"いながき委員","kind":"質問・要望","question":"先ほどあくつ副委員長からもお話があったのですが、補聴器に関してなのですけれども、昨日も要望が区民の方から出ていて、医療現場との連携も本当に大事だと思うのですが、特段、何かつまずきがありますかとお尋ねしたら、とても円滑に進んでいるということだったので、検討はもちろん大事なのですけれども、一歩踏み込んで、ご要望に応えられる方向で、ぜひとも進んでいただけたらという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-018"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田委員","kind":"質問","question":"今、品川区立障害児者総合支援施設、ぐるっぽについてご説明いただきまして、今年の１０月に運営法人が、多くの利用者から変えないでほしいという様々な声が出ていた中で、指定管理者が変更されるという事態になってしまったという状況ですけれども、運営法人変更後、予定していた職員数等は確保できたのでしょうかというのを、まず伺いたいと思います。","respondent":"松山障害者支援課長","answer":"総合支援施設運営に当たっての人員ですけれども、現在、正規職員、非常勤職員を含めて、１１５人の方を確保して運営しております。","voiceIndex":54,"id":"exchange-019"},{"speaker":"石田委員","kind":"質問","question":"変更前が何人で、それで今、１１５人というのが分かれば伺いたいのと、２の事業内容についてのところで、（４）の移動支援事業が新規ということで、移動支援はご説明いただいたように本当にニーズが高いですけれども、移動支援サービスの事業の提供実績はこの法人にあるのでしょうか。それで、どういう人数体制でやっていくのかというのをお聞かせください。","respondent":"松山障害者支援課長","answer":"１点目ですけれども、変更前の職員数ですが、ほぼ同等です。必ず変更前の人員を埋めるようにということで決めておりますので、特に変更があったものではないということです。","voiceIndex":56,"id":"exchange-020"},{"speaker":"石田委員","kind":"質問","question":"それで、移動支援のところですけれども、ということは、２人がもう利用されているということになったのですかね。それで、どれぐらい受け入れられる体制があるのかというのは分かるのでしょうか。ぐるっぽの変更した指定管理者が、ぐるっぽとして入るのは初めてということなのか、事業所連絡会というのが今まではどうだったのか、いつ頃開催されるのかを伺いたいのですが。","respondent":"松山障害者支援課長","answer":"移動支援事業でどれぐらい受け入れられるのかというご質問ですけれども、確かに移動支援のニーズは高いのですが、その方の使いたい曜日あるいは時間等もありますので、どれぐらい受け入れられるかということについては、お答えは今のところできません。","voiceIndex":58,"id":"exchange-021"},{"speaker":"石田委員","kind":"質問","question":"保育所等訪問支援ですけれども、先ほど今後の取組のところで、利用が少ないから、園長会や校長会で周知していくということだったのですけれども、今現在、少ないというのはどれぐらいなのか、実績が分かれば伺いたいのと、親御さんがこの制度を知らないということが、利用が広がらないということなのではないかと思うので、園長会や校長会で周知した後に。","respondent":"松山障害者支援課長","answer":"保育所等訪問支援についてのご質問にお答えします。登録の人数ですが、今、お二人が登録されているということです。","voiceIndex":60,"id":"exchange-022"},{"speaker":"石田委員","kind":"質問・要望","question":"それと、今後の取組についての２番の（１）、「地下１階に浴室を設置し」ということで、精神障害者が外出するきっかけづくりを行うということなのですけれども、これはたいむの利用者からの要望というか、声だったということなのですが、そもそもたいむのような機能がもう１個欲しいというのが、精神障害者の皆さん、ご家族の皆さんのすごく強い要望だと思うのですけれども、機能そのもの。","respondent":"松山障害者支援課長","answer":"たいむのような機能をもう１か所できないかというご質問です。総合支援施設については、既に面積的にも建物的にも決まっておりますので、その中で精神障害者の方をできるだけ多く受け入れるということで、指定管理者と区とも話してまいりました。","voiceIndex":62,"id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、精神障害者の方のお風呂というのは、そんなに強い要望ではない。要望は要望であるのですけれども、お風呂は入れるのではないかと。たしか、かもめ会やパルレの親の会とか年輪の会の方から連名で、前区長にクリニックについて要望が出ていると思うのです。なので、新規クリニックの誘致についても検討されているのか、ぜひ考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"お風呂に注目が集まるかもしれませんが、ユニットバスを一つ設置するということで、それで例えば生活リズムだったり、お風呂があるから行かなければという形で、精神障害者の方は精神の状態によっては、お一人で入るということに対して非常に不安があるということですので。","voiceIndex":64,"id":"exchange-024"},{"speaker":"石田委員","kind":"質問・要望","question":"そうすると、クリニックとしては新たな形で、ぐるっぽに限らずですけれども、精神の方のクリニックというところでは、要望も強いと思いますし、それまでにも要望は出ていると思いますので、そこはぜひ検討すべきではないかと思いますし、ぐるっぽだけで考えると、確かに場所は限られていると思うのですけれども、障害児者支援についてということで所管事務調査なので、そういったところでは。","respondent":"松山障害者支援課長","answer":"医療のものについては、そこまで誘致についてはお答えが難しいというところですけれども、私どもでできることとしましては、精神障害者の方の生活上の支援というところが主ですので、まずは精神障害者の方が安定して通える場所がある、相談ができるというところ。","voiceIndex":66,"id":"exchange-025"},{"speaker":"石田委員","kind":"質問・要望","question":"たいむのような機能が広がっているというところでは、よかったなとは思います。それで、そもそもの数が足りないということが大きな問題だと思いますので、障害福祉計画のところでも、児童発達支援センターにしても、精神障害者の分野にしても、目標を掲げられていますので、そこに向けて、ぜひ実現させていくということで、様々検討していただきたいと思いますし、さらに広げていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問・要望","question":"各論のサービスはだいぶ多いので、総論的なことを伺います。これは別に福祉に限らないですが、課題がある。共に考えましょう、あるいは、何でも要望に応えられるわけではないけれども、駄目なときもコミュニケーション力で理解いただく。その辺をまず一つ教えてください。その辺の考え方をこの際、限られた施設ですから、数字を追うとかではなくて、うまくできないものかなというところで伺います。","respondent":"松山障害者支援課長","answer":"１点は、区の方針です。区の方針といたしましては、まずはこの施設の設置目的を達成するというところが大きいのですけれども、児童発達支援センターの機能拡充と地域生活支援拠点の拡充という２点が非常に大きいです。それは、障害のあるお子さんから大人までの生活を支えるです。","voiceIndex":70,"id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問・要望","question":"前半の部分ですが、方針をいろいろ伺って、このことがうまく利用者に伝わってほしいと思いました。それと、利用者もそうですし、現場で従事されている方々。区がその辺を強調していくことで、例えば時間の使い方があるではないですか。すみません、最後は感想です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"いながき委員","kind":"質問","question":"事業内容についてお尋ねしたいのですが、２の事業内容の4)の保育所等訪問支援なのですが、保護者の方からの依頼に基づきとあるのですけれども、これは保育所ではなくて、保護者の方個人からの依頼に基づいてということでいいのでしょうか。それをお尋ねします。","respondent":"松山障害者支援課長","answer":"保育所等訪問についてのお尋ねです。こちらは、児童福祉法に基づいて、制度として決まっておりまして、保護者からの依頼に基づくものです。","voiceIndex":74,"id":"exchange-029"},{"speaker":"いながき委員","kind":"質問","question":"累計とかは取っていないというか、２人から８人が、令和元年は２人、令和２年は何人という感じですか。","respondent":"松山障害者支援課長","answer":"各月で実績を取っておりまして、月ごとの実績になります。登録が一番多いのが８人だったです。各月変動がありまして、それぞれ異なっております。","voiceIndex":80,"id":"exchange-030"},{"speaker":"いながき委員","kind":"質問","question":"保護者からの希望があって初めて行くものなので、月によって、もちろん違ってくる。継続的に登録されている方はお二人いらっしゃるという理解で大丈夫でしょうか。","respondent":"松山障害者支援課長","answer":"今現在は、お二人です。その月時点でのカウントになります。","voiceIndex":82,"id":"exchange-031"},{"speaker":"いながき委員","kind":"質問","question":"今のお話だと、最大では３泊ぐらいまでの方はいらっしゃるということでした。次に、４の今後の取組についてお尋ねします。１の（３）の地域のインクルージョン推進で、保育所等訪問支援や巡回相談の充実というのが新規ということなのですが、要は、先ほどお尋ねした事業内容についての（１）の4)の保育所等訪問支援とは別ということでよろしいのですか。","respondent":"松山障害者支援課長","answer":"今後の取組の中での、保育所等訪問支援や巡回相談の充実ということで、既にやっているものに対して、拡大もしていくというのを今後の取組に入れしています。","voiceIndex":86,"id":"exchange-032"},{"speaker":"いながき委員","kind":"質問","question":"一応、別物ということで考えていいと。違いますか。4)は保護者からの依頼に基づきとあって、（３）のほうは保育所等訪問支援とあったので、こちらは保育所からなのかなと思ったのですけれども、そうではなくて、保育所等訪問支援とイコールということでよろしかったでしょうか。","respondent":"松山障害者支援課長","answer":"４の今後の取組の中にある保育所等訪問支援と、事業内容の中にある保育所等訪問支援は、同一のものです。","voiceIndex":88,"id":"exchange-033"},{"speaker":"いながき委員","kind":"質問","question":"地下の配置が随分変わるようなのですが、お風呂が作られて、子ども発達相談室ができると伺ったかと思うのですけれども、令和元年７月２９日の資料の地下１階の配置図を拝見していて、どこにお風呂ができて、どこにお子さんたちの相談室ができるのかというのを、できれば図面とかがあればよかったかなと思うのですが、どこがお風呂になってというのを教えていただけますでしょうか。","respondent":"松山障害者支援課長","answer":"これまで地下１階にシャワーがあったところに、ユニットバスが１つ入るというところなので、全く配置は変わるものではありません。相談室につきましても、クリニックの相談室がありますので、クリニックの相談室をそのまま子ども発達相談で活用するというものです。","voiceIndex":90,"id":"exchange-034"},{"speaker":"いながき委員","kind":"質問・要望","question":"品川区民は約４０万人いるのですけれども、五反田に１つしかないので、ぜひともそういったものをつくってほしいという要望があったので、どの辺にあるのかなとか、どこが空いているのかなというのを知りたかったというところで、すみません、少し外れた質問をしてしまったということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-035"},{"speaker":"せお委員","kind":"質問・要望","question":"そういったところが、割合とかが分かれば教えていただきたいというのと、今後の取組の、地域のインクルージョン推進の中核としての機能のところで、保育所等訪問支援はやっていらっしゃるのは分かるのですけれども、巡回相談というのは区のほうで、所管が違いますが、やっていると思うのですけれども、そういったところの関わりというのはどういったところなのか教えてください。","respondent":"松山障害者支援課長","answer":"実際に指定管理者変更前は、ご利用者の方が、どの職員が残るのか、自分の担当する職員が残るのかというご不安のお声をかなり区のほうでも聞きましたけれども、４月以降、今の指定管理者と前の指定管理者が協力して、一緒にぐるっぽの中で丁寧に引継ぎを行っておりましたので。","voiceIndex":96,"id":"exchange-036"},{"speaker":"せお委員","kind":"質問・要望","question":"巡回相談は区や保育所等から出向くということで、保護者からすると、見てほしいところが違っていたりもするので、巡回相談、特に施設のほうの、保育所等の運営がうまくいくようにというところが主なところであったりするので、ぜひ福祉のほうで連携していただいて、少し認識が違っていたりするところもあるので、ぜひそこは連携していただきたいと思います。すみません、あと１点だけ。","respondent":"松山障害者支援課長","answer":"そういった面的な連携も含めまして、指定管理者のほうで予定はしているです。ただし、コロナの感染拡大の影響などを見ながら、実施状況については考えたいということを聞いております。","voiceIndex":98,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、幾つかお尋ねします。４の今後の取組についての（３）、ほかの委員の方もお話がいろいろ出ていましたが、保育所等訪問支援が非常に少ないわけです。それが一つ。それから、巡回相談を充実するということは、なかなかここの施設として、できていないということなのですが、その２つの事業がなかなかうまくいっていないのは、どういう点が課題なのでしょうか。","respondent":"松山障害者支援課長","answer":"私どもは、実はこの実績の少なさから、今回、区独自でお知らせを作りまして、保育所等訪問支援の仕組みというのをご理解いただかないと、その制度にはなかなか乗っていかないというところがありますので、正しい理解をしていただくよう、きちんとチラシを作り。","voiceIndex":102,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"意見","question":"２つ目は、先ほども話に出た保育課の巡回相談です。そこで、このお子さんはいろいろな配慮が必要だとか、こういうことだというので、結局そちらは、保育士たちに指導されている仕組みです。その情報をこちらの施設等も共有して、先ほどの保育所等訪問支援を巡回相談とかにつなげていくことは可能だと思うのです。保育課の巡回相談との情報共有体制と、それぞれのお子さんに対する支援についてです。","respondent":"松山障害者支援課長","answer":"保育課の巡回相談につきましては、園全体のことも考えているかと思いますので、その辺の視点の違いはありますけれども、今後とも、保護者の同意が取れれば、連携していくことは可能と考えております。","voiceIndex":104,"id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こちらの所管のお考えはそういうことだとご説明いただいたので、保育課のほうはどういう考えかというのは別の機会にお尋ねして、協力できるような仕組みづくりをどうすればできるかというのも、またお尋ねしていきたいと思います。","respondent":"松山障害者支援課長","answer":"区内のお子さんも、障害のあるお子さんだけではなくて、障害のことをご心配されている保護者の方、あるいは発達が気になるお子さんについても相談をお受けしているのが品川児童学園ですので、品川児童学園の協力を求めまして。","voiceIndex":106,"id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、詳細に、教育委員会等と協力しながら進めていくと。ぜひ小学校へのつなぎという意味で、こちらの施設の持つ意味は非常に大きく、役割は重要だと思うので、ぜひお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-041"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"これは４年前からそうだったのですけれども、ぜひそのように、先ほどピンチをチャンスにというお話もありましたが、変化をチャンスにというお話もありましたが、そのようにしていっていただきたいということが、まず一つなので、そこの認識を伺いたいところが一つです。それを、これから発展をしていっていただきたいという要望も含めて、どのようにお考えになっているのかということが２つ目。","respondent":"松山障害者支援課長","answer":"そこに丁寧に対応するという姿勢を持っていると認識しておりますので、そのいいところをより発展させていくよう、区としても支援していきたいと考えています。それから、３点目ですけれども、相談のところに実際の職員がいるかというご質問です。","voiceIndex":110,"id":"exchange-042"},{"speaker":"あくつ副委員長","kind":"確認","question":"１点だけ再質問というか、最後のところですけれども、これから相談員を増やしていくような取組みたいなものについて、品川区は指定管理者を支援しているのかどうかを確認させてください。","respondent":"松山障害者支援課長","answer":"現場で一緒に働く方なので、最終的には社会福祉法人のほうで決定するというのが一番よいかと思いますが、区としてもバックアップできる情報等をお伝えして、そちらで募集はできないだろうかという情報はお伝えしています。","voiceIndex":112,"id":"exchange-043"}]},{"id":"topic-04","title":"を改めて聴取いたします。 初めに、(3)新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","agenda":"を改めて聴取いたします。 初めに、(3)新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","exchanges":[{"speaker":"石田委員","kind":"質問","question":"支給状況のところで、令和３年と令和４年の支給件数が倍以上になっているのですけれども、ここを区としてはどう見られているのでしょうか。周知が広がったとか、コロナがさらに広がっているということもあるので、そうしたことだと思うのですけれども、区としての見解を伺えたらと思います。","respondent":"池田国保医療年金課長","answer":"これについては、パートタイマー的な方のご申請が多くなったということ、それから、実際に９月以降に罹患された方につきましては、コロナの療養期間が１０日から７日間ということで短くなりましたので、その関係で、支給金額も減少していると考えているところです。","voiceIndex":119,"id":"exchange-044"},{"speaker":"石田委員","kind":"質問・要望","question":"口コミでというのもありましたけれども、引き続き、区としての周知、こうした対応がありますというのは、広げていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-045"},{"speaker":"いながき委員","kind":"質問","question":"対象者のところが被用者とあるのですけれども、これというのは、雇われて働いている方かなと思うのですが、経営者の方たちの支援みたいなものというのはあるのですか。これは当たらないということで、まずはいいのかなと思うのですけれども、経営者の方もすごく大変だろうなと思うのですが、それはないのですか。","respondent":"池田国保医療年金課長","answer":"こちらの傷病手当金の支給の対象ですけれども、給与収入ということで、給与収入を得ている方が給与を得られなくなった場合に、傷病手当金の対象になるということになってございまして、実際に事業主の方でも、給与ということでお支払いを受けている場合には。","voiceIndex":123,"id":"exchange-046"},{"speaker":"あくつ副委員長","kind":"質問","question":"今のところに関連して、変な話ですけれども、給与を得ている方は社会保険のほうの傷病手当があって、国保のほうの傷病手当が受けられるという方については、ご相談があって、個人事業主は受けられないということだったのですけれども、逆に受けられる方というのは、今おっしゃった個人事業主だけれども給与を受けている方、そのほかにはどういう方がいらっしゃるのですか。","respondent":"池田国保医療年金課長","answer":"そのほか、パートタイマーの方とか、それから、実際にあまりないとは思いますけれども、会社にお勤めになっていて、健康保険制度に加入されていない会社とかの場合には、給料が止められた場合にはこちらの傷病手当金の対象になってまいります。","voiceIndex":125,"id":"exchange-047"}]},{"id":"topic-05","title":"コロナ禍における区民の健康に関する調査の実施","agenda":"コロナ禍における区民の健康に関する調査の実施","exchanges":[{"speaker":"石田委員","kind":"質問","question":"国立国際医療研究センターと筑波大学と大阪大学と連携してということで、コロナでの後遺症等々、まだ広く解明されていないというところはあると思うので、そういう研究をされるのだという思いですけれども、２番の実施内容の（２）のところに、共同研究契約書を締結とありますので、どういう経緯でこういう研究契約をされたのかをお聞きしたいのと、国立国際医療研究センターや筑波大学、大阪大学は。","respondent":"坂野保健予防課長","answer":"きっかけなのですけれども、区のほうに研究班からコンタクトがありまして、ぜひ協力してもらえないかというのが発端でございまして、類似のスキームでやっているほかの自治体なのですけれども、大阪府八尾市が同じスキームでやっております。","voiceIndex":132,"id":"exchange-048"},{"speaker":"石田委員","kind":"質問","question":"研究班からコンタクトがあったというのは、何か今まで深い関わりがあって、品川区にお願いしてみようとなったということなのでしょうか。","respondent":"坂野保健予防課長","answer":"幾つかの自治体に打診をして、断られたところもあるし、品川区は検討しましょうということで、それでお話が進んでいるという経緯です。","voiceIndex":134,"id":"exchange-049"},{"speaker":"石田委員","kind":"意見","question":"細かい話になるのですけれども、コンタクトがあって、それで検討されて、契約されたということなのですけれども、いつ頃そういうコンタクトがあったのかというのと、調査対象は第７波で感染した方、それと非感染者の方、約３万人ということなのですけれども、後遺症が１年たってもなかなか消えない、いろいろな症状があると思うのですが、その後遺症なのか。","respondent":"坂野保健予防課長","answer":"完全に収まった後に、あなたは３年前のこの頃、どうでしたかと聞いて、恐らくまともな回答は得られないと思います。やっているさなかにも増えたり減ったりがあるので、どこかでこれは切らないと、研究自体が成り立たないのかなと思います。","voiceIndex":136,"id":"exchange-050"},{"speaker":"石田委員","kind":"質問","question":"分かりました。それで、しかも負担は全部、研究センターと筑波大、大阪大が負担するということで、各自治体にコンタクトして、やっていただけるという状況なら、こちらで出すという感じで進めてきたということですね。デジタルギフトというのはどういうものになるのですか。イメージがつかないのですけれども。","respondent":"坂野保健予防課長","answer":"デジタルギフトなのですけれども、いわゆる電子マネーの価値というか、それを差し上げるということで、具体的に言いますと、スマートフォンでコード決済に充当できる、バリューというのですけれども、これを５００円分です。","voiceIndex":138,"id":"exchange-051"},{"speaker":"いながき委員","kind":"質問","question":"コンタクトがあったのは、国立国際医療研究センターの研究班の方からということでいいのでしょうか。それをお尋ねします。","respondent":"坂野保健予防課長","answer":"ファーストコンタクトがあったのは、国際医療研究センターの方です。","voiceIndex":143,"id":"exchange-052"},{"speaker":"いながき委員","kind":"質問","question":"そうすると、大阪大学とか筑波大学の方というのは、研究センターの方から一緒にというお話があったのでしょうか。","respondent":"坂野保健予防課長","answer":"これは、厚生労働科学研究でもともと研究班があって、その研究班の中で、国際医療研究センターの方がフィールドを探すような役割でやっていたという感じです。","voiceIndex":145,"id":"exchange-053"},{"speaker":"いながき委員","kind":"質問","question":"すみません、少し分かりづらかったのですけれども、国立国際医療研究センターの方が研究班を持っていて、その研究班の方たちが、大阪大学とか筑波大学の方と一緒にこれまでやられていたのでということですか。ごめんなさい、つながりがよく分からなかったというだけなのですけれども。","respondent":"坂野保健予防課長","answer":"疫学デザインというのはなかなか難しくて、議会のところで簡単にご説明するのはなかなか難しいところではあるのですけれども、要するに、国からテーマが与えられて、そのテーマをやってくださいというオーダーで動いているということです。","voiceIndex":147,"id":"exchange-054"},{"speaker":"いながき委員","kind":"質問","question":"なので、品川区でやることなので、昭和大学の方とかは入らないのかなと思って、別のところの方たちが入っていたので、それがどうして入っていたのかなという、ごめんなさい、単純な質問なのですけれども。","respondent":"坂野保健予防課長","answer":"いろいろな理由があるのかなと思うのですけれども、３万人のコホートということで、かなり大規模なデータ解析が必要です。","voiceIndex":149,"id":"exchange-055"},{"speaker":"いながき委員","kind":"質問・要望","question":"この２つの大学はそういった能力があるので、多分、国からのオーダーが来たときに、一緒に国立国際医療研究センターの方とこれまでもやっていたからということなのかなと理解しましたが、それでいいのかの確認と、一つはお願いなのですけれども、対象者が２０歳から６９歳なのですが、お子さんとか若い方たちも罹患されて、後遺症ですごく苦しんでいるという話があります。","respondent":"坂野保健予防課長","answer":"ただ、それは品川区ではないということで、恐らく、これから徐々にそういった結果が出てくるのかなと思います。","voiceIndex":151,"id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"確認","question":"それと、ボランティアとして手を挙げるということなのですけれども、先ほどからあるとおり、後遺症のことに関して等、非常に区民の関心が高いけれども、今まで保健所とすると、広域行政ということで、東京都で様々やっておられるというご答弁を何回か伺ったことがありますが、ここについては、この結果を令和５年５月末に品川区としていただいた場合には、品川区保健所として、品川区の保健行政。","respondent":"坂野保健予防課長、舩木生活衛生課長","answer":"それは品川区に限らず、ほかの全ての自治体も当然、雑誌を買えば見えるわけですから、そういうことで活用されている。品川区を含むいろいろなところで活用されるかと思います。繰り返しになりますけれども、これは業者に委託とか、そういうことを一切することなく、区の内部でしっかり個人情報の部分は業務を全て行いまして、きちんと個人情報を担保した上で、この調査を進めているところですので。","voiceIndex":154,"id":"exchange-057"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"提供するときには、そういった内容がしっかりと確認をされた上で提供されているというご答弁だったのですが、くれぐれも流出等がないようにということをお願いしたいのが一つと、後段の先ほどの保健予防課長のご答弁の中で、論文として提供はされる、それはどこの自治体も手に入れることができるということでしたけれども、ボランティアで国に対して参加をするという意義は当然あると思うのですが。","respondent":"坂野保健予防課長","answer":"ただ、せっかくこれだけの大規模な調査ですから、これだけ大きいコホートでの調査というのは、なかなか実はできないのです。これだけの規模の調査ですので、どのように活かせるかは具体的にはまだ分からないのですけれども、ぜひ活用していきたいと考えています。","voiceIndex":157,"id":"exchange-058"},{"speaker":"いながき委員","kind":"質問・要望","question":"そうなると、何％ぐらいの返信があれば、データとしていいのかとか、何％のお返事が返ってくるのを求めているのかとか、変な話、５％しかなかったらどうなのかとか、６０％以上あればいいとか、希望の数字と目安というのを教えていただいていいですか。","respondent":"坂野保健予防課長","answer":"回収率が下がると誤差がだんだん大きくなってくる。統計学で言うところの信頼区間というのですけれども、それがだんだん広がっていってしまう。だから、何％あればいいとかということではないけれども、高ければ高いほどいいというのが答えかなと思います。","voiceIndex":160,"id":"exchange-059"},{"speaker":"いながき委員","kind":"質問","question":"確かにおっしゃるとおり、高ければ高いほど、すごくいいものになると思うのです。なので、何％を目指しているとか、これぐらいないとデータとしては難しいという、少なくとも何％返ってくることを、品川区としてはというか、この研究としては希望しているという数字というか、基準を教えていただいていいですか。","respondent":"坂野保健予防課長","answer":"一応、サンプリング前の数字ではあるのですけれども、感染者で７,５００人、だから３万人だとすると、２５％です。ただ、転出とかがあるので、実際には３万人より多少少なくなってしまうのです。だから、もう少し高いほうがいいということだと思います。","voiceIndex":162,"id":"exchange-060"}]},{"id":"topic-06","title":"品川区における新型コロナウイルス感染症対策","agenda":"品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"ご説明いただいた最初の（１）の棒グラフですが、じわじわと増えてきているということでしたけれども、一番直近の内訳が分かれば、教えていただきたいです。感染者数は東京都で先日２万人になって、昨日は１万８,０００人ぐらいでしたが、本当に多くなってきている状況で、保健師の皆さんの逼迫度合いと言ったら失礼かもしれないのですけれども、残業等々が増えている状況なのかというのをお聞かせください。","respondent":"坂野保健予防課長","answer":"資料のグラフの内訳ということで、色で塗り分けているのがあって、６５歳以上が灰色の部分で、黄色の斜線みたいな部分が、入院を要すると医師が判断したと。９月２６日以降、４類型しか発生届が上がりませんので、内訳というと、ここの色を見てくださいというところかなと。","voiceIndex":169,"id":"exchange-061"},{"speaker":"石田委員","kind":"質問・要望","question":"まだほかの部署から応援が来るという状況にはなっていなくて、でも少し忙しくなってきたということでいいのかという確認と、昨日等々もこの委員会で、介護サービス事業所と障害者サービス事業所には物価高騰等の支援金が出るようになったのですけれども、医療機関はすごく大変な状況ですという声が届いていまして、先日の決算特別委員会でも、私はこうした医療機関への経済的支援を求めて。","respondent":"坂野保健予防課長","answer":"医療機関への支援ということなのですが、今日の報告内容にはない部分かと思うのですけれども、医療機関とは結構頻繁にオンライン会議とかをやって、いろいろご意見は伺っているという状況ではあります。","voiceIndex":171,"id":"exchange-062"},{"speaker":"石田委員","kind":"質問・要望","question":"医療機関と意見交換されているという中でも、経済的支援をお願いしたいという要望が来ているので、そこに対してどう応えているのか、検討はされているのでしょうかというところをお聞きしたいと思います。","respondent":"若生健康課長","answer":"医療機関への経済的支援のご要望については、区としても適宜検討しています。医療機関ですとか病院も含めて、広域的な東京都等の支援状況もありますので、そういったものを含めまして、区として何ができるかというのは今後も検討していきたいと考えています。","voiceIndex":173,"id":"exchange-063"},{"speaker":"石田委員","kind":"質問・要望","question":"本当に繰り返しているので、感染拡大が繰り返すたびに医療機関は、一般の診療が受け入れられないぐらい、でも目の前の命がということで、本当にやりきれない状況というのが生まれていますので、そういう中では、経営を支援していくというところで、それだけ逼迫していて、さらに赤字となると、命を守る機関が本当に成り立たなくなっていきますので、そこは早急に対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-064"},{"speaker":"いながき委員","kind":"質問","question":"そういったものを、品川区としてはどれぐらい確保されているのかとか、区内の病院とかでも、塩野義だけではなくて、お薬をどれぐらい確保されていて、区民の方への安心感というか、別に数字を区民に出すというわけではないのですけれども、どれぐらいお薬を確保されている、もしくは予定しているというものがあれば教えてください。","respondent":"坂野保健予防課長","answer":"だから、区で確保するというスキーム自体、ないのです。とにかく、薬の所有権は国です。国が配布をコントロールしているという状況ですので、区で確保しているのはどれぐらいかということになると、ゼロということになります。","voiceIndex":177,"id":"exchange-065"},{"speaker":"いながき委員","kind":"質問","question":"となったら、持っている国に品川区として、今これだけ逼迫しているので、ご都合いただけますかというお話とかはできるものなのですか、できないものなのですか。","respondent":"坂野保健予防課長","answer":"基本的に、薬の流通は都道府県単位なので、区でどうにかというよりも、都道府県単位でのスキームかと思われます。","voiceIndex":179,"id":"exchange-066"},{"speaker":"いながき委員","kind":"質問","question":"であるならば、東京都に対して品川区が、これぐらいのお薬をお願いしますというのはできるのですか。やる気があるかというか、そういった方向性のお話もありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-067"},{"speaker":"いながき委員","kind":"意見","question":"そうなってくると、昭和大学が、すごくよくニュースにも出るように実績があるかなと思ったので、例えば昭和大学が手を挙げてくれれば、入ってくるのかなという思いがあったので、お尋ねしました。なので、それはできますか。","respondent":"坂野保健予防課長","answer":"全て、この薬が入る医療機関というのはウェブサイトに載っていますので、治療にアクセスがということだとは思うのですけれども、昭和大学を含めて、近隣区も含めて、この辺はかなり医療機関が一生懸命やっているところですので。","voiceIndex":186,"id":"exchange-068"},{"speaker":"あくつ副委員長","kind":"確認","question":"１点だけ伺います。先ほど口頭でご報告のあったインフルエンザとの同時流行が、来るぞ来るぞと言われていて、いよいよ昨日からそれが東京都から発表されたと、ホームページを確認したら、品川区でもそういうお知らせが出ておりました。","respondent":"坂野保健予防課長","answer":"スポーツ飲料とか、そういったものを備蓄しておく。災害のときにも通じる備蓄かと思うのですけれども、レトルト食品というのも１週間分を目安にそろえておきましょうというのが、東京都から周知の紙が出ているという状況です。","voiceIndex":189,"id":"exchange-069"},{"speaker":"あくつ副委員長","kind":"質問","question":"分かりました。同時流行のリスクという部分で、発熱者がたくさん出れば、医療機関がかかりにくくなったりするのかなということ。私も素人なので分からないのですが、両方かかってしまう場合もあるのかなとか、その辺について何か教えていただけるところがあれば。","respondent":"坂野保健予防課長","answer":"ただ、今お話しされたように、医療機関とか救急医療システムにかかる負荷というのは、相当高くなってくるのが想定されておりますので、区のホームページを見ていただいたようですけれども、昨日からずっとこれをやっているという状況でございまして。","voiceIndex":191,"id":"exchange-070"},{"speaker":"あくつ副委員長","kind":"質問","question":"最後にもう１回だけ。３年前と同様に、１週間ぐらい早いということでしたけれども、３年前はどれぐらいで流行が落ち着いたのかというのが分かれば教えてください。","respondent":"坂野保健予防課長","answer":"手元の資料があって、一番すごかったのは２０１８年から２０１９年です。２０１８年の年末から２０１９年にかけてのシーズン中は物すごく出て、これが収まったのは、大体３月の頭です。２月の末から３月の頭ぐらいに収まってきているというのが手元の資料では分かります。","voiceIndex":193,"id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません、１つだけ。ワクチンの接種のところなのですけれども、私も医学的なことは全然分からないのですが、小学生よりも小さなお子さんたちの接種率について、区のほうでどのようにお考えになっていて、それに対して区として区民の方にどう啓発するのか、どういう広報をしていくのか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もともと二十数か所、クリニックで手を挙げていただいていたのですが、なかなかほかの、コロナの感染者の対応であったりとか、インフルエンザの予防接種であったりとか、いろいろなことがあって、ようやく落ち着いたというか、手が空いたというか、準備が整ったというところから。","voiceIndex":196,"id":"exchange-072"},{"speaker":"せお委員","kind":"質問","question":"立正大学の臨時接種会場についてなのですけれども、まず、東京都が準備してくださった医療従事者は、以前と同じように医師、薬剤師、看護師という理解でいいのかということと、もう２年ほど集団接種会場を設置してきているのですけれども、ここの立正大学において課題とかが見つかったかどうか、何かあれば教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それが、学生が思いのほか、大体区民の方というか、一般の方と学内関係者を１対１で我々は考えておりまして、それでもともと学校に持っていって、恐らくこれから卒業旅行であったりとか、いろいろな国内旅行であったりとか、学生が行うであろうから。","voiceIndex":200,"id":"exchange-073"},{"speaker":"せお委員","kind":"質問・要望","question":"課題のところは、私も立正大学でやるということは、若い世代の方がたくさんいらしたのかなと思っていたので、そこのところを引き続き呼びかけていただきたいと思っています。でも、すぐにマニュアルなども準備していただいて、整ってきていたと思うので、引き続きマニュアルもしっかり準備していただいて、スタッフ同士でコミュニケーションを取れるような状況をつくっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3648#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":48948,"voices":206}},{"id":"r04-20221223-8","meetingId":"r04-cm12","date":"2022年12月23日","dateIso":"2022-12-23","committee":"建設委員会","time":"午前１０時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年陳情第５９号、区営住宅の新規建設","agenda":"令和４年陳情第５９号、区営住宅の新規建設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この間の区営住宅の募集倍率、併せて、その人数も伺いたいと思います。","respondent":"竹田住宅課長","answer":"今年７月の募集倍率ですが、募集室数４室に対して、１８８人の方から応募があり、４７.０倍、今年の１月の募集倍率は、募集室数８室に対して、３０２人の方からご応募があり、３７.８倍、昨年の７月の募集倍率は、募集室数１１室に対して。","voiceIndex":11,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"３５倍、３７倍、４７倍ということで、いずれも、相当な倍率になっています。このような下で、やはり、公営住宅、区営住宅の必要性が出ていると思いますし、この間、格差や貧困が拡大している下で、公営住宅の役割というものが、より求められていると思います。その下で、先ほど、増設する考えはないというお話でしたけれども、なぜ増やさないのかを伺いたいと思います。","respondent":"竹田住宅課長","answer":"区営住宅の新設については、公的な住宅だけでなく、民間住宅も含めた住宅ストックは、量的に充足していると考えています。居住支援協議会の議論の下、民間賃貸住宅への円滑な入居を目的として、昨年１１月からは、住宅確保要配慮者入居促進事業も開始したところです。","voiceIndex":13,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"区営住宅の役割について伺いたいと思います。先ほど、目的のところでは、低所得者の方に住宅を供給するというところで、ご説明がありましたので、やはり、そのようなところで、区営住宅を増設し、実際問題として、応募倍率も３０倍、４０倍という状況で、求められているわけですから、やはり、増設をしていくということが、区の役割としても求められていると思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"第３条には、低額所得者の住宅不足を緩和するために、必要が認められるときは、供給を行わなければならないとなっておりますので、１３団地、４３９戸を供給しておりますので、法の趣旨には沿っているものと考えています。","voiceIndex":15,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"緩和するためにやらなければいけないというお話でしたけれども、そうすると、今、応募倍率が４７倍にもなっている。その下で、緩和をする必要がないということなのかを伺いたいと思います。","respondent":"竹田住宅課長","answer":"区の住宅ストックは、今、民間ストックというものが十分にある段階ですので、このようなものを有効に活用しながら、全体として、区の施策として展開するべきものと考えておりますので、さきに申し上げた結論となっているところです。","voiceIndex":17,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"全体としてということで、結論だということですが、全体としてとは、どのようなことなのか。今、区営住宅も、応募倍率が４７倍ということです。その下で、やはり、公営住宅をしっかり供給していくということが、今こそ求められていると思います。改めて、区の認識を伺いたいと思います。そのような中で、やはり、公営住宅の役割が、今こそ発揮されるべきだと思いますけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"今、委員から、高齢の方が入りにくい状況にあるというお話がございましたが、昨年から実施しました入居促進事業では、その事業を通じまして、例えば、９０代の女性の方が、この事業を使って、入居することができた、あるいは。","voiceIndex":19,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際に、私も、高齢の方から入居ができないということで相談がありまして、なかなか見つからず、結局、都営住宅に応募してたまたま当たったので入れることになりました。今、そのような公営住宅の役割が本当に重要だと思いますので、実際に民間で足りていると、ストックがあるという話ですけれども、そこには入れないという実態があるということは、区として認識されているのかを伺います。","respondent":"竹田住宅課長","answer":"一部のオーナー等におきましては、高齢者等は難しいとお考えのオーナーの方もあろうかと思います。しかし、今回、入居促進事業では、区内の７１の不動産事業者にご協力いただいて、こちらの事業を実施しています。","voiceIndex":21,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"実際に入れない実態を認識しているかというところを聞きまして、その中で、このような需要があるということでお認めになりましたので、やはり、公営住宅としても、そのような役割を発揮していくということが必要だと私は思います。区のほうでも、連帯保証人をなくして、低所得者がしっかり住居確保をできるようにしていくべきだと思いますけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"しかし、私どもが考えることは、今の入居者の方に住み続けていただくということが、一番重要と考えておりますので、一時的に収入が減った場合に、状況によりましては、個人または法人の連帯保証人の方にご協力をいただきながら、実現可能な分割案を一緒に考えていくなど。","voiceIndex":23,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"連帯保証人をなくすことと、入居されている方が住み続けていくことの関連性が、よく分からないのですけれども、そこをご説明いただきたいと思います。連帯保証人をなくすかどうかということを、区の中でも検討されたのか、どうか、されたのであれば、その内容についても伺いたいと思います。","respondent":"竹田住宅課長","answer":"先ほども申し上げたとおり、東京都とは、住宅の数が大きく違いますので、一概に比較することはできないですけれども、機械的な対応ではなくて、その方、その方の状況に合わせて、寄り添った対応をしていきたいと考える上から、連帯保証人は必要だと考えています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"都が、３か月、１５万円以上を滞納したときに訴訟するということですけれども、それは、一律にそこからやるのかどうかの確認をさせていただきたいと思います。そのような面から見て、寄り添うということであれば、そのような面でも寄り添っていくことが必要ではないかと思いますが、いかがでしょう。","respondent":"竹田住宅課長","answer":"ちなみに、品川区の区民住宅で、支払いに関しての訴訟になったケースは、２０年前の平成１４年の５月が、一番直近のものです。そのような事例が少ないということは、日頃、居住者の方に、早期から丁寧に対応している成果だと考えております。","voiceIndex":27,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"そのような対応でも、連絡を取ることはできるわけですから、そのようなやり方をしていけば、住民に寄り添った対応もできると思います。もともと低所得の方が入っているわけですから、そのような家計を圧迫することがないようにしていくということも、必要だと思いますけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"保証会社の保証料の件です。保証会社とは、契約を結んでおりまして、保証料が上がることのないように、保証会社に要請しています。今後も、区営住宅の運営に適切に努めてまいりたいと考えております。","voiceIndex":30,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"上がることのないようにということですが、むしろ、なくせば、そのような心配もありませんし、ぜひ、連帯保証人もなくしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。当時、我々自民党会派も、不動産団体の方々とお話をして、住宅確保要配慮者入居促進事業がスタートしたと思っていますので、民間の力をうまく使って、公営住宅ではなく、民間の住宅で、区民の方が住まいに安心していられるというような状況を、さらにしっかりと促進していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-012"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すで、お願いしたいと思います。現在、居住支援協議会で協議していただいて、住宅確保要配慮者への住宅確保対策が進んでいると捉えております。保証人についても、保証会社を活用するということが、主流になっているということ、公営住宅だけではなくて、民間の空き家のお部屋、空き部屋も活用することが、住宅確保の対策だと捉えております。したがいまして、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-013"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。区営住宅の応募倍率は高止まりしていますし、需要と供給が合っていません。新規建設をすべきだと思いますし、また、連帯保証人についても、寄り添うということで言えば、別の方法もありますので、なくしていくべきだと思いますので、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-014"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。先ほどの議論でもありましたように、我が会派といたしましては、新設に当たっては、民間住宅とも両立していく必要があると考えており、また、連帯保証人につきましては、対策・対応をしっかりとされていると考えておりますので、この陳情に関しましては、不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"本日結論を出すで、先ほどの説明、議論を踏まえて、不採択でお願いいたします。品川区居住支援事業を一歩ずつ進めていただくことを要望するとともに、今後も住宅確保要配慮者の対象外でありましても、お一人お一人の状況に合わせて、これまでどおりの寄り添う姿勢で、お住まいのお困り事に関するご相談に乗っていただきますようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、オープンハウス型の説明会が行われたということで、今、内容の説明が若干ありましたが、この参加人数、ほかに声、主な意見などを聞いていましたら、ご説明いただきたいと思います。このビラを配布したのは、どこまで配布されたのかも伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"この２日間に参加した人数ですけれども、ＪＲ東海からは、約１５０名と聞いております。区のほうには、先ほどのような声が届いてございましたが、ＪＲ東海のほうからは、丁寧な説明で、分かりやすかったといった意見が非常に多かったということは、聞いてあります。","voiceIndex":47,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"今回のこの陳情は、このシールドマシンが故障して止まっているということが、８月に発表されてから、その後、説明がないということで、そのための教室型説明会を実施してほしいということです。やはり、住民の皆様は、様々な不安も抱えていると思いますので、この事故についての説明をやっていくということが必要だと思いますけれども、その認識を伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今回のオープンハウス型説明会の内容においても、現在の状況、または、今どのような対応をしているかといったことも、パネルを踏まえて説明をしているというところで確認しています。","voiceIndex":49,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"一定、そのようなパネルもあって、説明をされているということですけれども、今回はオープンハウス型ということで、それぞれが自由に来場して、説明会に行くということもいいと思うのですけれども、教室型で、住民説明会をやってほしいということで、今回の陳情は求められております。いろいろなやり方でやっていくということが、よりいいと思いますけれども、そのような下でやる説明会は、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"一方で、様々な説明会の方法を取り入れるべきというところで、今回、オープンハウス型を取り入れたというところで、その部分についても、区は支援していきたいと考えています。","voiceIndex":53,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"大勢の前で発言することをちゅうちょするということは、私も気持ちは分かります。ですけれども、やはり、様々なやり方で説明会をやっていくということが必要だと私は思いますので、ぜひ、教室型説明会も、どうしても求めていただきたいと思います。やはり、しっかり安全を保っていくということが難しいから、できないということではないかと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"そのような中で、今、ＪＲ東海からは、今後、有識者委員会などを通して、安全に配慮して進めていくと聞いております。区も、今後も引き続き、安全に対して注視してまいりたいと考えています。","voiceIndex":55,"id":"exchange-020"},{"speaker":"のだて委員","kind":"確認","question":"併せて、残土の問題も、リニア新幹線はトンネルなので、あると思うのですが、この間のいろいろな説明を聞いている中で、リニア新幹線のトンネル工事で掘った残土が、産業廃棄物にならないという話を聞いています。その確認と、第二戸越幹線では、残土で出たものは産業廃棄物になるという話みたいだったのですが、どうしてそうなるのか、そこの違いを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"事業者の選定についてですけれども、こちらは、国が、ＪＲ東海に対して、その企業の企業体、または、資金面、安全面、施工能力などを踏まえて、一定程度、事業認可を下ろしていますので、そのような中で、事業を認められて、進めているです。","voiceIndex":57,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"工事の施工ミスのところは、一定程度、認められたということです。やはり、その中でも、このような施工ミスによって、故障、あるいは、外環道では陥没事故が起こってしまったということですから、そのような危険のあるトンネル工事を進めていくことは、やめるべきだと思います。ＪＲ東海のほうから、工事再開に向けて、今後、同じようなことが起きないような再発防止策が示されているのかどうかを伺います。","respondent":"中道まちづくり立体化担当課長","answer":"再発防止対策についてです。今現在、今後どのようにより安全に行っていくかというところは、まだ検討中というところで聞いています。有識者委員会などを通しまして、今後、再開するときには、また、そのようなものが出されるというところは聞いてあります。","voiceIndex":59,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"工事のところでは、今後、対策が示されるということで、少なくとも対策が示される前に、工事を再開することはないように、区としても求めていただきたいと思います。リニアでは、そのような検査を行っているのか、その基準値以上の有害物質などが出てきた場合には、産業廃棄物になるのかどうかも含めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"今回、コロナなどもありまして、ＪＲ東海自身の事業計画は、採算性も含めて、ＪＲリニア新幹線を行っていくということがなかなか難しくなっていると、私は思います。そもそも、ＪＲ東海道新幹線の収益によって、リニア新幹線を支えていこうということでしたけれども、今、コロナなどもあって、利用客が減っている中で、リニア新幹線自体の事業性というのも失われていると思いますが、その見解を伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今回、リニア中央新幹線ですけれども、大都市圏を結んで、そこの経済性の一体性を持たせるですので、そのような意味で、国およびＪＲ東海は進めていっているです。","voiceIndex":65,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"実際に、南海トラフ地震などが起こった際に、リニア新幹線の場合、安全性も指摘されております。このような様々な問題があるリニア新幹線を進めていくべきではないと思いますが、改めて、区の見解を伺います。","respondent":"中道まちづくり立体化担当課長","answer":"工事を進める、進めないということの判断は、事業者であるＪＲ東海が行うべきと考えています。区としましては、引き続き、区民に対して丁寧な説明、また安全対策をしっかり行っていただきたいと考えています。","voiceIndex":67,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＪＲ東海が決めることだということですけれども、やはり、区民の生活もかかっています。陥没事故などもありましたので、品川区の下にトンネルを掘り進めていくわけですから、区も当事者として、そのような認識を持っていただいて、対応していっていただきたい、そして、ＪＲ東海にも、中止を求めていただきたいと強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-026"},{"speaker":"芹澤委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。建設をする、しないに関しては、今、お話があったとおりで、事業者が決めるべきだと考えていますので、そこに関しては、そうであると考えています。情報提供というところは、以前からお話ししておりますが、ぜひ、効果的なものを選択していただきたいという思いであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いします。住民の方への情報提供は重要だと考えています。その意味からも、区民の皆様の不安払拭のための説明や情報提供の手法は、教室型の説明会に限ることなく、広く区民の皆様の不安払拭に寄り添っていただいて、個々の質疑について、丁寧に対応していただく手法が望ましいと考えます。よって、今陳情については、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。ほかの人の意見も聞きながら、理解を求めることもできます。リニア新幹線自体が、住宅街の真下を勝手に掘り進めて、残土などの環境破壊、また、採算性もない、事業性もないということで、問題だらけのリニア新幹線は中止にすべきですし、区民の生活が脅かされていますので、区としても求めるべきだと考えますので、採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-029"},{"speaker":"松永委員","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。説明会に関しまして、私どもの会派でも、やはり、事故が起きてしまった理由など、しっかりとパネルで説明していただいて、区民の意見を幅広く聞けるような方法が、このオープンハウス型の説明会だと考えておりますので、この陳情に関しましては、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"},{"speaker":"横山委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。今後も区民に寄り添った丁寧な説明を行っていただくよう、区として、ＪＲの対応を注視するとともに、随時、進捗状況の確認をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"６１号の１番目では、大井町から臨海斎場に行けるルートを求めています。ぜひ、臨海斎場に行くルートもつくっていただきたいと思いますが、その点についても伺いたいと思います。そうなれば、より便利になりますし、外出もしやすくなるということで、ぜひ、このようなルートについても実施をしていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そのような声をトータル的に、どう検討して、整理をして、区民の方にお示しし、理解をいただきながら、ルートを設定していくかという中で、この１１の指標で、１３地域を回りながら、丁寧にワークショップも実施しながら、進めてきたものです。","voiceIndex":85,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方のこのような様々な意見を取り入れて、より使いやすい、便利なコミュニティバスにしていくということが必要だと思いますけれども、いかがでしょうか。ぜひ、そのような面で、区のコミュニティバスとしての役割を発揮していただいて、高齢者あるいは障害者の方などの移動支援というところで、ぜひ、様々、便利なコミュニティバスにしていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"繰り返しの答弁になりますが、その中で、このような検討手法、説明会、あるいは、ワークショップを行いながら、３ルートを選定してきているという中での実施、開始です。","voiceIndex":87,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"３ルートを中心にやっていきたいということですけれども、このようないろいろな声が出ているわけですから、ぜひ、そのような意見も踏まえながら、様々なルートをつくっていっていただきたいと思います。区の総合実施計画の中では、１ルートずつ、試行運行をしていくという計画になっておりますが、ぜひ、これを前倒しにして、ルートを実施していっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的には、大井ルートの試行運行を開始して、数か月がたちますが、そのような取組の状況、アンケートの結果も踏まえながら、試行運行の大井ルートの本格実施への判断も踏まえながら、大崎ルート、荏原ルートの実施については、その時期に合わせて。","voiceIndex":89,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、大井町に行きたいという要望も強いのです。自治体がやるバスですから、そのような移動権を保障するということを位置づけて、行っていくという姿勢が求められると思いますけれども、いかがでしょうか。ですから、大崎ルートの早期実施、荏原ルートもありますので、荏原ルートのほうも、ぜひ早期に実施をしていくということが必要だと求められていると思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"やはり、大崎ルートについては、検討時期から、例えばですが、ゆうぽうとの辺りでは建て替えが進められて、ホールですとか、あるいは、産業支援の区の施設も加わったり、ＴＯＣについても、大崎ルートの経由地になっておりますが。","voiceIndex":91,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"大崎ルートの早期実施というところは、民間でもできるかもしれないということですけれども、このようなところで、区として、今、コミュニティバスのルートを示しているわけですから、ぜひ、その実施に向けて、早期に取り組んでいくということで、やはり、住民の中でも、大井ルートが実施されて、ほかのルートも実施してほしいという声も出されておりますので。","respondent":"鈴木都市計画課長","answer":"料金の点です。区内でコミュニティバスを実施している区の料金の設定については、様々でございまして、２２０円で、品川区と同額で実施している区もあります。","voiceIndex":93,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"やはり、１００円程度に引き下げれば、気軽に利用できるようにもなると思うのですけれども、区のお考えを伺いたいと思います。廃止基準のほうは、収支率５０％という設定ですけれども、やはり、他区では、このような収支率の基準は設けていないというところもありますし、設けているところでも、５０％ではない。５０％は結構高い水準だと思うのですけれども、区の認識を伺います。","respondent":"鈴木都市計画課長","answer":"試行運行の中では、この金額で実施していきたいです。収支率については、他区のお話をいただきましたが、品川区同様、判断基準を設定しているところは、数区ありますし、５０％で設定しているというところも、区としては、幾つかあります。","voiceIndex":95,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、低廉な金額にしていっていただきたいと思います。やはり、福祉面を考えたら、もちろん、区がやるわけですから、収支が合わない路線をやるわけです。なので、そのような面で、しかも、今、品川区は、そこだけしか基準になっていないわけですから、そのような点でやっていくということはやめるべきだと、廃止基準をなくしてほしいということは、強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-038"},{"speaker":"松永委員","kind":"質問","question":"私からは、何点かあります。地域公共交通会議が３３人の有識者の方々で、何度か、会合が開かれていると考えています。大井ルートについて、開始から現在まで、約７か月の利用状況について伺いたいと思います。もう一つが、先ほども質疑の中であったのですけれども、２年間の試行運行ということで、５０％に達しなければ、中止してしまうおそれがあるのかと考えてしまうのですが、どうでしょうか。","respondent":"鈴木都市計画課長","answer":"収支率の判断基準、試行運行期間は４年間、令和４年から令和７年度までの３年目の運行実績に基づきまして、本格導入か、廃止を含む見直しかの検討をしてまいりたいです。","voiceIndex":102,"id":"exchange-039"},{"speaker":"松永委員","kind":"質問・要望","question":"３年目で判断をされるです。このままの状況でいくと、３１％で、５０％にいくのか、いかないのかと不安になると思うので、私どもの会派といたしましては、ぜひ残していただきたいということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-040"},{"speaker":"芹澤委員","kind":"提案","question":"私も、地域の方から、ここに通ってほしい、料金を下げてほしいという声をたくさんいただいておりますし、議会でも、議員個人として、もしくは会派を代表して、コミュニティバス、大崎ルートも含めた、ルートの活用案の提案はしてまいりましたが、この議会の場で、建設委員会の総意として、本日結論を出していくものが、最終的には品川区議会の総意として、結論となっていくわけでありますから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-041"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すでお願いしたいと思います。３つの陳情について、態度表明は、一括でさせていただきたいと思います。区民の皆様のご要望として、ルートの拡大のことは受け止めております。今後も、地域公共交通会議等で、区民の皆様のご意見をしっかりと集約していただいて、そして、検討して、決定していただくことが、進め方としてはふさわしいと考えますので、よって、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。大崎ルートは、すぐに運行していただきたいと思いますし、臨海斎場にぐるっと回れば便利になる。低廉な価格にもすべきだと考えますので、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-043"},{"speaker":"松永委員","kind":"質問・要望","question":"不採択でお願いします。コミュニティバスにつきましては、これまでも数多くの陳情が出されており、まさに様々なご要望が地域から出されていることと思います。このたびの個々のルートも含めて、様々なルート、要望を、また一つの案として捉えることができたと、私どもは理解しております。今回の陳情も、地域の声として捉えていただき、試行運行も含めて、地域公共交通会議で検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"本日結論を出すで、試行運行ルート選定経緯と評価基準、試行運賃の説明・議論を踏まえて、不採択でお願いいたします。区内、１３地域で、各地域ごとに、多様な課題とご意見がありますが、区民の皆さんのご意見を伺いながら、地域公共交通会議、警視庁、鉄道や路線バスなどの民間事業者などとの協議や試行運行の分析を実施する中で、コミュニティバスの試行運行を進めていただきますようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-045"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。交通不便地域を解消してほしいという気持ちは分かりますが、その方法は様々あると思います。大井ルートを変更してということではなくて、別のやり方もあると思いますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。便利で使いやすいコミュニティバスにするために、住民要望に応えたものにしていくべきだと考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-047"}]},{"id":"topic-02","title":"品川区自転車活用推進計画策定に向けた検討状況","agenda":"品川区自転車活用推進計画策定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そのような面で、違いが出ている部分もあるかと思いますが、民間の場合は、実際そうなのかは、僕も分からないのですが、短時間の無料の利用があると思うのですけれども、そのような関係も影響しているのかと思ったのですが、区のお考えを伺いたいと思います。ここでは、北品川と西小山の自転車分担率が高いということですけれども、ここがどうして高いのかという区の分析がありましたら、伺いたいと思います。","respondent":"工藤交通安全担当課長、鈴木都市計画課長","answer":"買物等に来られるお客様については、民間の駐輪場を使っていただくということで、短時間の駐輪ということで、無料にしていると思うのですけれども、こちらのほうは、時間を長く止めるとなると、１００円、１５０円と。駅として離れていると、やはり、そこへ歩いていくのではなくて、自転車を使おうというところも考えられます。ここから見えてくる課題の精緻な分析については、次回２回目以降の協議会での提示を考えている予定です。","voiceIndex":137,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、ネットワークということですから、つながっていかないと、なかなか機能しないということにもなってきますので、ぜひ、そのようなネットワークをつくっていくというところで、力を尽くしていっていただきたいと思いますが、区内では、今、４３.７キロメートルが整備されているということですけれども、これは、区内の道路の何割ぐらいになるのかが分かれば伺いたいと思います。","respondent":"工藤交通安全担当課長、森道路課長","answer":"現状、駐輪場の利用率が１００％を超えている大井町駅などもありますので、使ってもらうことと併せて、放置自転車の防止ということも考えながらやっていきたいと思いますので、ここら辺は慎重に考えていきたいと考えています。委員ご指摘のように、４３.７キロメートルございまして、区内の国道、都道、区道を合わせますと、３７３キロメートルということになりますので、割合といたしましては、１１.７％という形になります。","voiceIndex":140,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、１１.７％ということで、ぜひこれを増やしていっていただきたいと思います。区内でのネットワークをつくっていくというところで、ぜひ努力をしていただきたいと思います。そのような中で、整備していくところで、今、事故数なども示されたと思います。今、区が考えていらっしゃる整備の形態、方針というのは、どのように考えていらっしゃるのか、伺いたいと思います。","respondent":"森道路課長、工藤交通安全担当課長","answer":"そのようなものを組み合わせながら、先ほどお話がありましたネットワークも意識しながら、整備を進めていきたいと考えております。駅周辺は、なかなか、駐輪場を新たに設置するための適地が確保できないということが現状です。ですが、町開発、まちづくり等の計画がある際は、積極的に駐輪場の設置について、働きかけをしていきたいと思います。","voiceIndex":143,"id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"駐輪場のところは、なかなか適地がないということですけれども、そのような中で、力を尽くしていただいて、ぜひ、駐輪場の整備と併せて、短時間利用についても、慎重に考えるということですので、そのようなところも検討していただいて、ぜひ、短期間の無料の利用ができるようにしていっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-051"},{"speaker":"横山委員","kind":"質問","question":"最初にお伺いします。資料３、「自転車活用等に関する品川区の現状について」の５ページのところです。現在、区におきまして、コロナなどの影響で、オンライン勤務など、区民の生活に様々な影響が出ているかと思います。分析の部分は、また、第２回以降というところですが、現時点において、どのような変化があると、区として捉えているのかというところをお聞かせください。","respondent":"鈴木都市計画課長","answer":"利用が戻ってきているということは実感としてあるのですが、やはり、コロナ前の当時の朝の通勤時間帯の混雑具合には、まだまだ至っていないのかというところで、資料では６５％ですが、戻りとしては、もう少し来ているのかです。","voiceIndex":148,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問","question":"自転車ネットワークの部分の続きになります。資料３の１６ページのところに、電動キックボードに関する法改正の動向ということで、参考というところがあります。このようなところに関しても、一体的に考えていくという理解でよろしいのでしょうか。ヘルメットなどの議論等もあるかと思うのですけれども、現在、区として分かっている範囲で構いませんので、教えていただけたらと考えています。","respondent":"鈴木都市計画課長","answer":"これをどのような形で位置づけて、計画の中で何かをしっかり示していくのか、あるいは、まずは方向性的なところを明示することにとどめるのかは、今後、検討の中で、しっかり示します。","voiceIndex":150,"id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"国としての動向もあるかと思いますので、国の動向を注視していただきながら、区の事業者へのヒアリングもしていただけるということで、現状を確認していただきながら、品川区内だけではなく、ほかに実証実験をされている区域もありますので、他の自治体の情報、課題、または、安全に使っていただけるように、まちにどのような影響が出てくるのか、そのようなところも、まずは。","respondent":"工藤交通安全担当課長、鈴木都市計画課長","answer":"こちらについては、基本的には、通勤・通学の方が使われている方の大多数という認識でおります。ただ、今後、世の中の変化もいろいろあろうかと思いますので、そこら辺は、適宜、追っていきたいと考えております。どのような目的で、駐輪場を利用されているかということは、先ほどもご紹介しましたけれども、全ての駐輪場ではないと思うのですが、駐輪場を利用されている方に、アンケートに答えていただくことも予定しておりますので、その中で。","voiceIndex":152,"id":"exchange-054"},{"speaker":"横山委員","kind":"質問・要望","question":"区外からの移動を含めた広域的な利用ができるということも、シェアサイクルのメリットかと考えているのですけれども、今回は区内のみの資料になっておりますが、区外から区内へのポート間の移動状況、例えば、ポート間のペアとして、利用が一番多い状況は、どこからどこまでなのかみたいな形で、区外からのアクセス状況みたいなものや単位が分かりましたら、教えていただけたらと思います。","respondent":"工藤交通安全担当課長、溝口土木管理課長","answer":"ただ、自転車を駐輪場以外に止めることは悪いことだとは認識されているということですので、そこら辺は、ご理解をいただいているところです。今後、このような自転車のことを検討していく中で、やはり、場合によって、広域連携は、一つ大きな柱になってくるところだと思いますので、必要に応じて、運営事業者から、どのような形でデータが取れるかは分かりませんけれども。","voiceIndex":155,"id":"exchange-055"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。ぜひ、広域の部分も含めて、情報を取れる部分はしっかりと取っていただきながら、全体の計画に活かしていただきたいと考えていますので、要望します。今、目黒区のほうで、西小山駅前は開発が行われているかと思いますが、目黒区側の駐輪場の整備がされるのか、どうかなど、そのような辺り、他区との連携についても、大変重要な部分かと考えていますが、現状をお聞かせください。","respondent":"工藤交通安全担当課長","answer":"目黒区とは、情報の交換等はさせていただいているのですけれども、やはり、具体的な駐輪場の整備といったところについては、あれば、情報交換をするという形で進めておりますので、現状、そちらのほうは、今のところ、把握してございません。","voiceIndex":158,"id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"最後、１５ページの図３３のところになります。自転車が混在する見通しの悪い道路での事故の危険性が増大していると考えられる」と記載があるのですけれども、これと同じ、原因ということでよろしいのか確認させてください。こちらですが、４０歳代から６５歳以上の増加の原因も、また、次回の第２回で分析されていくのかと思うのですけれども、現在お分かりになることがありましたら、教えてください。","respondent":"工藤交通安全担当課長、鈴木都市計画課長","answer":"図３５の関係です。４０代、５０代の事故に遭う数が増えているです。やはり、これは、コロナの関係で、今まで電車等を使っていた方が、密を避けるために、自転車に乗り換えた。委員ご指摘のとおり、逆に、多少広い道路は減少傾向にある中で、幅員が一番広い道路が、微増ながら増えていますというところでは、やはり、これは、法定速度は守りながらだとは思うのですが、より遠距離の通勤、移動に。","voiceIndex":160,"id":"exchange-057"},{"speaker":"横山委員","kind":"質問・要望","question":"様々な御答弁、ありがとうございました。これだけの資料を作っていただくには、大変なご苦労があったかと思います。ぜひ、区内そして区外の状況、国の動向等、民間とも様々な情報連携をしていただきながら進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-058"},{"speaker":"こんの委員","kind":"質問","question":"私からは、まず、資料３の１２ページ、図２７、自転車の利用の目的別というところです。そこで、１２ページの図２９に、私事のパーソントリップ調査の目的と出ています。ここは、先ほど、ご説明がなかったので、ここを少しご説明いただけますでしょうか。お願いします。","respondent":"鈴木都市計画課長、溝口土木管理課長","answer":"分類別の中で、代表的な移動手段が、ここで記載されているわけです。説明が難しいのですが、具体的に……。人が、１日に何を目的に動くのか、動く際に何を使うのかといったものを定期的に調査して、このような交通政策ですとか、今後の道路の形状や道路整備をどうやっていくかなどというものに使うための基礎調査として。","voiceIndex":165,"id":"exchange-059"},{"speaker":"こんの委員","kind":"意見","question":"今、交通安全担当課長の個人のご意見として、ご所見をいただきました。現状を把握した上で、計画をどうするかではなく、その課題をどうするか、解消する計画も盛り込まないと、具体的な推進計画にはならないと考えるところです。何かご所見がございましたら、お願いいたします。","respondent":"鈴木都市計画課長","answer":"計画の中では、今、交通安全担当課長から条例の改正を行っていくべきかどうかというところのお話もさせていただきましたが、まず、そこは、例えば、一店舗、一店舗が小規模で、対象でないとしても、例えば、その店舗が商店街の中にある店舗であれば、商店街全体として。","voiceIndex":170,"id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"区民の皆様の生活の足として利用していくのだという、区の方向性が以前とは大きく変わって、推進をしていくという区の姿勢になりました。そのような意味からすると、生活の足として、区民の皆さんが利用できるように、活用できるような方向性を今後考えていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-061"},{"speaker":"澤田委員","kind":"質問","question":"資料３の６ページの図１１に区全体の収容可能台数、実収容台数、放置自転車台数の推移があると思います。先ほどサービス向上を目指しているとおっしゃっていたので、そちらの取組というか、チャイルドシートをつけた自転車に対する整備というか、そのような専用スペースみたいなものを造る計画や検討はされているのか、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"チャイルドシートを装着している自転車が増えてきたというところは、認識しています。やはり、区民の皆様の声でも、そのようなチャイルドシートを止められる場所を増やしてほしいというようなお声も多数いただいております。","voiceIndex":174,"id":"exchange-062"},{"speaker":"澤田委員","kind":"質問・要望","question":"努力をされているということで、了解いたしました。ただ、実感として、そんなにないというか、やはり、スペースも取られていないところが、まだまだたくさんあるので、特に大井町など、本当にお母さん方が集まるような場所、買物をするようなところには、ぜひ早く設置していただけたらと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-063"},{"speaker":"松永委員","kind":"質問","question":"資料２の国の自転車活用推進法の平成２９年５月の６番目に、災害時の自転車の有効活用体制の整備と書いてありまして、品川区としては、どのような体制を取られているのかということを伺いたいと思います。そのようなことも含めて、自転車の在り方はとても大切に思っているのですけれども、例えば、自転車屋との連携など、区として、どのような整備をされているのかお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"災害時の関係、全般的なところは地域防災計画になるわけですが、その中で、地域との連携も含めて、自転車利用がどのように整理されているかということは、確認が必要ですが、今回の区の計画の中で、例えば、健康増進あるいは環境配慮的にもいい移動手段であるという流れの一環で。","voiceIndex":178,"id":"exchange-064"},{"speaker":"芹澤委員","kind":"質問・要望","question":"この前も質問をしたところですが、改めて自転車の違反の取締りというところで、もう一度お聞かせいただきたいのですが、改めてになりますけれども、電動自転車の違法改造について、警察署も非常に前向きに取り組んでいただいているとは思いますが、今後どのように取り締まっていくのか。","respondent":"工藤交通安全担当課長","answer":"今、委員ご説明のとおり、電動バイク、モペットのことだと思います。これは、扱い上は、原動機付自転車の扱いということで、今、実際に走っている電動バイクは、ナンバーもついていない、ミラーもないということで、簡単に言えば、違反になるわけです。","voiceIndex":181,"id":"exchange-065"},{"speaker":"芹澤委員","kind":"質問・要望","question":"確認で、電動キックボードに関しては、私も、アプリを入れて登録しましたが、たしか、本人確認は、免許証でした覚えがあります。事故に対する保険が、今、義務化されていて、区もいろいろ普及はしていただいていると思うのですが、これは、役割として、主に都がやるものなのですか。品川区でも入っている方が少ないような感覚があって、区のそこのご見解をお聞かせいただければと思います。","respondent":"工藤交通安全担当課長","answer":"ただ、そこまでやっているかどうかというところは、警察がどのようにやっているかということは、私は把握していないのですけれども、そのような対応になろうかと思います。２点目、保険の関係です。こちらは、区としまして、窓口になって、加入者の募集をしています。","voiceIndex":183,"id":"exchange-066"},{"speaker":"芹澤委員","kind":"質問・要望","question":"そのような意味でいうと、やはり義務化されながらも、任意ではないですけれども、区が確認できないというところで言えば、なかなか、まだ難しいと思っています。あれはバイクですから、あれでひかれてしまうと、本当に大きな事故になると思っていますので、その点だけ、ぜひ警察と強く連携を取っていただければと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-067"},{"speaker":"西村副委員長","kind":"質問・要望","question":"１点だけお伺いします。シェアサイクルです。ドコモだけではなく、区内にはソフトバンクのＨＥＬＬＯ ＣＹＣＬＩＮＧもありまして、確認させていただいたら、７ステーション、３８ラックあることが確認されました。こちらも、また、ドコモとは異なるポート間の移動を、区民の方がされていると思いますので、把握しておられましたら、お聞かせいただきたいと考えています。","respondent":"溝口土木管理課長","answer":"ほかの区を見ていますと、場合によっては、ドコモだけではなく、ソフトバンク系の運営会社等との連携を図っているところもあるようですから、今後、何か連携する機会があれば、周りの区の動向等も見ながら、その辺は、しっかり対応していければと考えているところです。","voiceIndex":187,"id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"資料３の１５ページのところで、年代別の事故発生件数割合が出ています。３０代の割合が下がっているのですが、分析はこれからということですけど、今の分析を伺えたらと思います。大体、事務局などで入っていらっしゃると思うのですが、このようなメンバーになった理由を伺いたいと思います。","respondent":"工藤交通安全担当課長、鈴木都市計画課長","answer":"１５ページ、図３５の年齢層別の事故の割合の関係です。こちらは、３０代の方が、令和元年から２年にかけて、減少しているです。検討体制の協議会のご質問です。","voiceIndex":190,"id":"exchange-069"},{"speaker":"横山委員","kind":"質問","question":"今の資料１のところで、一つ気になったことが、計画の位置づけのところで、品川区環境基本計画ですとか、しながわ健康プラン２１との整合・連携を取っていくというところで、こちらは、学識経験者の方が２名いらっしゃいますけれども、例えば、健康ですとか、環境の部門のご意見、学識経験等をお持ちなのかと思いましたが、ご専門はどのような形なのか。もし分かりましたら、教えてください。","respondent":"鈴木都市計画課長","answer":"単に自転車としての道路構造、道路交通法、駐輪対策などの視点だけではなくて、この方は、ほかの区や自治体の策定にも広く関わっていただいている方ですので、そのような健康や文化ですとか、そのような幅広い形での需要、自転車利用の在り方について、アドバイス、御提案。","voiceIndex":194,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、下流部シールドのほうは、変更ということで、何で変更になったのかというか、やはり、もともと、このようなことを計画することができなかったのかどうかというところを伺いたいと思います。今回、北品川の特殊人孔の整備は、もとから計画されていたものということでいいのかどうかというところも確認させていただきたいと思います。","respondent":"栗原河川下水道課長","answer":"受注者が地盤の状況等を適切に調査いたしまして、安全に工事を進めるために、懸念される事項につきましては、受注者と発注者が適切に協議をして、設計変更を行うことが必要であると考えているところです。","voiceIndex":203,"id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"泥土のところで、性状が、そのような産業廃棄物になっているということですが、どのような性状だと、産業廃棄物になるのかというところを伺いたいと思います。","respondent":"栗原河川下水道課長","answer":"建設現場から出てくる土に関しましては、建設発生土と、水や添加剤が含まれていることもあって、泥土として、産業廃棄物として出しているものがあります。基本的には水分を多く含むどろどろとした性状のものであれば、泥土として出していると認識しております。","voiceIndex":206,"id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4368#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":61168,"voices":213}}]);
